COLLDATA("tafsirnoor","ur",[[5161,"§قوم ثمود کی جانب صالح کو بھیجنے کا بیان\nاللہ کی قسم ! ہم نے قبیلہ ثمود کی جانب نسب کے لحاظ سے ان کے بھائی صالح کو رسول بناکر مبعوث فرمایا وہ انھیں اللہ کی توحید اور اس کی عبادت کی جانب دعوت دیتے رہے تو اس اثنا میں لوگ دو گروہوں میں تقسیم ہوگئے ایک گروہ مسلمانوں کا اور دوسرا گروہ کفار کا تھا ان کا باہمی جھگڑا اور اختلاف دین اسلام کے بارے میں تو تھا، توصالح علیہ السلام نے اپنی قوم کو نرمی کے ساتھ مخاطب کرتے ہوئے کہا کہ اے میری قوم کے لوگو تم اللہ کی رحمت طلب کرنے سے پہلے عذاب الٰہی کو کیوں جلدی طلب کررہے ہو، آخر سبب کیا ہے کہ تم رحمت کو طلب نہیں کررہے ہو، بلکہ عذاب الٰہی کو طلب کررہے ہو، تم شرک سے تائب ہو کر اللہ کے عذاب کو روکتے کیوں نہیں ہو ظاہر ہے کہ خیروبرکت کو جلدی طلب کرنا کسی مصیبت کے طلب کرنے سے کہیں زیادہ بہتر ہے۔\nانہوں نے کہا اے صالح علیہ السلام! ہم نحوست کی نسبت تیری جانب اور تیرے رفقاء کی جانب کرتے ہیں یقیناً تم اس مصیبت کا سبب بنے ہو اور تمہارے رفقاء میں ہم پر یہ مصیبت نازل ہوئی ہے مقصود قحط سالی کی مصیبت ہے جس کے باعث بھوک نے ان کے گھروں میں ڈیرے ڈال رکھے تھے صالح علیہ السلام نے انھیں آگاہ کیا حقیقت یہ ہے کہ تمہارا اچھائی یا برائی میں حصہ اللہ کے ساتھ بلکہ اللہ کے فیصلہ کے ساتھ ہے اگر وہ چاہے تو تمہیں رزق عطا کرے اور اگر وہ چاہے تو تمہیں محروم کردے۔"],[5162,"§سیّدنا صالح علیہ السلام کا اپنی قوم کو دعوت دینے کا بیان\nذہن نشین کریں کہ سیّدنا صالح علیہ السلام نے جب انھیں مخاطب کرکے اسلام کی دعوت دی تو اس دعوت میں لطافت کارفرما تھی لیکن جب انھوں نے جواب میں درشت لحجہ اختیار کیا اور کہا کہ ہم تجھے اور تیرے ساتھیوں کو منحوس باور کرتے ہیں تو اس پر انھوں نے ان کو آگاہ کیا کہ انھیں جو نحوست لاحق ہے وہ ان کی بداعمالیوں کا نتیجہ ہے اس کا سبب ہرگز نہ سیّدنا صالح علیہ السلام ہیں اور نہ ایماندار بلکہ حقیقت یہ کہ تم ایسی جماعت ہو جن کو شیطان نے وسوسے ڈال ڈال کر گمراہ کردیا ہے یہی وجہ ہے کہ تم غلط باتیں اپنی زبان سے نکال رہے ہو۔\n﴿وَكَانَ فِي الْمَدِيْنَةِ تِسْعَةُ رَهْطٍ يُّفْسِدُوْنَ فِي الْاَرْضِ وَلَا يُصْلِحُوْنَ۰۰۴۸ قَالُوْا تَقَاسَمُوْا بِاللّٰهِ لَنُبَيِّتَنَّهٗ۠ وَاَهْلَهٗ ثُمَّ لَنَقُوْلَنَّ لِوَلِيِّهٖ مَا شَهِدْنَا مَهْلِكَ اَهْلِهٖ وَاِنَّا لَصٰدِقُوْنَ۰۰۴۹ وَمَكَرُوْا مَكْرًا وَّمَكَرْنَا مَكْرًا وَّهُمْ لَا يَشْعُرُوْنَ۰۰۵۰ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ مَكْرِهِمْۙ اَنَّا دَمَّرْنٰهُمْ وَقَوْمَهُمْ اَجْمَعِيْنَ۰۰۵۱ فَتِلْكَ بُيُوْتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوْاؕ اِنَّ فِيْ ذٰلِكَ لَاٰيَةً لِّقَوْمٍ يَّعْلَمُوْنَ۰۰۵۲ وَاَنْجَيْنَا الَّذِيْنَ اٰمَنُوْا وَكَانُوْا يَتَّقُوْنَ۰۰۵۳﴾\nاور اس شہر میں نو سرغنے تھے، وہ زمین میں فساد پھیلاتے رہتے تھے اور اصلاح نہیں کرتے تھے⟦48⟧ انھوں نے کہا: تم آپس میں اللہ کی قسم کھائو کہ ہم ضرور صالح اور اس کے اہل خانہ پر شب خون ماریں گے، پھر ہم اس کے وارث سے کہیں گے کہ ہم اس کے گھر والوں کی ہلاکت کے وقت موجود نہ تھے اور بلاشبہ ہم سچے ہیں⟦49⟧ اور انھوں نے ایک چال چلی، اور ہم نے بھی تدبیر کی، اور وہ شعور بھی نہ رکھتے تھے⟦50⟧ پھر آپ دیکھیں! ان کی چال کا انجام کا کیا ہوا، بلاشبہ ہم نے ان (نو سرغنوں) کو اور ان کی سب قوم کو تباہ و برباد کر دیا⟦51⟧ چنانچہ یہ ہیں ان کے گھر خالی (اجڑے اور ویران) پڑے ہوئے، اس لیے کہ انھوں نے ظلم کیا، بلاشبہ اس میں نشان (عبرت) ہے ان لوگوں کے لیے جو جانتے ہیں⟦52⟧ اور ہم نے انھیں نجات دی جو ایمان لائے اور وہ (اللہ سے) ڈرتے تھے⟦53⟧"],[5163,"§فسادکرنے والے گروہ کی چال اور قوم ثمود کا انجام\nاللہ تعالیٰ نے قوم ثمود کے سرکشوں اور ان سرداروں کے بارے میں بیان فرمایا ہے کہ وہ اپنی قوم کو ضلالت، کفر اور صالح علیہ السلام کی تکذیب کی دعوت دیتے تھے اور ان کا کفر اور ظلم یہاں تک پہنچ گیا ہے کہ انھوں نے اونٹنی کو تو مار دیا اور یہ بھی ارادہ کیا کہ رات کو صالح علیہ السلام پر شب خون ماریں اور انھیں اچانک قتل کر دیں، پھر ان کے دوستوں اور رشتے داروں سے کہیں کہ انھیں تو اس واقعے کے بارے میں قطعاً علم نہیں اور وہ بالکل سچ کہہ رہے ہیں۔ اللہ تعالیٰ نے فرمایا ہے :﴿وَكَانَ فِي الْمَدِيْنَةِ﴾ ’’اور شہر میں تھے۔‘‘ یعنی شہر ثمود میں۔ ﴿تِسْعَةُ رَهْطٍ يُّفْسِدُوْنَ فِي الْاَرْضِ وَلَا يُصْلِحُوْنَ۰۰۴۸﴾ ’’نو شخص جو ملک میں فساد کیا کرتے تھے اور اصلاح سے کام نہیں لیتے تھے۔‘‘ اور یہ نوآدمی قوم ثمود پر غالب تھے کیونکہ یہ ان کے سردار اور بڑے لوگ تھے۔ عوفی رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ انھی لوگوں نے اونٹنی کو قتل کیا تھا۔(تفسیر ابن أبی حاتم : 2900/9وتفسیر الطبری : 210/19) یعنی اونٹنی کا قتل ان لوگوں کی رائے اور مشورے سے ہوا تھا، اللہ تعالیٰ ان پر لعنت فرمائے، ارشاد باری تعالیٰ ہے : ﴿فَنَادَوْا صَاحِبَهُمْ فَتَعَاطٰى فَعَقَرَ۰۰۲۹﴾ (القمر:29) ’’تو ان لوگوں نے اپنے رفیق کو بلایا، پس اس نے دست درازی کی، پھر اس کی کونچیں کاٹ ڈالیں۔ ‘‘اور فرمایا: ﴿اِذِ انْۢبَعَثَ اَشْقٰىهَا۪ۙ۰۰۱۲﴾ (الشمس:12) ’’جب اُن میں سے ایک نہایت بدبخت اُٹھا۔‘‘\nامام عبدالرزاق رحمہ اللہ نے کہا ہے کہ ہمیں یحییٰ بن ربیعہ صنعانی رحمہ اللہ نے یہ خبر دی کہ میں نے عطاء بن ابو رباح رحمہ اللہ کو یہ بیان کرتے ہوئے سنا :﴿وَكَانَ فِي الْمَدِيْنَةِ تِسْعَةُ رَهْطٍ يُّفْسِدُوْنَ فِي الْاَرْضِ وَلَا يُصْلِحُوْنَ۰۰۴۸﴾ ’’اور شہر میں نو شخص تھے جو ملک میں فساد کیا کرتے تھے اور اصلاح سے کام نہیں لیتے تھے۔‘‘ اس آیت میں مذکور لوگوں کا فساد یہ تھا کہ وہ درہموں کوکاٹ لیتے تھے۔(تفسیر عبدالرزاق : 480/2، رقم : 2171)یعنی ان میں سے کچھ لے لیتے تھے، گویا کہ ان کے ہاں بھی عربوں کی طرح لین دین میں درہموں کی تعداد کا نظام رائج تھا۔ امام مالک رحمہ اللہ نے یحییٰ بن سعید رحمہ اللہ سے اور انھوں نے سعید بن مسیب رحمہ اللہ سے روایت کیا ہے کہ سونے اور چاندی (درہم و دینار) کو کاٹ لینا بھی فساد فی الأرض ہے۔(الموطا للإمام مالک، حدیث : 1368) الغرض!ان کافروں اور فاسقوں میں خرابی کا ایک پہلو یہ بھی تھا کہ یہ زمین میں فتنہ وفساد برپا کرتے تھے۔ ان کے فتنہ و فساد کی کچھ صورتیں یہ تھیں جو ان ائمہ کرام نے بیان فرمائی ہیں اور کچھ اور صورتیں بھی تھیں۔ ارشاد باری تعالیٰ ہے : ﴿قَالُوْا تَقَاسَمُوْا بِاللّٰهِ لَنُبَيِّتَنَّهٗ۠ وَاَهْلَهٗ﴾ ’’کہنے لگے کہ اللہ کی قسم کھاؤ کہ ہم رات کو اس پر اور اس کے گھر والوں پر شب خون ماریں گے۔‘‘ یعنی قسم کھا کر اس بات کا عہد و پیمان کرو کہ ہم میں سے جس شخص کی بھی آج رات صالح علیہ السلام سے ملاقات ہوئی تو وہ انھیں قتل کر دے گا۔ اللہ تعالیٰ نے بھی ان کے خلاف ایک تدبیر کی اور سارا وبال انھی پر ڈال دیا۔ مجاہد رحمہ اللہ کہتے ہیں کہ انھوں نے بہت زور شور سے قسمیں کھائیں کہ وہ آپ کو ہلاک کر دیں گے مگر وہ آپ تک نہ پہنچ سکے، اللہ تعالیٰ نے انھیں اور ان کی ساری قوم کو ہلاک اور تباہ و برباد کر دیا۔ (تفسیر ابن أبی حاتم : 2901/9)\nامام عبدالرحمٰن بن زید رحمہ اللہ نے کہا ہے کہ جب انھوں نے اونٹنی کی کونچیں کاٹ دیں تو سیّدنا صالح علیہ السلام نے ان سے فرمایا: ﴿تَمَتَّعُوْا فِيْ دَارِكُمْ ثَلٰثَةَ اَيَّامٍؕ ذٰلِكَ وَعْدٌ غَيْرُ مَكْذُوْبٍ۰۰۶۵﴾ (ہود:65) ’’اپنے گھروں میں تین دن (مزید) فائدے اُٹھالو، یہ ایسا وعدہ ہے کہ جھوٹا نہ ہوگا۔‘‘انھوں نے کہا کہ صالح علیہ السلام کا گمان یہ ہے کہ وہ تین دن کے بعد ہمارا کام تمام کر دے گا ہم اس کا اور اس کے گھر والوں کا تین دن سے پہلے ہی کام تمام کر دیتے ہیں۔\nسیّدنا صالح علیہ السلام کی حجر میں گھاٹی کے پاس ایک مسجد تھی جس میں آپ نماز ادا فرمایا کرتے تھے، وہ لوگ رات کو غار میں چلے گئے اور کہنے لگے کہ وہ رات کو جب نماز پڑھنے کے لیے آئیں گے تو ہم انھیں قتل کر دیں گے اور ان کے قتل کے بعد واپس آکر ان کے گھر والوں کو بھی قتل کر دیں گے مگر اللہ تعالیٰ نے پہاڑ سے ان پر ایک چٹان بھیج دی، وہ ڈرے کہ یہ چٹان کہیں انھیں کچل ہی نہ ڈالے، انھوں نے جلدی سے بچاؤ کی صورت اختیار کرنا چاہی مگر چٹان گری تو اس سے غار کا منہ بند ہو گیا اور اب ان کی قوم کو ان کے بارے میں کوئی علم نہ تھا کہ وہ کہاں ہیں اور نہ انھیں یہ معلوم تھا کہ ان کی قوم کا کیا حشر ہوا ہے۔ اللہ تعالیٰ نے ان نو اشخاص کو یہاں غار میں عذاب میں مبتلا کر دیا اور قوم کے باقی لوگوں پر ان کے گھروں میں عذاب بھیج دیا اور سیّدنا صالح علیہ السلام اور آپ کے رفقاء کو نجات عطا فرمائی، یہ تفصیل بیان کرنے کے بعد امام عبدالرحمٰن بن زید رحمہ اللہ نے یہ آیات پڑھیں :﴿قَالُوْا تَقَاسَمُوْا بِاللّٰهِ لَنُبَيِّتَنَّهٗ۠ وَاَهْلَهٗ ثُمَّ لَنَقُوْلَنَّ لِوَلِيِّهٖ مَا شَهِدْنَا مَهْلِكَ اَهْلِهٖ وَاِنَّا لَصٰدِقُوْنَ۰۰۴۹﴾ ’’کہنے لگے کہ اللہ کی قسم کھاؤ کہ ہم ضرور رات کو اس پر اور اس کے گھر والوں پر شب خون ماریں گے، پھر ہم اس کے وارث سے کہیں گے کہ ہم اس کے گھر والوں کی ہلاکت کے وقت موجود نہ تھے اور بلاشبہ ہم سچے ہیں۔‘‘ (اور ابن ابی حاتم رحمہ اللہ میں حسب ذیل آیات کی تلاوت کا بھی ذکر ہے :) ﴿وَمَكَرُوْا مَكْرًا وَّمَكَرْنَا مَكْرًا وَّهُمْ لَا يَشْعُرُوْنَ۰۰۵۰ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ مَكْرِهِمْۙ اَنَّا دَمَّرْنٰهُمْ وَقَوْمَهُمْ اَجْمَعِيْنَ۰۰۵۱ فَتِلْكَ بُيُوْتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوْاؕ اِنَّ فِيْ ذٰلِكَ لَاٰيَةً لِّقَوْمٍ يَّعْلَمُوْنَ۰۰۵۲ وَاَنْجَيْنَا الَّذِيْنَ اٰمَنُوْا وَكَانُوْا يَتَّقُوْنَ۰۰۵۳﴾ ’’اور وہ ایک چال چلے اور ہم بھی ایک چال چلے اور ان کو کچھ خبر نہ ہوئی، چنانچہ دیکھیے کہ ان کی چال کا انجام کیا ہوا، ہم نے انھیں اور ان کی قوم سب کو ہلاک کر ڈالا، سو یہ ان کے گھر ان کے ظلم کے سبب خالی پڑے ہیں، جو لوگ دانش رکھتے ہیں ان کے لیے اس میں نشانی ہے اور جو لوگ ایمان لائے اور ڈرتے رہے، ہم نے ان کو نجات دی۔‘‘(تفسری الطبری : 212/19 وتفسیر ابن أبی حاتم : 2903/9)"],[5164,"§قوم ثمود کے نو غنڈہ سرغنے\nرھط بمعنی ایک ہی خاندان کے لوگوں کی مختصر سی جماعت جن کی تعداد دس سے کم ہو اور ان میں کوئی عورت نہ ہو۔ نیز اس کے جماعت کے سردار یا سرغنہ کو بھی رھط کہتے ہیں۔ (مفردات) اور یہ لفظ عموماً بُرے مفہوم میں استعمال ہوتا ہے۔ اور رھط کی اضافت کسی عدد کی طرف ہو تو اس سے اشخاص مراد لیے جاتے ہیں۔ (منجد) اسی لیے ہم نے رھط کا ترجمہ سرغنہ کیا ہے یعنی کسی اوباش اور بدکردار چھوٹی سی جماعت کا لیڈر۔\nقوم ثمود کی معروف بستی کا نام حجر ہے۔ اور اسے ام القریٰ بھی کہتے ہیں یہ مکہ سے شام جاتے ہوئے راستہ میں پڑتی ہے اسی شہر میں ایسے نو سرغنے تھے یا بدمعاش ٹائپ چوہدری تھے اور ان سب میں سر کردہ قدار تھا یعنی سب سے بڑا بدبخت اور حرامی یہی قدار ہی تھا جس نے اللہ کی اونٹنی کی کونچیں کاٹ ڈالی تھیں۔ اور باقی آٹھ سرغنے اسی قدار کے ممدو معاون ساتھی تھے۔"],[5165,"§قوم ثمود کے ان غنڈوں کی سازش\nجب ان لوگوں نے ملی بھگت سے قدار کو آگے لگا کر ناقة اللہ کو زخمی کردیا تو سیدنا صالح علیہ السلام نے ان لوگوں کو تین دن بعد عذاب آنے کا الٹی میٹم دے دیا۔ اس الٹی میٹم کے بعد بھی ان لوگوں نے یہی سمجھا کہ یہ عذاب تو آتا ہے یا نہیں۔ اس سے پہلے ہی ہم کیوں نہ صالح علیہ السلام اور اس کے گھر والوں کا قصہ بھی تمام کردیں۔ چنانچہ نو بدمعاشوں نے سیدنا صالح علیہ السلام کو بھی ٹھکانے لگا دینے کی ویسی ہی سکیم بنائی، جیسی قریش مکہ نے ہجرت سے پیشتر رسول اللہ صلی اللہ علیہ وسلم کا قصہ پاک کردینے کے لیے بنائی تھی۔ البتہ یہ فرق ضرور تھا کہ قریش نے یہ سمجھا کہ اس طرح بلوا کی صورت میں قتل کرنے پر ہم سے دیت کا مطالبہ کیا جائے گا تو وہ ہم آپس میں بانٹ لیں گے۔ لیکن یہ بدمعاش ان سے بھی چار ہاتھ آگے کی بات سوچ رہے تھے۔ ان کا خیال تھا کہ جب سیدنا صالح علیہ السلام کے ولی(جیسے رسول اللہ صلی اللہ علیہ وسلم کے ولی ابوطالب تھے) ہم سے کوئی بات پوچھیں گے تو ہم کہہ دیں گے کہ ہم تو موقع پر موجود ہی نہ تھے۔ ہمیں کیا خبر کہ کون ان کو قتل کر گیا ہے۔ اور دوسرا فرق یہ تھا کہ قریش مکہ نے صرف رسول اللہ صلی اللہ علیہ وسلم کو قتل کرنے کا منصوبہ تیار کیا تھا جبکہ ان بدمعاشوں نے سیدنا صالح علیہ السلام اور ان کے پورے خاندان کو مار ڈالنے کا منصوبہ بنایا تھا اور اپنے اس منصوبہ کے معاہدہ پر سب نے ایک دوسرے کے سامنے قسمیں کھائیں کہ ایک تو اس خاندان کو قتل کرکے دم لیں گے اور دوسرے اپنے جرم کا کبھی اعتراف نہ کریں گے۔"],[5166,"§ذکر قوم لوط\nیہاں لفظ ﴿تُبْصِرُوْنَ﴾ استعمال ہوا ہے جو دیکھنے کے معنوں میں استعمال ہوتا ہے اور سمجھنے کے معنوں میں بھی۔ اس لحاظ سے ان دو آیات کے کئی مطلب ہوسکتے ہیں: ایک یہ کہ تم خود بھی یہ سمجھتے ہو کہ یہ گندا اور بےحیائی کا کام ہے۔ اور خلاف فطرت ہے۔ حقیر سے حقیر جانور بھی ایسا کام نہیں کرتے تم اشرف المخلوقات ہونے کے باوجود ایسا کام کرتے ہو۔ دوسرا یہ کہ تم خوب سمجھتے ہو کہ اس کام کے لیے اللہ نے بیویاں پیدا کی ہیں۔ لیکن تم ان سے بےتعلق ہو کر مردوں سے ہی یہ کام کرتے ہو۔ تیسرے یہ کہ تم اس قدر بےحیا ہوچکے ہو کہ ایک دوسرے کی آنکھوں کے سامنے یہ کام کرتے ہو۔\nیعنی ہم نے مذکورہ نو سرداروں کو ہی نہیں، بلکہ ان کی قوم کو بھی مکمل طور پر ہلاک کر دیا۔ کیونکہ وہ قوم ہلاکت کے اصل سبب کفر و حجود میں مکمل طور پر ان کے ساتھ شریک تھی اور گوبالفعل ان کے منصوبۂ قتل میں شریک نہ ہو سکی تھی۔ کیونکہ یہ منصوبہ خفیہ تھا۔ لیکن ان کی منشا اور دلی آرزو کے عین مطابق تھا اس لیے وہ بھی گویا اس مکر میں شریک تھی جو نو افراد نے سیّدنا صالح علیہ السلام اور ان کے اہل کے خلاف تیار کیا تھا۔ اس لیےپوری قوم ہی ہلاکت کی مستحق قرار پائی۔\nسیّدنا صالح علیہ السلام کے شہر میں نوافراد ایسے تھے جن کا تعلق اونچی فیملی سے تھا، سورة الحجر میں بھی ان کا ذکرگزرچکا ہے ان کا مقصود اللہ کی زمین میں فساد انگیزی کو ہوا دینا تھا، اور ہر طرح سے اللہ کے بندوں کو تکالیف میں ڈالنا تھا۔"],[5167,"§سیّدنا ابن عباس رضی اللہ عنہما کا بیان\nاس سے مقصود وہ لوگ ہیں جنہوں نے اونٹنی کی کونچیں کاٹ دی تھیں انھوں نے آپس میں اللہ کی قسم اٹھاتے ہوئے کہا ہم صالح اور اس کے اہل خانہ کو رات کی تاریکی میں قتل کردیں گے پھر ہم اس کے خون کے متولی کو کہیں گے کہ ہم اس کی ہلاکت کی جگہ پر موجود نہ تھے اور ہمیں اس کے اور اس کے اہل و عیال کے قاتل کا ہرگز علم نہیں ہے اور ہم خود قسم اٹھاتے ہیں کہ ہم درست بات کہہ رہے ہیں، وہ لوگ صالح علیہ السلام کے گھرپہنچے تو وہ تلواروں کو فضا میں لہراتے رہے تھے تو اس کیفیت میں فرشتوں نے ان پر پتھروں کی بوچھاڑ کردی اور انھیں موت کے گھاٹ اتاردیا، اللہ فرماتے ہیں انھوں نے صالح علیہ السلام کے قتل کا منصوبہ بنایا اور ہم نے انھیں ان کے مکر کے باعث بدلہ دیا کہ انھیں تباہ و برباد کردیا انھیں ان کے ظلم وکفر کے باعث ہلاک کردیا اور اس واقعہ میں ان لوگوں کے لیے عبرت ہے جو اللہ کی قدرت کو عظیم گردانتے ہیں اور ایمان والوں کو ہم نے نجات عطا کی جو صالح پر ایمان لائے۔\n﴿وَلُوْطًا اِذْ قَالَ لِقَوْمِهٖۤ اَتَاْتُوْنَ الْفَاحِشَةَ وَاَنْتُمْ تُبْصِرُوْنَ۰۰۵۴ اَىِٕنَّكُمْ لَتَاْتُوْنَ الرِّجَالَ شَهْوَةً مِّنْ دُوْنِ النِّسَآءِؕ بَلْ اَنْتُمْ قَوْمٌ تَجْهَلُوْنَ۰۰۵۵ فَمَا كَانَ جَوَابَ قَوْمِهٖۤ اِلَّاۤ اَنْ قَالُوْۤا اَخْرِجُوْۤا اٰلَ لُوْطٍ مِّنْ قَرْيَتِكُمْۚ اِنَّهُمْ اُنَاسٌ يَّتَطَهَّرُوْنَ۠۰۰۵۶ فَاَنْجَيْنٰهُ وَاَهْلَهٗۤ اِلَّا امْرَاَتَهٗ١ٞؗ قَدَّرْنٰهَا مِنَ الْغٰبِرِيْنَ۰۰۵۷ وَاَمْطَرْنَا عَلَيْهِمْ مَّطَرًاۚ فَسَآءَ مَطَرُ الْمُنْذَرِيْنَࣖ۰۰۵۸ قُلِ الْحَمْدُ لِلّٰهِ وَسَلٰمٌ عَلٰى عِبَادِهِ الَّذِيْنَ اصْطَفٰىؕ آٰللّٰهُ خَيْرٌ اَمَّا يُشْرِكُوْنَ۰۰۵۹﴾\nاور (یاد کریں) لوط کو جب اس نے اپنی قوم سے کہا: کیا تم بے حیائی (بدکاری) کرتے ہو جبکہ تم دیکھتے ہو (کہ یہ بے حیائی ہے)⟦54⟧ کیا تم شہوت رانی کے لیے (اپنی) عورتوں کو چھوڑ کر مردوں کے پاس آتے ہو؟ بلکہ تم تو نادان لوگ ہو⟦55⟧ پھر اس کی قوم کا اس کے سوا کوئی جواب نہ تھا کہ انھوں نے کہا: آل لوط کو اپنی بستی سے نکال دو، کیونکہ یہ لوگ تو بڑے پاک صاف بنتے ہیں⟦56⟧ پھر ہم نے اسے اور اس کے اہل خانہ کو نجات دی، سوائے اس کی بیوی کے، ہم نے فیصلہ کر دیا تھا کہ وہ پیچھے رہنے والوں میں سے ہو گی⟦57⟧ اور ہم نے ان پر (پتھروں کی) سخت بارش برسائی، تو ڈرائے گئے لوگوں پر (پتھروں کی) بد ترین بارش برسائی گئی تھی۔⟦58⟧ (اے نبی!) کہہ دیجیے: تمام حمد اللہ ہی کے لیے ہے، اور اس کے ان بندوں پر سلام ہے جنھیں اس نے چن لیا، کیا اللہ بہتر ہے یا وہ جنھیں لوگ شریک ٹھہراتے ہیں؟⟦59⟧"],[5168,"§سیّدنا لوط علیہ السلام اور آپ کی قوم کا ذکر\nان آیات میں اللہ تعالیٰ نے اپنے بندے اور رسول سیّدنا لوط علیہ السلام کا ذکر فرمایا ہے کہ انھوں نے اپنی قوم کو ایسی فحاشی کی وجہ سے جس کا ان سے پہلے کسی انسان نے ارتکاب نہیں کیا تھا، عذاب الٰہی سے ڈرایا۔ آپ کی قوم عورتوں کو چھوڑ کر مردوں سے لذت حاصل کرتی تھی۔ اور یہ زبردست فحاشی ہے کہ مرد مردو ں سے اور عورتیں عورتوں سے اپنی جنسی ضرورت پوری کریں۔ آپ نے قوم سے مخاطب ہوتے ہوئے فرمایا:﴿اَتَاْتُوْنَ الْفَاحِشَةَ وَاَنْتُمْ تُبْصِرُوْنَ۰۰۵۴﴾ ’’کیا تم بے حیائی کرتے ہو جبکہ تم دیکھتے ہو ؟‘‘ یعنی تم ایک دوسرے کے سامنے اپنی مجلسوں میں بدکاری کا ارتکاب کرتے ہو۔ ﴿اَىِٕنَّكُمْ لَتَاْتُوْنَ الرِّجَالَ شَهْوَةً مِّنْ دُوْنِ النِّسَآءِؕ بَلْ اَنْتُمْ قَوْمٌ تَجْهَلُوْنَ۰۰۵۵﴾ ’’کیا تم عورتوں کو چھوڑ کر لذت (حاصل کرنے) کے لیے مردوں کے پاس آتے ہو؟ حقیقت یہ ہے کہ تم ایسے لوگ ہو کہ جہالت برتتے ہو۔ ‘‘ تم طبعاً اور شرعًا کچھ نہیں جانتے۔\nجیسا کہ دوسری آیت میں فرمایا:﴿اَتَاْتُوْنَ الذُّكْرَانَ مِنَ الْعٰلَمِيْنَۙ۰۰۱۶۵ وَتَذَرُوْنَ مَا خَلَقَ لَكُمْ رَبُّكُمْ مِّنْ اَزْوَاجِكُمْؕ بَلْ اَنْتُمْ قَوْمٌ عٰدُوْنَ۰۰۱۶۶﴾ (الشعرآئ:165-166) ’’کیا تم اہل عالم میں سے لڑکوں کے پاس آتے ہو اور تمہارے پروردگار نے تمہارے لیے تمہاری بیویاں پیدا کی ہیں ان کو چھوڑ دیتے ہو۔حقیقت یہ ہے کہ تم حد سے نکل جانے والے لوگ ہو۔‘‘﴿فَمَا كَانَ جَوَابَ قَوْمِهٖۤ اِلَّاۤ اَنْ قَالُوْۤا اَخْرِجُوْۤا اٰلَ لُوْطٍ مِّنْ قَرْيَتِكُمْۚ اِنَّهُمْ اُنَاسٌ يَّتَطَهَّرُوْنَ۠۰۰۵۶﴾ ’’تو اس کی قوم کا اس کے سوا کچھ جواب نہ تھا کہ انھوں نے کہا: لوط کے گھر والوں کو اپنے شہر سے نکال دو، یقیناً یہ لوگ پاک بننا چاہتے ہیں۔‘‘ یعنی تم جو کام کرتے ہویہ اس سے بڑے اہتمام سے بچتے ہیں اور اس کارگزاری پر تمہارے برقرار رہنے کو بھی درست نہیں سمجھتے، لہٰذا انہیں اپنے ہاں سے نکال دو، وہ تمہارے علاقوں میں تمہارے ساتھ رہنے کے قابل نہیں ہیں، بنا بریں انھوں نے ان کو نکال دینے کا پختہ ارادہ کر لیا مگر اللہ تعالیٰ نے ان کو تباہ و برباد کردیا اور ان کفار کے لیے بھی اس جیسی (سزائیں) ہیں۔"],[5169,"§اللہ تعالیٰ کی حمد اور رسولوں علیہم السلام پر سلام بھیجنے کا حکم\nاللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو حکم دیا ہے کہ آپ کہیں : ﴿الْحَمْدُ لِلّٰهِ﴾ یعنی سب طرح کی تعریف اللہ تعالیٰ ہی کے لیے ہے کہ اس نے اپنے بندوں کو ان گنت اور بے شمار نعمتوں سے نوازا ہے اور اس لیے بھی کہ اس کی ذات پاک صفات علیا اور اسمائے حسنٰی سے متصف ہے۔ اللہ تعالیٰ نے یہ بھی حکم دیا ہے کہ آپ اللہ تعالیٰ کے ان بندوں پر سلام بھیجیں جنھیں اللہ تعالیٰ نے منتخب فرمایا ہے، ان بندوں سے مرسلین و انبیائے کرام علیہم السلام مراد ہیں۔ عبدالرحمٰن بن زید بن اسلم و غیرہ کا بھی یہی قول ہے کہ اللہ تعالیٰ کے منتخب بندوں سے انبیائے کرام علیہم السلام مراد ہیں۔ (تفسیر ابن ابی حاتم: 2906/9) اور یہ آیت کریمہ اس طرح ہے جیسا کہ اللہ تعالیٰ نے فرمایا ہے:﴿سُبْحٰنَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُوْنَۚ۰۰۱۸۰ وَسَلٰمٌ عَلَى الْمُرْسَلِيْنَۚ۰۰۱۸۱ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِيْنَࣖ۰۰۱۸۲﴾ (الصافات : 180 تا 182) ’’یہ جو کچھ بیان کرتے ہیں آپ کا پروردگار جو عزت والا ہے اس سے پاک ہے اور پیغمبروں پر سلام، سب طرح کی تعریف اللہ رب العالمین ہی کے لیے ہے۔‘‘\nثوری رحمہ اللہ اور سدی رحمہ اللہ کہتے ہیں کہ اس سے مراد اصحاب محمد صلی اللہ علیہ وسلم ہیں۔ (تفسیر الطبری : 4/20، تفسیر ابن ابی حاتم : 2906/9) اللہ ان تمام سے راضی ہو۔ اور سیّدنا ابن عباس رضی اللہ عنہما سے بھی اسی طرح مروی ہے۔ (تفسیر ابن ابی حاتم: 2906/9 و تفسیر الطبری : 4/20) اور ان دونوں اقوال میں کوئی تضاد نہیں کیونکہ اگر صحابہ کرام رضی اللہ عنہم اللہ تعالیٰ کے منتخب بندوں میں سے ہیں تو حضرات انبیائے کرام علیہم السلام بالاولیٰ ان بندوں میں سے ہیں جن کو اللہ تعالیٰ نے منتخب فرمایا ہواہے: ﴿آٰللّٰهُ خَيْرٌ اَمَّا يُشْرِكُوْنَ۰۰۵۹﴾ ’’بھلا اللہ بہتر ہے یا وہ جن کو یہ (اس کا) شریک بناتے ہیں۔‘‘ یہ مشرکین کے اللہ کے ساتھ دیگر معبودانِ باطلہ کی عبادت کرنے کے بارے میں استفہامِ انکار ہے۔\nیعنی کہہ دیجیے ﴿اَلْحَمْدُلِلّٰہِ﴾ ’’ حمد و ستائش اللہ ہی کے لیے ہے ‘‘ جو اپنے کمال اوصاف، اپنے جمال عطا و بخشش، اہل تکذیب کو سزا دینے اور ظالموں کو عذاب دینے میں عدل و حکمت کی بنا پر کامل حمد و ستائش اور مدح وثناء کا مستحق ہے نیز اس کے بندوں انبیاء ومرسلین پر سلام بھیجے جن کو اس نے تمام جہانوں میں سے منتخب فرمایا جو رب کائنات کے چنے ہوئے اور محبوب بندے تھے اور یہ اس لیے ہے تاکہ ان کا ذکر اور ان کی تعظیم اور زیادہ ہو نیز اس لیے بھی کہ وہ شر اور گندگی سے پاک ہیں، اپنے رب کے بارے میں جو کہتے ہیں وہ نقائص و عیوب سے محفوظ ہے۔ ﴿آٰللّٰہُ خَیْرٌ اَمَّا یُشْرِکُوْنَ﴾ ’’بھلا اللہ بہتر ہے یا جن کو یہ شریک ٹھہراتے ہیں؟‘‘ یہ استفہام محقق اور معروف ہے، یعنی اللہ، رب عظیم، جو کامل اوصاف اور عظیم الطاف کا مالک ہے، بہتر ہے یا یہ اصنام واوثان بہتر ہیں، جن کی یہ اللہ تعالیٰ کے ساتھ عبادت کرتے ہیں، جو ہر لحاظ سے ناقص ہیں جو کوئی نفع دے سکتے ہیں نہ نقصان، جو خود اپنے لیے اور اپنے عبادت گزاروں کے لیے ذرہ بھر بھلائی کے مالک نہیں۔ پس اللہ تعالیٰ ان ہستیوں سے بہتر ہے جن کو یہ اللہ تعالیٰ کا شریک ٹھہراتے ہیں۔\nمجرموں کی ہلاکت اور مومنوں کی نجات کی خبر دینے کے بعد، اللہ تعالیٰ نے نبی کریم صلی اللہ علیہ وسلم کو حکم دیا کہ وہ اس نعمت پر اپنے رب کا شکر ادا کریں، اور امت محمدیہ کو تعلیم دی ہے کہ جب بھی انھیں اللہ کی کوئی نعمت حاصل ہو تو وہ اپنے رب کا شکر بجا لائیں جس نے اپنے فضل سے انھیں وہ نعمت دی ہے۔\nاس آیت کریمہ میں اللہ تعالیٰ نے نبی کریم صلی اللہ علیہ وسلم اور آپ کی امت کو یہ تعلیم دی ہے کہ دعوت کے میدان میں جب سامعین کے سامنے کوئی تقریر کرنی چاہیں یا کوئی تحریر پیش کریں تو اللہ کی برکت حاصل کرنے کے لیے اس کا آغاز اللہ کی حمد و ثنا اور انبیائے کرام علیہم السلام جو اللہ کے برگزیدہ بندے ہیں ان پر درود وسلام سے کریں۔ اسی لیے نبی کریم صلی اللہ علیہ وسلم کے زمانے سے ہر دور میں علماء خطباء اور واعظین کا یہی طریقہ رہا ہے۔\nنیز اس آیت میں اللہ تعالیٰ نے نبی کریم صلی اللہ علیہ وسلم کو حکم دیا کہ وہ اللہ کی حمد و ثنا اور انبیائے کرام علیہم السلام پر درود وسلام کے بعد، مشرکین مکہ سے پوچھیں کہ اللہ بہتر ہے، یا وہ معبودان باطل جنہیں وہ اللہ کے ساتھ شریک ٹھہراتے ہیں، ظاہر ہے کہ ان معبودانِ باطل میں کوئی خیر نہیں ہے، اور یہ بات کفار مکہ کو معلوم ہے، اور پھر بھی وہ انہی کی عبادت کرتے ہیں۔ یہ کیسی بےعقلی، کیسی جہالت اور کیسی نفس پرستی ہے ؟ یہ جانتے ہوئے کہ ان میں کوئی بھلائی نہیں ہے، پھر بھی انھیں اپنا معبود مانتے ہیں، ان پر چڑھاوے چڑھاتے ہیں، اور ان کے سامنے سر ٹیکتے ہیں۔"],[5170,"§لواطت کے نتائج\nیعنی تم اس لواطت کے انجام سے آگاہ نہیں اس کا انجام یہ ہوگا کہ چند ہی سالوں بعد تمہاری نسل ختم ہوجائے گی نیز تمہاری عورتوں میں فحاشی پھیل جائے گی۔ یا تم اس فعل کے اس انجام سے بےخبر ہو کہ اس کے نتیجہ میں اللہ کا عذاب تم پر نازل ہو۔"],[5171,"§بستی سے نکالنے کی دھمکی\nبجائے اس کے کہ وہ سیدنا لوط علیہ السلام کی نصیحت پر کچھ اپنی اصلاح کرتے وہ اوچھے ہتھکنڈوں پر اُتر آئے۔ سیّدنا لوط علیہ السلام اور ان کے متبعین کو از راہ تمسخر پاکبازی کا طعنہ دیں۔ پھر انھیں اپنے شہر سے نکال دینے کی دھمکی بھی دینے لگے کہ تم جیسے پاکباز ہم گندے لوگوں میں کیونکر رہ سکتے ہیں۔ لہٰذا تمہاری عافیت اسی میں ہے کہ یہاں سے چلے جاؤ۔\nاس سورة میں تین انبیاء سیدنا سلیمان، سیدنا صالح اور سیدنا لوط علیہم السلام کے حالات کا ذکر ہوا ہے۔ اور ان کے حالات میں اور رسول اللہ صلی اللہ علیہ وسلم کے حالات میں کوئی نہ کوئی مشابہت کا پہلو ضرور پایا جاتا ہے۔ مثلاً سیدنا سلیمان علیہ السلام نے ملکہ سبا کو یہ چیلنج کیا تھا کہ اگر تم مطیع فرمان بن کر حاضر ہوجاؤ تو بہتر ورنہ ہم ایسے لشکر سے تم پر حملہ کریں گے جس کے مقابلہ کی تم تاب نہ لاسکو گے۔ چنانچہ فتح مکہ کے موقع پر رسول اللہ صلی اللہ علیہ وسلم مشرکینِ مکہ پر ایسا ہی لشکر لائے تھے۔ جس کے مقابلہ کی ان میں تاب نہ تھی۔ سیدنا صالح علیہ السلام کو ان کی قوم نے بلوا کی صورت میں شبخون مار کر قتل کرنا چاہا تھا۔ لیکن اللہ نے انھیں نجات دی۔ قریش مکہ نے بھی آپ سے یہی سلوک کرنا چاہا تھا مگر اللہ تعالیٰ نے آپ کو ان کی اس سازش سے بال بال بچالیا۔ سیدنا لوط علیہ السلام کو ان کی قوم نے شہر سے نکال دینے کی دھمکیاں دیں۔ جبکہ قریش مکہ نے رسول اللہ صلی اللہ علیہ وسلم کو عملاً شہر مکہ سے نکل جانے پر مجبور کردیا تھا۔"],[5172,"§الحمدللہ کے استعمال کا خاص موقع\nویسے تو ہر حال میں اللہ کی تعریف بیان کرنا چاہیے اور اس کا شکر بجا لانا چاہیے۔ لیکن اہل عرب اس جملہ کا استعمال عموماً اس وقت کرتے ہیں۔ جب فریق مخالف یا مخاطب پر دلائل کے ساتھ اتمام حجت کردی جائے اور اس کے پاس ان دلائل کا کوئی معقول جواب نہ ہو یا اسے کوئی معقول جواب میسر نہ آئے۔ یہاں بھی تین انبیاء علیہم السلام کا ذکر کرنے اور منکرین حق کا ایک ہی جیسا انجام بتلانے کے بعد یہ جملہ اسی مفہوم کو ادا کرنے کے لیے استعمال ہوا ہے۔"],[5173,"§قوم لوط کے احوال اور ان پر عذاب نازل کرنے کا بیان\nآپ ہمارے پیغمبر سیّدنا لوط علیہ السلام کا تذکرہ کریں جب اس نے اپنی قوم سدوم بستی کے لوگوں کو مخاطب کرکے کہا تعجب ہے کہ تم نہایت ہی قبیح برے فعل کے مرتکب ہورہے ہو کہ تم لڑکوں سے اپنی شہوت نفسانی کو پورا کرتے ہو مقصود لواطت کا شنیع فعل ہے اس سے دور رہو، اور مرد لوگ مردوں کے ساتھ ہی بےحیائی کے مرتکب ہورہے ہیں، بلکہ تم بیوقوف بےشرم لوگ ہو اسی لیے تم اس مذموم فعل کو اس پر ترجیح دیتے ہو جس کو اللہ نے تمہارے لیے حلال قرار دیا ہے مقصود عورتوں کے ساتھ جائز طریق اختیار کرتے ہوئے خواہش نفسانی کو تسکین دینا ہے۔\nلیکن سیّدنا لوط علیہ السلام کی قوم نے ان کو جواب دیتے ہوئے کہا کہ تم سیّدنا لوط علیہ السلام اور ان کے اہل و عیال کو اپنے شہر سے نکال دو جب کہ یہ لوگ لڑکوں سے دور رہتے ہیں اور ہمارے لواطت کے فعل کو گندگی باور کرتے ہیں ان کا یہ انداز اس لائق ہے کہ انھیں شہر سے دیس نکالا دیا جائے۔ قتادہ رحمہ اللہ وضاحت کرتے ہوئے کہتے ہیں کہ لوط کی قوم نے ایمان والوں کو معیوب قرار دیا جب کہ ان میں ہرگز عیب نہ تھا ان کے نزدیک ان میں یہ عیب تھا کہ وہ خود کو لواطت کے مذموم فعل سے دور رکھتے تھے۔\nجب کہ سیّدنا عبداللہ بن عباس رضی اللہ عنہما نے ان کے انداز کو مزاحیہ قرار دیتے ہوئے واضح کیا ہے کہ یہ لوگ عجیب ہیں کہ وہ خود کو لڑکوں کی دبرزنی سے پاکیزہ قرار دیتے ہیں چنانچہ جب اللہ پاک کا عذاب قوم لوط پر واقع ہواتوہم نے سیّدنا لوط علیہ السلام اور ان کے اہل و عیال کو اس عذاب سے تحفظ عطا کیا جس کو قوم پر اتارا تھا البتہ سیّدنا لوط علیہ السلام کی بیوی کو عذاب خداوندی کی لپیٹ میں گرفتار کرکے ہلاک کردیا گیا اس لیے کہ ہماری نوشتہ تقدیر میں اس کی ہلاکت کا فیصلہ ہوچکا تھا اور ہم نے ان پر پتھروں کی بارش کی یعنی جس طرح بارش گرتی ہے اس طرح ان پر پتھر گرتے رہے ان کے سبب انھیں تباہ و برباد کردیا گیا چنانچہ پتھروں کی بارش کا یہ عذاب نہایت ہی برا تھا، جب کہ پتھر ترتیب کے ساتھ ان پر بےتحاشا بارش کے قطرات کی طرح گرتے رہے۔\nقُلِ الْحَمْدُ لِلّٰهِ وَ سَلٰمٌ عَلٰى عِبَادِهِ الَّذِيْنَ اصْطَفٰى: اے محمد صلی اللہ علیہ وسلم آپ کہیں کہ سب تعریفیں اللہ کی ذات کے لیے ہیں جس نے انعامات کو ہم پر اتارا اور اس کے ان بندوں پر سلام ہو جنہیں منصب رسالت پر فائز فرمایا اور اپنی دعوت کو پہنچانے کے لیے ان کا انتخاب فرمایا علامہ زمخشری رحمہ اللہ بیان کرتے ہیں کہ اللہ تعالیٰ نے اپنے پیغمبر کو حکم دیا کہ آپ ان پر ایسی آیات کی تلاوت کریں جس میں اللہ کی وحدانیت کا اظہار واضح ہے جن میں اللہ کی قدرت اور اس کی حکمت پر دلائل کی بارش ہورہی ہے نیز آپ آغاز میں اللہ کی حمدوثنا کریں اس کے بعد انبیاء علیہم السلام پر سلام بھیجیں نہایت عمدہ ادب کی تلقین ہے کہ اوّلاً اللہ کی حمد کو بیان کیا جائے اور بعدازاں پیغمبروں کو سلام بھیجا جائے اس کے بعد معلومات سے آگاہ کیا جائے۔\nآٰللّٰهُ خَيْرٌ اَمَّا يُشْرِكُوْنَ: مشرکین کو ڈانٹ پلائی ہے اور ان سے مزاح کیا ہے تم ہی بتاؤ کہ اللہ جو خالق ہے بلا نمونہ پیدا کرنے والا ہے حکمت والا ہے، وہ بہتر ہے یاپتھر بہتر ہیں جن کی تم عبادت کرتے ہو ؟\n(صفوۃ التفاسیر القسم الحادی عشرص 17)"],[5174,"§توحید کے چند ایک دلائل\n﴿اَمَّنْ خَلَقَ السَّمٰوٰتِ وَالْاَرْضَ وَاَنْزَلَ لَكُمْ مِّنَ السَّمَآءِ مَآءًۚ فَاَنْۢبَتْنَا بِهٖ حَدَآىِٕقَ ذَاتَ بَهْجَةٍۚ مَا كَانَ لَكُمْ اَنْ تُنْۢبِتُوْا شَجَرَهَاؕ ءَاِلٰهٌ مَّعَ اللّٰهِؕ بَلْ هُمْ قَوْمٌ يَّعْدِلُوْنَؕ۰۰۶۰﴾\n(کیا یہ معبودانِ باطلہ بہتر ہیں) یا وہ (اللہ) جس نے آسمانوں اور زمین کو پیدا کیا اور تمھارے لیے آسمان سے پانی اتارا؟ پھر ہم نے اس سے ایسے پر رونق باغ اگائے جن کے درخت اگانے کی تمھیں قدرت نہ تھی، کیا اللہ کے ساتھ کوئی (اور) معبود ہے؟ بلکہ\n(یہ) وہ لوگ ہیں جو (غیر اللہ کو اللہ کے) برابر ٹھہراتے ہیں⟦60⟧\nاس کے بعد اللہ تعالیٰ نے یہ بیان شروع فرمایا ہے کہ صرف اور صرف وہی خالق، رازق اور مدبر ہے، اس کے سوا اور کسی کے اختیار میں یہ امور نہیں ہیں، چنانچہ ارشاد باری تعالیٰ ہے: ﴿اَمَّنْ خَلَقَ السَّمٰوٰتِ وَالْاَرْضَ﴾ ’’بھلا کس نے آسمانوں اور زمین کو پیدا کیا؟‘‘ یعنی کس نے ان بلند و بالا اور صاف و شفاف آسمانوں کو پیدا فرمایا اور انہیں روشن اور چمکدار ستاروں اور گردش کرنے والے افلاک سے مزین کیا، پھر اس نے زمین کو پیدا فرما کر اس کی موٹی تہ بچھا دی اور اس میں اس نے پہاڑوں، ٹیلوں، میدانوں، غاروں، جنگلوں، صحراؤں، فصلوں، درختوں، پھلوں، دریاؤں، سمندروں، اور مختلف قسموں، شکلوں اور رنگوں کے جانوروں وغیرہ کو پیدا فرمایا؟\n﴿وَاَنْزَلَ لَکُمْ مِّنَ السَّمَآءِ مَآءً﴾ ’’ اور (کس نے) تمہارے لئے آسمان سے پانی برسایا؟‘‘ اور اسے بندوں کے لئے رزق بنایا؟ ﴿فَاَنْۢبَتْنَا بِهٖ حَدَآىِٕقَ ذَاتَ بَهْجَةٍۚ﴾ ’’پھر ہم نے اس سے سر سبز باغ اُگائے۔‘‘ جن کے منظر بہت حسین اور جن کی شکلیں بہت خوبصورت ہیں۔ ﴿مَا كَانَ لَكُمْ اَنْ تُنْۢبِتُوْا شَجَرَهَاؕ﴾ ’’تمہارا کام تو نہ تھا کہ تم اس کے درختوں کو اُگاتے۔‘‘ تم تو درختوں کے اگانے پر قادر نہ تھے، قادر تو وہ خالق و رازق ہے جو مستقل طور پر خالق و رازق ہے اور ان صفات میں منفرد ہے۔ اس کے سو اکوئی بت یا کوئی شریک اس پر قادر نہیں ہے۔ اور خود مشرکین کو بھی اس کا اعتراف تھا جیسا کہ اللہ تعالی نے دوسری آیت میں فرمایا ہے: ﴿وَلَىِٕنْ سَاَلْتَهُمْ مَّنْ خَلَقَهُمْ لَيَقُوْلُنَّ اللّٰهُ﴾ (الزخرف: 87) ’’اور اگر آپ ان سے پوچھیں کہ ان کو کس نے پیدا کیا ہے تو کہہ دیں گے کہ اللہ نے۔‘‘\nمعبودانِ باطل کی عمومی نفی کرنے کے بعد اللہ تعالیٰ نے اپنی قدرت مطلقہ کی مثالیں دے کر مشرکین مکہ سے الزامی سوال کیا ہے کہ بتاؤ یہ کس کی قدرت کا کرشمہ ہے ان چیزوں کو کس نے پیدا کیا ہے یہ نعمتیں کس نے دی ہیں ؟ اور جب ہر سوال کا جواب تمہارے پاس سوائے اس کے کچھ نہیں کہ یہ سب اللہ کی کرشمہ سازی ہے تو پھر تم اسے چھوڑ کر دوسروں کو اپنا معبود کیوں بناتے ہو؟\nاللہ تعالیٰ نے مشرکین مکہ سے پہلا الزامی سوال یہ کیا کہ ان آسمانوں اور زمین کو کس نے پیدا کیا ہے اور آسمان سے تمہارے لیے بارش کس نے نازل کی ہے ؟ جس کے ذریعہ ہم نے تمہارے لیے خوبصورت باغات اگائے ہیں، تم ان درختوں کو اگانے کی طاقت نہیں رکھتے تھے۔ ظاہر ہے اس کے سوا کوئی جواب نہیں کہ یہ سارے کام اللہ کے ہیں۔ تو پھر تم کیوں اللہ کے سوا کسی اور کی پرستش کرتے ہو ؟\nدوسرا سوال یہ کیا کہ اس زمین کو تمہارے لیے قرار کی جگہ کس نے بنائی ہے کہ وہ الٹتی نہیں ہے اور تم آرام سے اس پر زندگی گزارتے ہو اور زمین پر نہریں کس نے جاری کی ہیں اور اس پر پہاڑ کس نے جما دیئے تاکہ حرکت نہ کرے، اور میٹھے اور کھارے پانی کے درمیان رکاوٹ کس نے کھڑی کی ہے کہ وہ ایک دوسرے سے نہیں ملتے ہیں۔ اس کے سوا تمہارے پاس کوئی جواب نہیں کہ یہ سب اللہ کی قدرت کے کرشمے ہیں، تو پھر تم کیوں اس کے سوا کسی اور کو اپنا معبود بناتے ہو ؟\nتیسرا سوال یہ کیا کہ جب انسان کو کوئی پریشانی لاحق ہوتی ہے کسی مرض میں مبتلا ہوتا ہے یا کسی مصیبت میں گرفتار ہوجاتا ہے یا کسی ظالم کے ہتھے چڑھ جاتا ہے تو وہ بےتحاشا کسے پکارتا ہے اور کون ہے جو اس کی فریاد رسی کرتا ہے اور اس کی مصیبت کو دور کردیتا ہے ؟ اور کون ہے جو کچھ کو موت دیتا رہتا ہے اور ان کی نسلوں کو زمین کا وارث بناتا رہتا ہے ؟ جواب معلوم ہے کہ وہ اللہ ہے۔ تو اے مشرکین مکہ ! پھر کیوں تم اسے چھوڑ کر معبودان باطل کے سامنے سربسجود ہوتے ہو ؟ حقیقت یہ ہے کہ تم لوگ بہت ہی کم نصیحت حاصل کرتے ہو۔\nمضطر کی دعا کی مناسبت سے حافظ ابن القیم رحمہ اللہ نے اپنی کتاب الجواب الکافی میں لکھا ہے کہ اگر دعا کرتے وقت پورے طور حضور قلب حاصل ہو، اپنی حاجت و ضرورت کا شدید احساس ہو اور رب العالمین کے حضور انتہائی عاجزی و انکساری اور غایت درجہ کا خشوع و خضوع حاصل ہو اور دل پر رقت طاری ہو اور اس حال میں بندہ اپنے رب کے پاکیزہ ناموں اور اعلیٰ صفات کو وسیلہ بنا کر دعا کرے تو ایسی دعا شاید ہی رد کی جاتی ہے۔\nچوتھا الزامی سوال اللہ نے مشرکین سے یہ کیا کہ صحرا اور سمندر کی تاریکیوں میں تمہاری کون رہنمائی کرتا ہے، اور کون بارش برسانے سے پہلے ہواؤں کو بھیجتا ہے، جن سے لوگ سمجھ لیتے ہیں کہ اب بارش ہوگی، کون ان باتوں پر قادر ہے ؟ جواب معلوم ہے کہ وہ اللہ ہے تو پھر کیوں تم لوگ اس کے ساتھ غیروں کو شریک بناتے ہو، اللہ تمہارے ان جھوٹے معبودوں سے بہت ہی برتر وبالا ہے۔\nپانچواں سوال یہ کیا کہ وہ کون ہے جس نے انسانوں کو پہلی بار پیدا کیا ہے اور قیامت سے پہلے پھر سے انہیں دوبارہ زندہ کرے گا، اس کا جواب اس کے سوا کچھ بھی نہیں (تم چاہے مانو یا نہ مانو) کہ وہ اللہ کی ذات ہے جو انہیں دوبارہ زندہ کرے گا اور کون ہے جو آسمان سے بارش برسا کر اور زمین سے پودے اگا کر تمہیں روزی دیتا ہے ؟ جواب معلوم ہے کہ وہ اللہ کی ذات ہے جو اس کی قدرت رکھتا ہے، تو پھر تم جو اس کے ساتھ غیروں کو شریک بناتے ہو اور دعویٰ کرتے ہو کہ تم سچے ہو تو اپنی صداقت کی کوئی عقلی یا نقلی دلیل پیش کر کے دکھاؤ۔\nآخر میں اللہ تعالیٰ نے مشرکین مکہ سے الزامی بات یہ کہی کہ غیبی امور کا علم آسمانوں اور زمین میں رہنے والی مخلوقات میں سے کسی کو نہیں ہے ان کا علم صرف اللہ کو ہے۔ جیسا کہ اللہ نے سورة الانعام آیت (59) میں فرمایا ہے :﴿وَعِنْدَهٗ مَفَاتِحُ الْغَيْبِ لَا يَعْلَمُهَاۤ اِلَّا هُوَؕ﴾ اور اللہ ہی کے پاس غیب کی کنجیاں ہیں، ان کو اس کے سوا کوئی نہیں جانتا۔ اس لیے اس کی ذات معبود برحق ہے اور تمہارے معبود چونکہ غیب کا کوئی علم نہیں رکھتے ہیں اس لیے وہ معبود نہیں ہوسکتے، کیونکہ معبود برحق کو تمام غیبی امور کا علم ہونا چاہیے تاکہ وہ دونوں جہان اور ان میں پائی جانے والی تمام کائنات کی دیکھ بھال کرسکے۔\nبخاری و مسلم اور ترمذی رحمہم اللہ نے عائشہ سے روایت کی ہے، انہوں نے کہا جس نے یہ دعوی کیا کہ وہ لوگوں کو کل کی خبر بتاتا ہے، اس نے اللہ پر بہت بڑی افترا پردازی کی، اللہ تو کہتا ہے : ﴿قُلْ لَّا يَعْلَمُ مَنْ فِي السَّمٰوٰتِ وَالْاَرْضِ الْغَيْبَ اِلَّا اللّٰهُؕ﴾ آسمانوں اور زمین میں رہنے والی مخلوقات میں سے کوئی بھی غیب کی باتیں نہیں جانتا، انہیں صرف اللہ جانتا ہے۔\nاس الزامی بات کی ایک اہم کڑی یہ ہے کہ قیامت کب آئے گی اور قبروں سے مردے کب اٹھائے جائیں گے اس کا علم بھی اللہ کے سوا کسی کو نہیں ہے، جیسا کہ اللہ نے سورة الاعراف آیت 187 میں فرمایا ہے :﴿يَسْـَٔلُوْنَكَ عَنِ السَّاعَةِ اَيَّانَ مُرْسٰىهَاؕ قُلْ اِنَّمَا عِلْمُهَا عِنْدَ رَبِّيْۚ﴾یہ لوگ آپ سے قیامت کے متعلق سوالات کرتے ہیں کہ وہ کب واقع ہوگی، آپ فرما دیجیے کہ اس کا علم صرف میرے رب ہی کے پاس ہے، اس کے وقت پر اللہ کے سوا اسے کوئی ظاہر نہیں کرے گا۔\nاور جن معبودوں کی تم پوجا کرتے ہو انہیں تو کچھ بھی خبر نہیں کہ قیامت کب آئے گی اور کب وہ اپنے خالق کے سامنے حساب کے لیے کھڑے ہوں گے، اس لیے وہ معبود کیسے ہوسکتے ہیں، اگر وہ معبود ہوتے تو انہیں قیامت کی خبر ضرور ہوتی۔"],[5175,"§اللہ کی ربوبیت عامہ\nاس آیت اور اس سے آگے تین چار آیات میں اللہ تعالیٰ نے اپنی قدت کاملہ،رحمت اور ربوبیت عامہ اور توحید پر چند ایسے دلائل کے انبار لگا دیے ہیں جن میں سے اکثر دلائل کے مشرکین مکہ بھی معترف تھے۔ مثلاً سب سے پہلی دلیل تو یہی ہے کہ آسمانوں کا خالق بھی اللہ تعالیٰ ہے اور زمین کا بھی۔ آسمان سے مینہ برستا ہے جسے زمین جذب کرتی ہے۔ تو اس کی قوت روئیدگی اپنا کام کرنا شروع کردیتی ہے۔ اس سے فصلیں، غلے، پھل دار درخت، پھول اور مویشیوں کے گھاس اور چارہ اگتا ہے۔ اس طرح روئے زمین پر جتنی بھی اللہ تعالیٰ کی مخلوق بس رہی ہے سب کی غذا کا سامان فراہم ہوجاتا ہے۔ کروڑوں اور اربوں کی تعداد میں صرف انسان ہیں جو صرف ایک نوع ہے۔ جبکہ جاندار اشیاء کی انواع کی تعداد لاکھوں تک جاپہنچتی ہے کچھ پانی کی مخلوق ہے۔ کچھ خشکی کی اور کچھ ہوائی مخلوق ہے۔ اللہ تعالیٰ نے ان سب کی روزی کا ایسا جامع اور مکمل انتظام فرما دیا ہے کہ سب جانداروں کو روزی مہیا ہو رہی ہے۔\nاب بتلائیے کہ اس پورے نظام ربوبیت عامہ میں کوئی فرشتہ، کوئی نبی، کوئی ولی، کوئی بزرگ یا کوئی دوسرا معبود شریک ہے کہ اللہ کے علاوہ اس کی بھی عبادت کی جائے۔ عبادت تو انتہائی عاجزی اور تذلل کا نام ہے اور اسی کو سزاوار ہے۔ جو انتہائی درجہ میں کامل اور بااختیار ہو، کسی ناقض، عاجز یا محتاج مخلوق کو یہ مقام کیسے دیا جاسکتا ہے؟"],[5176,"§عدل کا لغوی مفہوم\nعدل کا لفظ کئی معنوں میں استعمال ہوتا ہے۔ اس کا معنی برابر ہوتا بھی اور برابر کا بدلہ بھی۔ پھر یہ لفظ لغت ذوی الاضداد سے ہے۔ یعنی اس کا معنی انصاف کرنا بھی ہے اور بےانصافی کرنا بھی۔ اس لحاظ سے اس جملہ کے کئی مطلب ہوسکتے ہیں۔ مثلاً ایک تو ترجمہ سے ہی واضح ہے کہ جب ربوبیت عامہ کا پورے کا پورا نظام صرف اللہ تعالیٰ کے قبضہ قدرت میں ہو تو عبادت میں دوسروں کو اس میں شامل کرلینا کس قدر بےانصافی اور ظلم کی بات ہے۔ اور دوسرا مطلب یہ ہے کہ اس اعتراف حقیقت کے باوجود یہ لوگ اپنے معبودوں کو اللہ کے برابر کا درجہ دیتے ہیں۔ اور تیسرا مطلب یہ ہے کہ یہ لوگ راہ راست سے بڑھ جاتے ہیں یعنی اعتراف حقیقت کے باوجود اس کا نتیجہ غلط نکال رہے ہیں۔\nیہاں سے پچھلے جملے کی تشریح اور اس کے دلائل دیئے جا رہے ہیں کہ وہی اللہ پیدائش، رزق اور تدبیر وغیرہ میں متفرد ہے۔ کوئی اس کا شریک نہیں ہے۔ فرمایا آسمانوں کو اتنی بلندی اور خوبصورتی کے ساتھ بنانے والا، ان میں درخشاں کواکب، روشن ستارے اور گردش کرنے والے افلاک بنانے والا۔ اسی طرح زمین اور اس میں پہاڑ،نہریں، چشمے، سمندر، اشجار کھیتیاں اور انواع واقسام کے طیور وغیرہ پیدا کرنےوالا اور آسمان سے بارش برسا کر اس کے ذریعے سے با رونق باغات اگانے والا کون ہے؟ کیا تم میںسےکوئی ایسا ہےجو زمین سے درخت ہی اگا کر دکھا دے؟ ان سب کے جواب میں مشرکین بھی کہتے اور اعتراف کرتے تھے کہ یہ سب کچھ کرنے والا اللہ تعالیٰ ہے، جیسا کہ قرآن میںدوسرے مقام پر۔ (مثلاً سورة العنکبوت:63)"],[5177,"§اللہ تعالیٰ کی وحدانیت کے اثبات پر متعدد دلائل\nچونکہ انسانوں کو متوجہ کرتے ہوئے انھیں آگاہ کرنا مقصود ہے اس لیے فرمایا کہ کیا وہ ذات جس نے کائنات کو بلاکسی نمونہ کے پیدا فرمایا اس نے آسمانوں کو جہاں نہایت بلندی میں پیدا فرمایا وہاں ان کی تخلیق میں حددرجہ حسن و صفائی موجود ہے اور آسمان میں ایسے ستاروں کا جڑاؤ کیا جو روشن ہیں اور زمین کو پیدا کرنے کے ساتھ ساتھ اس میں پہاڑوں اور میدانی علاقوں کو پیدا کیا اور سمندروں اور نہروں کے نظام کو قائم کیا تو ان کی خالق ذات ہی عبادت کے لائق ہے وہی ذات بہتر ہے اس کے ساتھ کسی کو معبود تصور نہیں کیا جاسکتا اس ذات نے تو تمہارے لیے اپنی قدرت کے ساتھ بادلوں سے بارش کو اتارا جس کے سبب باغات کو تازگی عطا کی ان کی ہریالی سے آنکھوں کی بینائی میں نہ صرف قوت ہوتی ہے بلکہ تازگی جلوہ افروز ہوتی ہے اور رنگا رنگ انگوریوں، پھلوں، اور پھولوں کے تابناک مناظر سے دل و دماغ مسرتوں سے اچھلنے لگتے ہیں جب کہ کسی بھی انسان میں ایسی قوت موجود نہیں ہے کہ وہ کسی درخت کو اگاسکے چہ جائیکہ درختوں کو بارآور کرسکے اور ان سے پہلے پھول نکال سکے، ان حیران کن مناظر کو ملاحظہ کرنے کے بعد تمہارے لیے ممکن ہے کہ اس کا شریک بناؤ اور اس کی عبادت کروہرگز نہیں اللہ کی ذات تو نہ صرف پیدا کرنے کے لحاظ سے ایک ہے بلکہ کائنات کے تکوینی نظام پر بھی اسی کا کنٹرول ہے جب کہ اللہ کی ذات کے ساتھ اللہ کی مخلوق کو اس کا شریک بنانے والے اور کائنات کے خالق اور پتھر کے بتوں کے درمیان برابر ی کرنے والے اللہ کی ذات کے ساتھ شریک بنانے والے مشرک ہیں۔\nدوسری دلیل کیا وہ ذات جس نے زمین کو انسان اور حیوان کے لیے قرار گاہ بنایا ہے کہ زمین کی سطح پر نہ صرف کھڑا ہونا ممکن ہے بلکہ برقرار رہنا بھی ممکن ہے اور زمین کی وادیوں اور گھاٹیوں میں میٹھے عمدہ پانی کی نہریں چلادی ہیں جو مشرق سے مغرب اور شمال سے جنوب میں رواںدواں رہتی ہیں اور اس نے زمین پر اونچے اونچے پہاڑ کو گاڑا ہوا ہے تاکہ زمین متحرک ہونے سے محفوظ رہے اور اس پرچلناپھرنا ممکن ہو اور اللہ نے شیریں اور نمکین پانی کے درمیان حد فاصل قائم کررکھی ہے تاکہ ان دونوں پانیوں میں اختلاط رونما نہ ہو کہیں نمکین پانی کے اختلاط سے میٹھاپانی خراب نہ ہوجائے اللہ کی اس عجیب قدرت کی منظر کشی پر غور کرنے کے بعد ہرگز ممکن نہیں کہ اللہ کی ذات کے ساتھ کوئی اور اس کا شریک ہو ہرگز نہیں جب کہ اکثر مشرک حق و صداقت سے آشنا نہیں ہوتے وہ تو اللہ کی ذات کے ساتھ شریک بناتے ہیں۔\n﴿اَمَّنْ جَعَلَ الْاَرْضَ قَرَارًا وَّجَعَلَ خِلٰلَهَاۤ اَنْهٰرًا وَّجَعَلَ لَهَا رَوَاسِيَ وَجَعَلَ بَيْنَ الْبَحْرَيْنِ حَاجِزًاؕ ءَاِلٰهٌ مَّعَ اللّٰهِؕ بَلْ اَكْثَرُهُمْ لَا يَعْلَمُوْنَؕ۰۰۶۱ اَمَّنْ يُّجِيْبُ الْمُضْطَرَّ اِذَا دَعَاهُ وَيَكْشِفُ السُّوْٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ الْاَرْضِؕ ءَاِلٰهٌ مَّعَ اللّٰهِؕ قَلِيْلًا مَّا تَذَكَّرُوْنَؕ۰۰۶۲﴾\n(کیا یہ بت بہتر ہیں) یا وہ (اللہ) جس نے زمین ٹھہرنے کے لائق بنائی، اور اس کے درمیان نہریں بنائیں اور اس کے لیے اس نے پہاڑ بنائے، اور دو سمندروں کے درمیان آڑ رکھی؟ کیا اللہ کے ساتھ کوئی (اور) الٰہ ہے؟ (نہیں!) بلکہ ان کے اکثر علم نہیں رکھتے⟦61⟧ (کیا یہ بت بہتر ہیں) یا وہ (اللہ) جو مجبور و لاچار کی دعا قبول کرتا ہے جب وہ اسے پکارتا ہے، اور وہ اس کی تکلیف دور کر دیتا ہے، اور وہ تمھیں زمین میں جانشین بناتا ہے؟ کیا اللہ کے ساتھ کوئی (اور) معبود ہے؟ تم کم ہی نصیحت حاصل\nکرتے ہو⟦62⟧"],[5178,"§زمین بہترین قرار گاہ\nارشاد باری تعالیٰ ہے: ﴿اَمَّنْ جَعَلَ الْاَرْضَ قَرَارًا﴾ ’’بھلا کس نے زمین کو ٹھہرنے کے لائق بنایا۔‘‘ کس نے زمین کو قرار بخشا اور اسے ساکن و ثابت بنادیا ہے کہ اب وہ حرکت کرتی ہے نہ ڈگمگاتی ہے؟ کیونکہ اگر اس میں حرکت اور جنبش ہوتی تو زندگی خوشگوار نہ ہوتی، اسی لیے اس نے اسے اپنے فضل و رحمت سے بستر اور بچھونے کی طرح بنا دیا کہ ساکت و ساکن ہے اور اس میں حرکت و جنبش نہیں جیسا کہ دوسری آیت میں فرمایا: ﴿اَللّٰهُ الَّذِيْ جَعَلَ لَكُمُ الْاَرْضَ قَرَارًا وَّالسَّمَآءَ بِنَآءً﴾ (المؤمن: 64) ’’اللہ ہی تو ہے جس نے زمین کو تمہارے لئے ٹھہرنے کی جگہ اور آسمان کو چھت بنایا۔‘‘"],[5179,"§زمین میں دریائوں کا جال\n﴿وَّجَعَلَ خِلٰلَهَاۤ اَنْهٰرًا﴾ ’’اور اس کے بیچ میں دریا بنائے۔‘‘ یعنی اللہ تعالی نے زمین میں شیریں اور پاکیزہ پانی کے دریا جاری و ساری کر دیے، انہیں زمین کے بیچ ہی سے نکالا اور زمین ہی میں رواں دواں کر دیا، پھر ان میں سے کچھ دریا بڑے، کچھ چھوٹے اور کچھ درمیانے ہیں، اللہ تعالی نے ان دریاؤں کو اپنے بندوں اور ان کے ملکوں اور علاقوں کی مصلحتوں کے مطابق مشرق سے مغرب کو یا جنوب سے شمال کو جاری کر دیا ہے جیسا کہ اپنے بندوں کو بھی اللہ تعالی نے زمین کے اطراف و اکناف میں پھیلا دیا اور ان کی ضرورت کے مطابق اس نے رزق کا بھی اہتمام فرما دیا ہے۔ ﴿وَّجَعَلَ لَہَا رَوَاسِیَ﴾ ’’اور اس کے لیے پہاڑ بنائے۔‘‘ اسی نے زمین میں بلند و بالا پہاڑ پیدا فرما دیے ہیں جو زمین کو مضبوطی سے تھامے ہوئے ہیں تاکہ یہ ڈگمگا نہ سکے۔ ﴿وَجَعَلَ بَیْنَ الْبَحْرَیْنِ حَاجِزًاط﴾ ’’اور دو سمندروں کے بیچ میں اوٹ بنائی۔‘‘ یعنی اس نے میٹھے اور نمکین پانیوں کے درمیان اوٹ بنا دی جس کی وجہ سے پانی ایک دوسرے میں مل کر خراب نہیں ہوتے کیونکہ حکمت الٰہی کا تقاضا یہ ہے کہ ہر قسم کے پانی کو اس کی مخصوص صفت کے ساتھ باقی رکھا جائے تاکہ مقصود حاصل ہوسکے۔\nشیریں دریا سے مراد وہ ہیں جو لوگوں کے مابین رواں دواں ہیں اور ان سے مقصود یہ ہے کہ ان کا آبِ رواں شیریں ہوتا ہے کہ انسانوں اور حیوانوں کے پینے کے کام آئے اور اس سے فصلوں اور پھلوں کی آبپاشی کا کام بھی کیا جا سکے اور نمکین دریاؤں سے مراد وہ سمندر ہیں جو ہر طرف سے زمین کو گھیرے ہوئے ہیں اور ان سے مقصود یہ ہے کہ ان کا پانی کھاری اور کڑوا ہو تاکہ ان کی ہوا کی وجہ سے فضا خراب نہ ہو جیسا کہ ارشاد باری تعالیٰ ہے: ﴿وَهُوَ الَّذِيْ مَرَجَ الْبَحْرَيْنِ هٰذَا عَذْبٌ فُرَاتٌ وَّهٰذَا مِلْحٌ اُجَاجٌۚ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَّحِجْرًا مَّحْجُوْرًا۰۰۵۳﴾ (الفرقان: 53) ’’اور وہی تو ہے جس نے دو سمندروں کو ملا دیا یہ (ایک کا پانی) شیریں ہے بہت میٹھا اور یہ (دوسرے کا) کھارا ہے نہایت کڑوا اور اس نے (ہی) ان دونوں کے درمیان ایک پردہ اور مضبوط اوٹ بنا دی۔‘‘\nاسی لئے فرمایا: ﴿ءَاِلٰهٌ مَّعَ اللّٰهِؕ﴾ ’’تو کیا اللہ کے ساتھ کوئی (اور) معبود بھی ہے؟‘‘ جس نے یہ کام کیا ہو یا دوسرے قول کے مطابق جس کی عبادت کی جائے، یہ دونوں معنی ہی لازم و ملزوم اور صحیح ہیں۔ ﴿بَلْ اَكْثَرُهُمْ لَا يَعْلَمُوْنَؕ۰۰۶۱﴾ ’’(ہرگز نہیں) بلکہ ان کے اکثر علم نہیں رکھتے۔‘‘ یعنی اس کے علاوہ ان بتوں کی پوجا پاٹ میں۔"],[5180,"§مشکل کشا اور حاجت روا\nاللہ تعالی نے متنبہ فرمایا ہے کہ شدائد کے وقت اسی سے دعا کی جائے اور مشکلات کے ازالے کی اسی سے اُمید رکھی جائے جیسا کہ فرمایا ہے: ﴿وَاِذَا مَسَّكُمُ الضُّرُّ فِي الْبَحْرِ ضَلَّ مَنْ تَدْعُوْنَ اِلَّاۤ اِيَّاهُۚ﴾ (بنیٓ اسرائیل: 67) ’’اور جب تمہیں سمندر میں تکلیف پہنچتی ہے (ڈوبنے کا خوف ہوتا ہے) تو جنہیں تم پکارتے ہو سب اُس (پروردگار) کے سوا گم ہو جاتے ہیں۔‘‘ اور فرمایا: ﴿ثُمَّ اِذَا مَسَّكُمُ الضُّرُّ فَاِلَيْهِ تَجْـَٔرُوْنَۚ۰۰۵۳﴾ (النحل: 53) ’’پھر جب تمہیں کوئی تکلیف پہنچتی ہے تو تم اسی کے سامنے گڑ گڑاتے ہو۔‘‘\nاسی طرح یہاں فرمایا: ﴿اَمَّنْ یُّجِیْبُ الْمُضْطَرَّ اِذَا دَعَاہُ﴾ ’’بھلا کون بے قرار کی (التجا) قبول کرتا ہے، جب وہ اسے پکارتا ہے۔‘‘ یعنی کون ہے کہ مجبور و مضطر اور لاچار و بے قرار جس کی طرف رجوع کرتا ہے اور کون ہے جو تکلیف میں مبتلا لوگوں کی تکلیفوں کو دور کرتا ہے۔ امام احمد رحمہ اللہ نے بَلْہُجَیْم کے ایک شخص سے روایت کی ہے کہ میں نے عرض کی: اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم کس کی طرف دعوت دیتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: میں اس اللہ وحدہ کی طرف دعوت دیتا ہوں کہ آپ کو اگر کوئی تکلیف پہنچے اور آپ اس سے دعا کریں تو وہ آپ کی تکلیف کو دور فرما دے اور اگر آپ کسی جنگل میں اپنی سواری گم کر بیٹھیں اور اس سے دعا کریں تو وہ آپ کی سواری آپ کو ملا دے اور وہ کہ اگر آپ قحط سالی میں مبتلا ہوں اور اس سے دعا کریں تو وہ ہریالی و شادابی پیدا فرمادے، راوی کا بیان ہے کہ میں نے عرض کی کہ مجھے وصیت فرمائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: کسی کو گالی نہ دو، نیکی میں کوتاہی نہ کرو، خواہ یہ نیکی اپنے بھائی سے خندہ پیشانی سے ملنا ہی کیوں نہ ہو یا پانی پینے والے کے برتن میں اپنے ڈول سے پانی ڈالنا ہی کیوں نہ ہو، اپنے تہبند کو نصف پنڈلی تک رکھو، اگر یہ نہ کر سکو تو ٹخنوں کے اوپر تک رکھو، تہبند کو ٹخنوں کے نیچے لٹکانے سے اجتناب کرو کیونکہ تہبند کو ٹخنوں سے نیچے لٹکانا تکبر ہے اور اللہ تعالیٰ تکبر کو پسند نہیں فرماتا۔‘‘\n(مسند احمد، حدیث: 20636)"],[5181,"§ایک مجاہد فی سبیل اللہ کا قصہ\nحافظ ابن عساکر رحمہ اللہ نے فاطمہ بنت حسن امام احمد عجلیہ کے حالات میں ذکر فرمایا ہے کہ ایک جنگ میں کافروں نے مسلمانوں کو شکست دے دی تو ایک مسلمان کا گھوڑا جو بہت تیز رفتار تھا، میدان میں اُڑ گیا، وہ مسلمان شخص سخی اور بہت نیک تھا، اس نے گھوڑے سے کہا: کیا بات ہے؟ میں نے تو تجھے اسی طرح کے دن کے لیے تیار کیا تھا۔ گھوڑے کو اللہ تعالی نے قوت گویائی عطا فرمائی اور اس نے کہا: میں کوتاہی کیوں نہ کروں آپ میرا چارا سائسوں (جانوروں کے نگرانوں) کے سپرد کردیتے تھے اور وہ مجھ پر ظلم کرتے اور مجھے کھانے کو بہت کم دیتے تھے۔ اس نے کہا کہ میں اللہ تعالی کو گواہ بنا کر عہد کرتا ہوں کہ آج کے بعد میں تجھے اپنی نگرانی میں کھلایا کروں گا، یہ سن کر گھوڑا چل پڑا اور گھوڑے کا مالک دشمنوں سے نجات پا گیا اور اس کے بعد وہ ہمیشہ گھوڑے کو اپنی نگرانی ہی میں کھلایا کرتا تھا اور اس کا یہ معاملہ لوگوں میں خاصا مشہور ہوگیا اور لوگ اس کے پاس آنے لگے تاکہ یہ بات خود اس کی زبانی سنیں حتیٰ کہ رومی بادشاہ تک یہ خبر پہنچی، اس نے کوشش کی کہ کسی طرح اس شخص کو اپنے ملک میں بلا لے، اس نے ایک مرتد شخص کو اس کے پاس بھیجا، جب وہ اس کے پاس آیا تو اس نے بظاہر تاثر یہ دیا کہ اب اس کی اور اس کی قوم کی اسلام کے بارے میں نیت بہت اچھی ہے حتیٰ کے اسے اپنے اعتماد میں لے لیا اور دونوں ایک دن باہر نکلے اور دریا کے ساحل پر چلنے لگے۔ شاہ، روم کے بھیجے ہوئے آدمی نے خفیہ طور پر ایک شخص سے پروگرام طے کر رکھا تھا کہ وہ بھی وہاں پہنچ جائے تاکہ دونوں مل کر اسے گرفتار کر لیں۔ جب دونوں نے اسے گھیرے میں لے لیا تاکہ اسے پکڑ کر گرفتار کر لیں تو اس نے آسمان کی طرف نگاہ اٹھائی اور دعا کی: اے اللہ! اس شخص نے مجھے تیرے نام پر دھوکا دیا ہے لہٰذا تو جس طرح چاہے مجھے ان دونوں سے بچا لے۔ اس شخص کا بیان ہے کہ اس کی اس دعا کے بعد دو درندے نمودار ہوئے، انہوں نے ان دونوں آدمیوں کو پکڑ لیا اور یہ شخص صحیح سلامت اپنے گھر واپس آ گیا۔\n(تاریخ دمشق الکبیر لابن عساکر: 9-8/74)"],[5182,"§زمین میں خلافت\nارشاد باری تعالیٰ ہے: ﴿وَيَجْعَلُكُمْ خُلَفَآءَ الْاَرْضِؕ﴾ ’’اور وہ تمہیں زمین میں جانشین بناتا ہے۔‘‘ یعنی وہ پہلی صدی کے لوگوں کا بعد کی صدی کے لوگوں کو اور سلف کا خلف کو جانشین بناتا ہے جیسا کہ اس نے فرمایا ہے: ﴿اِنْ يَّشَاْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنْۢ بَعْدِكُمْ مَّا يَشَآءُ كَمَاۤ اَنْشَاَكُمْ مِّنْ ذُرِّيَّةِ قَوْمٍ اٰخَرِيْنَؕ۰۰۱۳۳﴾ (الانعام: 133) ’’اگر چاہے تو تمہیں لے جائے اور تمہارے بعد جسے چاہے (تمہارا) جانشین بنا دے جیسا کہ اس نے تمہیں بھی دوسرے لوگوں کی نسل سے پیدا کیا ہے۔‘‘ اور فرمایا: ﴿وَهُوَ الَّذِيْ جَعَلَكُمْ خَلٰٓىِٕفَ الْاَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجٰتٍ﴾ (الانعام: 165) ’’اور وہی تو ہے جس نے زمین میں تمہیں (اپنا) نائب بنایا اور تم میں سے بعض کو بعض پر درجوں میں بلند کیا۔‘‘ اور فرمایا: ﴿وَاِذْ قَالَ رَبُّكَ لِلْمَلٰٓىِٕكَةِ اِنِّيْ جَاعِلٌ فِي الْاَرْضِ خَلِيْفَةًؕ﴾ (البقرۃ: 30) ’’اور (وہ وقت یاد کرنے کے قابل ہے) جب تیرے پروردگار نے فرشتوں سے فرمایا کہ میں زمین میں ایک خلیفہ بنانے والا ہوں۔‘‘\nیعنی زمین میں ایک ایسی قوم پیدا کرنے والا ہوں جو ایک دوسرے کی جانشین ہو گی جیسا کہ ہم نے قبل ازیں اس کی تفصیل بیان کی ہے، اسی طرح اس آیت کریمہ میں فرمایا: ﴿وَيَجْعَلُكُمْ خُلَفَآءَ الْاَرْضِؕ﴾ ’’اور وہ تمہیں زمین میں (اگلوں کا) جانشین بناتا ہے۔‘‘ یعنی کون ہے جو ایک امت کے بعد دوسری امت، ایک نسل کے بعد دوسری نسل اور ایک قوم کے بعد دوسری قوم کو جانشین بناتا ہے، اگر وہ چاہتا تو سب لوگوں کو ایک ہی وقت میں پیدا فرما دیتا اور بعض کو بعض کی اولاد میں سے نہ بناتا بلکہ سب کو اسی طرح پیدا فرما دیتا جس طرح اس نے سیّدنا آدم علیہ السلام کو مٹی سے پیدا فرمایا اور اگر وہ چاہتا تو بعض کو بعض کی اولاد میں سے تو بنا دیتا لیکن کسی کو فوت نہ کرتا اور بالآخر سب کو ایک ہی دفعہ فوت کر لیتا، اگر ایسی صورت ہوتی تو زمین تنگ ہو جاتی، لوگوں کی معیشت تنگ ہو جاتی، بعض، بعض سے نقصان اٹھاتے لیکن حکمت الٰہی کا تقاضا یہ ہوا کہ وہ سب انسانوں کو ایک ہی جان سے پیدا فرمائے، پھر ان کی تعداد کو کثیر کرکے انہیں زمین میں پھیلا دے اور انہیں صدیوں کے بعد صدیوں اور امتوں کے بعد امتوں میں تقسیم فرما دے حتیٰ کہ مدت پوری ہو جائے جیسا کہ اللہ تبارک و تعالیٰ نے اس کا اندازہ مقرر فرما رکھا ہے اور جیسے اس نے ایک ایک بندے کا شمار کر رکھا ہے، پھر ایک دن وہ قیامت برپا کرے گا اور ہر عمل کرنے والے کو اس کےعمل کے مطابق اچھا یا برا بدلہ عطا فرمائے گا، اسی لیے اس نے فرمایا ہے: ﴿اَمَّنْ يُّجِيْبُ الْمُضْطَرَّ اِذَا دَعَاهُ وَيَكْشِفُ السُّوْٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ الْاَرْضِؕ ءَاِلٰهٌ مَّعَ اللّٰهِؕ﴾ ’’بھلا کون بے قرار کی (التجا) قبول کرتا ہے، جب وہ اسے پکارتا ہے اور (کون اس کی) تکلیف کو دور کرتا ہے اور (کون) تمہیں زمین میں (اگلوں کا) جانشین بناتا ہے (یہ سب کچھ اللہ کرتا ہے) تو کیا اللہ کے ساتھ کوئی (اور) معبود بھی ہے؟‘‘ یعنی کیا اللہ کے ساتھ کوئی اور معبود ہے جس کو ان باتوں کی قدرت ہو یا کیا اس کے بعد اللہ کےسوا کوئی اور معبود ہے جس کی عبادت کی جا سکے جبکہ یہ معلوم ہے کہ ان تمام امور کو سر انجام دینے والا صرف اللہ وحدہ لا شریک ہی ہے! ﴿قَلِيْلًا مَّا تَذَكَّرُوْنَؕ۰۰۶۲﴾ ’’مگر بہت کم تم نصیحت حاصل کرتے ہو۔‘‘ یعنی لوگ ایسا بہت کم غور کرتے ہیں جو ان کی حق کی طرف رہنمائی کرے اور انہیں صراط مستقیم کی نشان دہی کرے۔"],[5183,"§زمین کے جائے قرار ہونے کی چھ توجیہات\nاس ایک جملہ کے اندر اللہ تعالیٰ کی کئی قدرتیں سمٹ کر آگئی ہیں۔ یہ بات تو ہزار ہا ہزار سال پہلے انسان کے علم میں آچکی تھی کہ ہمارا یہ عظیم الجثہ کرہ زمین گول ہے اور فضائے بسیط میں معلق ہے۔ زمین کا اکثر حصہ سمندر ہے۔ اور زمین کے گول ہونے کے باوجود پانی اس سے گر نہیں جاتا تو اس کی وجہ یہ ہے کہ ہر کرہ سماوی کی طرح ہماری زمین میں بھی کشش ثقل موجود ہے۔ جس کی وجہ سے اشیاء زمین پر از خود گر تو سکتی ہیں مگر خود بخود کسی طاقت کے استعمال کے بغیر اوپر نہیں اٹھ سکتیں ماسوائے گیسوں اور آبی بخارات کے کہ ان کا کرہ ہی زمین سے اوپر ہے۔ اگر کوئی گیس جو عام ہوا سے ہلکی ہوگی زمین سے بھی نکلے گی تو از خود اوپر اٹھ جائے گی۔ یہ عجائبات ہی کیا کم تھے اب مزید علم ہیئت کی تحقیقات نے ان عجائبات میں بےپناہ اضافہ کردیا ہے۔ مثلاً ایک یہ کہ ہماری زمین سورج کے سامنے رہتے ہوئے اپنے محور کے گرد تقریباً ایک ہزارمیل فی گھنٹہ کی رفتار سے گھوم رہی ہے۔ اور اس کا چکر ایک دن رات یا 24گھنٹوں میں پورا ہوتا ہے۔ اور دوسرے یہ کہ ہماری زمین سورج سے 9کروڑ 30 لاکھ میل دور ہے اور اس کے گرد بھی ایک سال میں ایک گردش پوری کرتی ہے تو یا سورج کے گرد اس کی گردش کی رفتار چھیاسٹھ ہزار چھ سو میل فی گھنٹہ ہے۔ ان دونوں قسم کی گردشوں کے باوجود اللہ تعالیٰ نے زمین کو اس قدر جکڑ رکھا ہے کہ ہم محسوس تک نہیں کرسکتے اور آرام سے اس پر چلتے پھرتے اور زندگی بسر کرتے ہیں۔ زمین کے جائے قرار ہونے کا ایک مفہوم یہ ہوا کہ صحیح احادیث میں وارد ہے کہ ہماری زمین پہلی ان گردشوں کی وجہ سے ہچکولے کھاتی تھی۔ تو اللہ تعالیٰ نے اس کی مختلف اطراف میں پہاڑ ایسی مناسبت سے رکھ دیئے کہ ہچکولے کھانا بند ہوگئی اور انسان اور دوسری تمام اشیاء کے لیے قرار بن گئی۔ اس کا تیسرا پہلو یہ ہے کہ اگر زمین ہمیشہ سورج کے سامنے رہتی تو زمین کے نصف حصہ پر تو ہمیشہ دن ہی چڑھا رہتا اور باقی نصف پر ہمیشہ رات ہی رہتی۔ اس طرح پوری کی پوری زمین نباتات اور سب جانداروں کے لیے بالکل ناکارہ ثابت ہوتی۔ اس لیے کہ نباتات اور جانداروں کی زندگی اور نشوونما کے لیے جیسے دن کی ضرورت ہے ویسے ہی رات کی بھی ضرورت ہے۔ اللہ تعالیٰ نے زمین پر رات اور دن کا نظام قائم فرما کر اسے تمام مخلوق کے لیے جائے قرار بنادیا اور اس کا چوتھا پہلو یہ ہے کہ زمین سے سورج کا فاصلہ اگر موجودہ فاصلہ سے کم ہوتا تو تمام مخلوق گرمی کی شدت اور تپش سے مرجھا جاتی اور بالآخر ختم یا تباہ ہوجاتی اور اگر یہ فاصلہ زیادہ ہوتا تو اتنی زیادہ سردی ہوتی کہ تمام تر مخلوق سردی سے ٹھٹھر جاتی اور بالآخر تباہ یا ہلاک ہوجاتی۔ اس طرح بھی یہ زمین مخلوق کے لیے جائے قرار نہ بن سکتی تھی۔ اس کا پانچواں پہلو یہ ہے کہ ہماری زمین سورج کے گرد\n66 ڈگری درجے کا زاویہ بناتے ہوئے گھوم رہی ہے۔ جس سے ایک تو دن اور رات کے اوقات میں بتدریج تبدیلی ہوتی رہتی ہے۔ کبھی دن بڑے ہونا شروع ہوجاتے ہیں اور راتیں بتدریج چھوٹی ہوتی جاتی ہیں۔ اور کبھی اس کے برعکس معاملہ شروع ہوجاتا ہے پھر اس بنا پر موسموں میں تبدیلی آتی ہے کبھی موسم گرما ہوتا ہے، کبھی سرما، کبھی بہار، کبھی خزاں اور کبھی برسات اور ان موسموں کا مختلف قسم کی اجناس، غلے اور پھل دار درختوں کے پیدا ہونے، ان کی نشوونما اور فصلوں اور پھلوں کے پکنے سے گہرا تعلق ہے۔ اگر اللہ تعالیٰ یہ نظام قائم نہ فرماتے تو پھر اس زمین پر بسنے والوں کے لیے خوراک کا مسئلہ نہایت پریشان کن صورت اختیار کرسکتا تھا۔ اس صورت میں یہ زمین ہمارے لیے جائے قرار نہیں بن سکتی تھی اور اس کا چھٹا پہلو یہ ہے کہ ہماری زمین سے اوپر پانچ چھ سو میل کی بلندی تک کثیف ہوا کا کرہ بنا کر زمین کو آفات سماوی یا فضاوی سے محفوظ بنادیا گیا ہے۔ موجودہ تحقیق کے مطابق تقریباً دو کروڑ شہاب ثاقب روزانہ 30 میل فی سیکنڈ کی برق رفتاری سے ہماری زمین کا رخ کرتے ہوئے گرتے ہیں۔ جب وہ اس کرہ ہوائی میں پہنچتے ہیں تو انھیں آگ لگ جاتی ہے اور وہیں ختم ہوجاتے ہیں۔ پھر بعض اوقات کوئی بڑی زیادہ جسامت والا شہاب زمین پر گر بھی پڑتا ہے اور زمین کے گرد گہرا گڑھا ڈال دیتا ہے لیکن ایسا کبھی کبھار ہوتا ہے جیسا اللہ کو منظور ہوتا ہے۔ عام حالات میں ہم ان سے محفوظ رہتے ہیں۔ اگر اللہ تعالیٰ زمین کے گرد کرہ ہوائی کا یہ نظام نہ فرماتے تو زمین کبھی محفوظ جائے قرار نہیں بن سکتی تھی۔ غرض اس مسئلہ کے اتنے زیادہ پہلو ہیں کہ جتنا بھی ان میں غور کیا جائے مزید پہلو سامنے آتے جاتے ہیں۔ اب سوال یہ ہے کہ آیا اس نظام کائنات میں اللہ کے علاوہ کسی اور معبود کا بھی کچھ دخل ہے خواہ یہ دخل کتنا ہی معمول ہو ؟ اور اگر اس سوال کا جواب نفی میں ہے تو پھر دوسروں کو اللہ کی عبادت میں کیسے شریک بنایا جاسکتا ہے ؟"],[5184,"§مشکل اوقات میں اکیلے اللہ کو پکارنا\nیہ سوال اس لیے کیا گیا کہ مشر کین مکہ کو خوب معلوم تھا کہ جب کسی کی جان پر بن جاتی ہے تو اس وقت کے معبود کسی کام نہیں آسکتے۔ لہٰذا وہ ایسے آڑے وقتوں میں صرف اکیلے اللہ کو مدد اور نجات کے لیے پکارتے تھے۔ (تشریح کے لیے دیکھئے سورة انعام کی آیت نمبر41 کا حاشیہ) اور ان سے سوال یہ کیا جارہا ہے کہ جب تمہیں اپنے بچاؤ کی کوئی صورت نظر نہیں آتی اور اس وقت نجات کے لیے اللہ ہی کو پکارتے ہو پھر وہ تمہاری اس مصیبت کو دور بھی کردیتا ہے اس وقت نہ کوئی پتھر کا بت اس کو رفع کرسکتا ہے نہ کوئی دوسرا معبود۔ تو پھر اللہ کی عبادت میں تم انھیں اس کا شریک یا ہمسر کیوں بناتے ہو ؟\nاَمَّنْ يُّجِيْبُ الْمُضْطَرَّ اِذَا دَعَاهُ : اللہ کی وحدانیت کی تیسری دلیل کو پیش کیا جارہا ہے کہ کیا وہ ذات جو مجبور، لاچار شخص کی آہ وزاری کی کیفیت کو سن کر اس کی دعا کو قبول کرتی ہے اور اس کی پکار پر اس کی تکلیف کو دور کرتی ہے کیا اس کے ساتھ کسی دوسرے معبود کا تصور کیا جاسکتا ہے ؟ ہرگز نہیں اور پھر اس نے تمہیں زمین کی خلافت عطا کی ہے تم تقدیر کے فیصلے کے مطابق یکے بعد دیگرے زمین کو آباد کررہے ہو کیا اللہ کی ذات کے سوا کوئی معبود ہے کہ تم اس کی عبادت کرو ؟ تو تم بہت کم خیرخواہی کی بات قبول کرتے ہو۔\nاَمَّنْ يَّهْدِيْكُمْ فِيْ ظُلُمٰتِ الْبَرِّ وَ الْبَحْرِ : اللہ کی وحدانیت پرچوتھی دلیل پیش کی جارہی ہے، کیا وہ ذات جو تمہیں تمہارے سفر میں تمہارے مقاصد کی جانب اندھیروں اور چٹیل میدان اور سمندروں اور ان شہروں کی جانب جہاں تم جانے کا ارادہ کرتے ہو تمہاری راہ نمائی کرتا ہے اور کون ہے وہ ذات جو بارش اترنے سے پہلے ہواؤں کو بھیجتی اور بارش برسانے کی خوش خبری عطا کرتی ہے جبکہ بارش نہ صرف بندوں کے لیے رحمت کا پیغام لاتی ہے بلکہ ملکوں کے لیے بھی خوش حالی کا پیغام دیتی ہے جہاں تم رات دن اپنے ضروری کاموں میں مصروف رہتے ہو اس حقیقت کے واضح ہونے کے بعد کیا اللہ کی ذات کے ساتھ معبود کا تصور ممکن ہے ؟ ہرگز نہیں اللہ کی ذات عاجز قسم کی مخلوق کی مشارکت سے بلند عظمت والی ہے۔\n﴿اَمَّنْ يَّهْدِيْكُمْ فِيْ ظُلُمٰتِ الْبَرِّ وَالْبَحْرِ وَمَنْ يُّرْسِلُ الرِّيٰحَ بُشْرًۢا بَيْنَ يَدَيْ رَحْمَتِهٖؕ ءَاِلٰهٌ مَّعَ اللّٰهِؕ تَعٰلَى اللّٰهُ عَمَّا يُشْرِكُوْنَؕ۰۰۶۳ اَمَّنْ يَّبْدَؤُا الْخَلْقَ ثُمَّ يُعِيْدُهٗ وَمَنْ يَّرْزُقُكُمْ مِّنَ السَّمَآءِ وَالْاَرْضِؕ ءَاِلٰهٌ مَّعَ اللّٰهِؕ قُلْ هَاتُوْا بُرْهَانَكُمْ اِنْ كُنْتُمْ صٰدِقِيْنَ۰۰۶۴﴾\n(کیا یہ بت بہتر ہیں) یا وہ (اللہ) جو تمھیں خشکی اور تری کے اندھیروں میں راہ دکھاتا ہے اور جو اپنی رحمت (بارش) سے پہلے بشارت والی ہوائیں بھیجتا ہے؟ کیا اللہ کے ساتھ کوئی (اور) معبود ہے؟ اللہ ان سے بلند و بالا ہے جنھیں وہ شریک ٹھہراتے ہیں⟦63⟧ (کیا یہ بت بہتر ہیں) یا وہ (اللہ) جو مخلوق کو پہلی بار پیدا کرتا ہے، پھر اسے لوٹائے گا، اور وہ جو تمھیں آسمان اور زمین سے رزق دیتا ہے؟ کیا اللہ کے ساتھ کوئی (اور) الٰہ ہے؟ کہہ دیجیے: اگر تم سچے ہو تو اپنی کوئی دلیل لے آئو⟦64⟧"],[5185,"§ستاروں کےفوائد\nارشاد باری تعالیٰ ہے: ﴿اَمَّنْ يَّهْدِيْكُمْ فِيْ ظُلُمٰتِ الْبَرِّ وَالْبَحْرِ﴾ ’’بھلا کون تمہیں خشکی اور تری کے اندھیروں میں رستہ بتاتا ہے۔‘‘ اور آسمانوں اور زمین میں پیدا کیے ہوئے نشانات کے ساتھ تمہاری رہنمائی فرماتا ہے جیسا کہ ارشاد باری تعالیٰ ہے: ﴿وَعَلٰمٰتٍؕ وَبِالنَّجْمِ هُمْ يَهْتَدُوْنَ۰۰۱۶﴾ (النحل: 16) ’’اور (رستوں میں) نشانات بنا دیے اور لوگ ستاروں سے بھی رستے معلوم کرتے ہیں۔‘‘ اور فرمایا: ﴿وَهُوَ الَّذِيْ جَعَلَ لَكُمُ النُّجُوْمَ لِتَهْتَدُوْا بِهَا فِيْ ظُلُمٰتِ الْبَرِّ وَالْبَحْرِؕ﴾ (الانعام: 97) ’’اور وہی تو ہے جس نے تمہارے لیے ستارے بنائے تاکہ تم خشکی اور تری کے اندھیروں میں ان سے رستے معلوم کرو۔‘‘ ﴿وَمَنْ يُّرْسِلُ الرِّيٰحَ بُشْرًۢا بَيْنَ يَدَيْ رَحْمَتِهٖؕ﴾ ’’اور کون ہوائوں کو اپنی رحمت کےا ٓگے (بارش سے پہلے) خوش خبری دینے والیاں بنا کر بھیجتا ہے۔‘‘ یعنی اس بادل سے پہلے جس میں بارش ہوتی ہے اور جسے اللہ تعالیٰ اپنے قحط زدہ اور مایوس بندوں پر برسا دیتا ہے۔ ﴿ءَاِلٰهٌ مَّعَ اللّٰهِؕ تَعٰلَى اللّٰهُ عَمَّا يُشْرِكُوْنَؕ۰۰۶۳﴾ ’’تو کیا اللہ کے ساتھ کوئی (اور) معبود بھی ہے؟ یہ لوگ جو شرک کرتے ہیں اللہ (کی شان) اس سے بلند ہے۔‘‘"],[5186,"§اللہ تعالیٰ کی قدرت کاملہ کے دلائل\nیعنی اللہ تعالیٰ اپنی قدرت و حکمت کے ساتھ مخلوق کو پہلی بار پیدا کرتا، پھر اسے دوبارہ پیدا کرے گا جیسا کہ دوسرے مقام پر فرمایا: ﴿اِنَّ بَطْشَ رَبِّكَ لَشَدِيْدٌؕ۰۰۱۲ اِنَّهٗ هُوَ يُبْدِئُ وَيُعِيْدُۚ۰۰۱۳﴾ (البروج: 13-12) ’’بے شک آپ کے پروردگار کی پکڑ بہت سخت ہے، وہی پہلی دفعہ پیدا کرتا ہے اور وہی لوٹائے گا۔‘‘ اور فرمایا: ﴿وَهُوَ الَّذِيْ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيْدُهٗ وَهُوَ اَهْوَنُ عَلَيْهِؕ﴾ (الروم: 27) ’’اور وہی تو ہے جو خلقت کو پہلی دفعہ پیدا کرتا ہے، پھر اسے لوٹائے گا اور یہ اس کے لیے بہت آسان ہے۔‘‘\n﴿وَمَنْ يَّرْزُقُكُمْ مِّنَ السَّمَآءِ وَالْاَرْضِ﴾ ’’اور کون تمہیں آسمان اور زمین سے رزق دیتا ہے؟‘‘ (یہ سب کچھ اللہ کرتا ہے) کہ آسمان سے بارش نازل کرتا اور زمین سے برکتوں کو پیدا فرماتا ہے۔ جیسا کہ فرمایا: ﴿وَالسَّمَآءِ ذَاتِ الرَّجْعِۙ۰۰۱۱ وَالْاَرْضِ ذَاتِ الصَّدْعِۙ۰۰۱۲﴾ (الطارق: 12-11) ’’آسمان کی قسم! جو بار بار بارش برسانے والا ہے اور زمین کی قسم! جو پھٹنے والی ہے۔‘‘ اور فرمایا: ﴿يَعْلَمُ مَا يَلِجُ فِي الْاَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنْزِلُ مِنَ السَّمَآءِ وَمَا يَعْرُجُ فِيْهَاؕ﴾ (الحدید: 4) ’’جو چیز زمین میں داخل ہوتی ہے اور جو اس سے نکلتی ہے اور جو آسمان سے اترتی اور جو اس کی طرف چڑھتی ہے، سب اسے معلوم ہے۔‘‘\nیعنی اللہ تعالیٰ کے سوا کوئی او ر ہستی ہے جو مضطرب و مجبور کی دعاؤں کا جواب دیتی ہو کہ جسے کرب و غم نے بے قرار کر رکھا ہو، جس کے لیے مطلوب کا حصول مشکل ہو اور جس مصیبت میں وہ مبتلا ہے اس سےگلوخلاصی پر مجبور ہو ؟ اللہ تعالیٰ کے سوا برائی، مصیبت، شر اور اللہ تعالیٰ کی ناراضی کو کون دور کرتا ہے ؟ کون ہے جو تمہیں زمین میں خلیفہ بناتا ہے، زمین میں تمہیں تمکن عطا کرتا ہے، تمہیں رزق سے نوازتا ہے اور تمہیں اپنی نعمتوں سے بہرہ مند کرتا ہے ؟ اور تم گزرے ہوئے لوگوں کے خلیفہ بنتے ہو جس طرح عنقریب اللہ تعالیٰ تمہیں موت سے ہمکنار کرے گا اور تمہارے بعد کچھ اور لوگوں کو لے آئے گا۔ کیا اللہ تعالیٰ کے ساتھ کوئی اور معبود ہے جو یہ تمام افعال سر انجام دیتا ہو؟\nکوئی ایسی ہستی نہیں جس سے تمام افعال صادر ہوتے ہوں حتی کہ اے مشرکو! تمہیں خود بھی اس کا اقرار ہے۔ یہی وجہ ہے کہ جب انہیں کوئی تکلیف پہنچتی تھی تو دین کو خالص کرکے صرف اللہ تعالیٰ ہی کو پکارتے تھے کیونکہ انہیں علم تھا کہ صرف اللہ تعالیٰ ہی اس تکلیف کو دور کرنے کی قدرت رکھتا ہے۔ ﴿قَلِيْلًا مَّا تَذَكَّرُوْنَؕ۰۰۶۲﴾ یعنی تم بہت کم نصیحت پکڑتے ہو اور بہت کم تدبر کرتے ہو حالانکہ یہ معاملات ایسے ہیں کہ اگر تم ان سے نصیحت پکڑو تو تمہیں نصیحت آجائے اور تم ہدایت کی طرف لوٹ آؤ۔ مگر غفلت اور اعراض تم پر مسلط ہے بنا بریں تم جہالت سے باز آتے ہو نہ راہ راست پر چلتے ہو۔\nوہ کون ہے جو تمہیں اس وقت راہ دکھا تاہے جب تم بحر و بر کی تاریکیوں میں سفر کر رہے ہوتے ہو جہاں تمہارے پاس کوئی راہنمائی کرنے والا ہوتا ہے نہ کوئی علامت دکھائی دیتی ہے اور نہ کوئی ایسا وسیلہ ہوتا ہے جس کے ذریعے سے تم نجات حاصل کر سکو۔ البتہ اللہ تعالیٰ کی راہنمائی تمہارے کام آتی ہے، وہ تمہارے لیے راستے کو آسان کرتا ہے وہ تمہیں اسباب مہیا کرتا ہے جن کے ذریعے سے تم صحیح راستہ پالیتے ہو۔﴿وَمَنْ يُّرْسِلُ الرِّيٰحَ بُشْرًۢا بَيْنَ يَدَيْ رَحْمَتِهٖؕ﴾ ”اور کون ہواؤں کواپنی رحمت سے پہلے خوش خبری بنا کر بھیجتا ہے۔“ یعنی بارش ہونے سے پہلے۔ پس اللہ تعالیٰ ان ہواؤں کو بھیجتا ہے وہ بادل اُٹھاتی ہیں، ان کو اکٹھا کرتی ہیں پھر ان کو بار آور کرتی ہیں اور بارش برسنے سے پہلے ہی بندے ان ہواؤں کو دیکھ کر خوش ہوتےہیں۔\n﴿ءَاِلٰهٌ مَّعَ اللّٰهِؕ﴾ ”کیا اللہ کے ساتھ کوئی معبود ہے “جس نے یہ تمام افعال سر انجام دیے ہیں یا صرف اکیلے اللہ تعالیٰ سے یہ افعال صادر ہوئے ہیں؟ پھر تم اللہ تعالیٰ کے ساتھ دوسروں کو کیوں شریک ٹھہراتے ہو اور اس کے سوا دوسروں کی عبادت کیوں کرتے ہو ؟ ﴿تَعٰلَى اللّٰهُ عَمَّا يُشْرِكُوْنَؕ۰۰۶۳﴾ اللہ بہت بڑا اور ان کے شرک اور ہمسر قرار دینے سے منزہ اور پاک ہے۔"],[5187,"§ستاروں کے فائدے\nرات کی تاریکیوں میں راہ معلوم کرنے کے لیے اللہ تعالیٰ نے چاند اور ستارے بنا دیئے۔ جن کی گردش کے لیے اللہ تعالیٰ نے ایسے ضابطے مقرر فرما دیئے ہیں کہ وہ سیارے ان کی خلاف ورزی نہیں کرسکتے۔ اور اس قدرتی نظام کا انسان کو یہ فائدہ پہنچتا ہے کہ وہ ان سے یہ بھی معلوم کرسکتا ہے کہ رات کا کتنا حصہ گزر چکا ہے اور یہ بھی اس وقت وہ کون سی سمت میں سفر کر رہا ہے۔ علاوہ ازیں اسے ان سیاروں کی روشنی سے راستے نظر بھی آنے لگتے ہیں۔ اور آج کل جو قطب نما کا آلہ ایجاد ہوا تو یہ بھی سیاروں ہی کا مرہون منت ہے۔ اگر یہ ستارے اللہ تعالیٰ پیدا نہ کرتا، یا ان کے نظام گردش میں باقاعدگی نہ ہوتی یا یہ بےنور ہوتے تو انسان رات کی تاریکیوں میں سفر کر ہی نہ سکتا تھا۔ خواہ یہ سفر خشکی کا ہوتا یا سمندر کا اور سمندر کا سفر تو اس کے لیے موت کا باعث بن سکتا تھا۔ یہ سارا نظام تو اللہ نے بنایا جس میں اس کا کوئی شریک نہیں۔ لیکن اللہ کی عبادت کے وقت تو تم اسے بھول جاتے ہو۔ یا دوسروں کو بھی اس کا ہمسر قرار دے کر انھیں بھی مستحق عبادت سمجھنے لگتے ہو۔"],[5188,"§نباتات اور جاندار اشیاء کی انواع جو انسان کے علم میں آ چکی ہیں\nآغاز خلق اور اعادہ خلق کا مسئلہ بھی اپنے اندر اللہ کی ہزارہا قدرتوں کی نشاندہی کرتا ہے۔ اور انسان جتنا اس معاملہ میں غور کرتا ہے اس کی حیرانگی میں اضافہ ہی ہوتا جاتا ہے۔ اس مسئلہ میں سب سے پہلا سوال یہ پیش آتا ہے کہ روح کیا چیز ہے جس پر زندگی کا مدار ہے۔ اور یہ سوال آج بھی ایسا پیچیدہ اور لاینحل ہے جیسا کہ سیدنا آدم علیہ السلام کے وقت تھا۔ انسان نے یہ تو دریافت کرلیا کہ مثلاً انسان فلاں فلاں عناصر کا مرکب ہے اور انسان کے جسم میں ان عناصر کی مقدار اتنی اور اتنی ہوتی ہے۔ مگر انہی عناصر کو اسی مقدار کے مطابق ترکیب دے کر ایک زندہ انسان بن کھڑا کرنا انسان کی بساط سے باہر ہے۔ اور یہ مسئلہ غالباً تاقیامت لاینحل ہی رہے گا۔ پھر یہ صرف ایک انسان کا مسئلہ نہیں بلکہ تمام جاندار اشیاء کا مسئلہ ہے۔ جس میں نباتات بھی شامل ہے۔ نباتات بھی جانداروں کی طرح بڑھتی ہیں۔ پھلتی پھولتی ہیں حتیٰ کہ احساس و شعور بھی رکھتی ہیں۔ اس وقت تک روئے زمین پر نباتات کی تقریباً دو لاکھ انواع اور جاندار اشیاء کی تقریباً دس لاکھ انواع انسان کے علم میں آچکی ہیں۔ جو اپنی ساخت، عناصر اور ترکیب کے لحاظ سے بالکل ایک دوسرے سے الگ ہیں اور جب سے انسان نے ان انواع کو جاننا شروع کیا اس وقت سے لے کر آج تک انسان کے علم میں یہ بات نہیں آسکی۔ کہ نباتات یا حیوانات کی کوئی نوع ارتقاء کی منزل طے کرکے اپنے سے کسی اعلیٰ جنس میں تبدیل ہوگئی ہو۔ بلکہ جس حال میں انسان نے اسے پہلے دن دیکھا تھا اسی حال میں بھی یہ آج بھی پائی جاتی ہے۔ جس سے ڈارون کے نظریہ کا از خود ابطال ہوجاتا ہے اگرچہ ڈارون کے نظریہ کے باطل ہونے کے اور بھی بیشمار دلائل موجود ہیں۔ گویا اللہ تعالیٰ نے نباتات کی اور حیوانات کی جس نوع کو جس طرح پہلے دن پیدا کیا تھا آج بھی وہ اسی صورت میں پائی جاتی ہے اور انسان کی تخلیق تو ایک بالکل خصوصی نوعیت رکھتی ہے۔ جس کے متعلق اللہ تعالیٰ فرماتے ہیں کہ میں نے اسے اپنے ہاتھ سے بنایا ہے۔ (75:38)"],[5189,"§آغازِ خلق اور اعادہ خلق کا سلسلہ ہر آن جاری ہے\nاور اعادہ خلق سے صرف یہ مراد نہیں کہ اللہ تعالیٰ قیامت کے دن تمام انسانوں کو ان کی قبروں سے زندہ کرکے اٹھا کھڑا کرے گا۔ بلکہ اعادہ خلق سے مراد یہ ہے کہ اللہ تعالیٰ ہر آن مردہ سے زیادہ اور زندہ سے مردہ پیدا کر رہا ہے۔ اور یہ نظام نباتات اور حیوانات کی تمام تر اقسام میں جاری وساری ہے۔ مثلاً ایک ننھے سے بیج کو لیجئے اس میں اس درخت کی وہ تمام تر خصوصیات سمو دی گئی ہیں جس کا وہ بیج ہے۔ جب اس بیج کو نشوونما کا موقع ملے گا تو اس میں وہ تمام تر خصوصیات مثلاً اس کا رنگ، اس کا مزا، اس کی بو، اس کا قد و قامت، اس کا پھل اسی درخت جیسا ہوگا جس کا وہ بیج تھا۔ اسی طرح کسی جاندار یا انسان کے نطفہ میں اس انسان کی شکل و صورت ہی منتقل نہیں ہوتی بلکہ اس کی عادات و خصائل تک منتقل ہوجاتی ہیں۔ رہا انسان کا اور جسم اور اس کے اندر پیچیدہ مشینری، اس کا عصبی، عضلاتی، لحمی اور ہڈیوں کی پیدائش کا نظام یہ سب چیزیں اس انسان کے نطفہ میں ایک خوردبین جرثومہ کی شکل میں منتقل ہوجاتی ہیں۔ اور جب اسے نشوونما کا موقعہ میسر آتا ہے تو یہ سب چیزیں عملی طور پر وجود میں آجاتی ہیں کبھی ایسا نہیں ہوتا کہ ایک جاندار کے جرثومہ میں کسی دوسرے جرثومہ کے خواہش منتقل ہوجائیں۔ یا مثلاً کسی عورت کے رحم میں اونٹ کا جرثومہ چلا جائے تو اس کے ہاں اونٹ کا بچہ پیدا ہوجائے اللہ کا اعادہ خلق کا نظام آغاز خلق سے بھی زیادہ پیچیدہ اور حیران کن ہے۔ اب غور فرمائیے کہ اس آغازِ خلق اور اعادہ خلق کے نظام میں اللہ کے علاوہ کسی فرشتے، کسی نبی، کسی ولی، کسی جن، کسی پیروفقیر، یا کسی سیارے یا بت کا عمل دخل ہے؟ اگر نہیں تو پھر عبادت کے مستحق کیسے ہوسکتے ہیں؟"],[5190,"§خوراک کی پیدائش کے عوامل\nتمام نباتات اور حیوانات کی ضروریاتِ زندگی اگرچہ زمین ہی سے وابستہ ہیں۔ تاہم ان کی خوراک، پیدائش میں بہت سے دوسرے عوامل بھی کام کرتے ہیں۔ سب سے بڑا عامل تو زمین کی قوت روئیدگی ہے۔ مٹی کی تاریکی میں ہی بیج کی نشوونما شروع ہونے لگتی ہے۔ دوسرا عامل سورج ہے۔ جس کی گرمی سے سطح سمندر سے آبی بخارات اٹھتے ہیں۔ تیسری عامل ہوائیں ہیں جو ان آبی بخارات کی سمت موڑتی ہیں۔ چوتھا عامل پہاڑوں کی بلندی یا کسی بلند طبقہ کی ٹھنڈک ہے جو پھر سے ان آبی بخارات کو پانی کے قطروں کی شکل میں تبدیل کردیتا ہے۔ پھر اسی پانی کے ساتھ زمین کی قوت روئیدگی ملتی ہے۔ تب جاکر نباتات اُگتی ہیں اور انسان اور حیوانات کو رزق میسر آتا ہے۔ غور فرمائیے کہ ان سمندروں، اس سورج، ان ہواؤں، ان پہاڑوں اور اس زمین کی پیدائش میں اللہ کے سوا کسی دوسری ہستی کا کچھ عمل دخل ہے ؟ اب اگر کوئی یہ سمجھتا ہے کہ بارش فلاں سیارے کے فلاں نچھتر میں داخل ہونے پر یا اس سیارے کی روح کے مجسّمے یا بت کی قربانی یا نذرانہ دینے سے ہوتی ہے تو اسے کوئی تجرباتی مشاہداتی یا نقلی دلیل پیش کرنا چاہیے۔ اور اگر وہ ایسا نہیں کرسکتے تو اللہ کی رزاقیت میں دوسرے کیسے شامل ہوسکتے ہیں۔ اور لوگوں کے داتا کیسے بن سکتے ہیں ؟\nاَمَّنْ يَّبْدَؤُا الْخَلْقَ ثُمَّ يُعِيْدُهٗ : اللہ تعالیٰ کی وحدانیت پر پانچویں دلیل پیش کی جارہی ہے، کیا وہ ذات جس نے ابتداء میں انسان کو پیدا فرمایا پھر اس کو موت کے بعد دوبارہ اٹھائے گا۔\nوَ مَنْ يَّرْزُقُكُمْ مِّنَ السَّمَآءِ وَ الْاَرْضِ: اور تم پر کون آسمان سے بارش اتارتا ہے اور زمین سے پھلوں اور کھیتوں کو اگاتا ہے کیا اللہ کے ساتھ کوئی معبود ہے ؟ ہرگز نہیں آپ کہیں اگر تم سچے ہو تو دلیل پیش کرو کہ اللہ کے ساتھ کوئی اور معبود ہے۔\n﴿قُلْ لَّا يَعْلَمُ مَنْ فِي السَّمٰوٰتِ وَالْاَرْضِ الْغَيْبَ اِلَّا اللّٰهُؕ وَمَا يَشْعُرُوْنَ اَيَّانَ يُبْعَثُوْنَ۰۰۶۵ بَلِ ادّٰرَكَ عِلْمُهُمْ فِي الْاٰخِرَةِ١۫ࣞ بَلْ هُمْ فِيْ شَكٍّ مِّنْهَا١۫ٞࣞ بَلْ هُمْ مِّنْهَا عَمُوْنَࣖ۰۰۶۶﴾\nکہہ دیجیے: آسمانوں اور زمین میں اللہ کے سوا کوئی بھی غیب (کی بات) نہیں جانتا، اور وہ (خود ساختہ معبود) تو یہ بھی نہیں جانتے کہ وہ (قبروں سے) کب اٹھائے جائیں گے⟦65⟧ بلکہ آخرت کے بارے میں ان کا علم ختم ہو چکا، بلکہ وہ آخرت کے متعلق شک میں ہیں، بلکہ وہ اس سے اندھے ہیں⟦66⟧"],[5191,"§عالم الغیب صرف اللہ تعالیٰ ہی کی ذات گرامی ہے\nاللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو یہ حکم دیا ہے کہ آپ تمام مخلوق کو یہ بات بتا دیں کہ اللہ تعالیٰ کے سوا آسمانوں اور زمین میں اور کوئی غیب نہیں جانتا۔ اور ارشاد باری تعالیٰ: ﴿اِلَّا اللّٰہُط﴾ میں استثنا منقطع ہے، یعنی اللہ عزوجل کے سوا اور کوئی اسے نہیں جانتا، غیب جاننا صرف اسی ذات وحدہ لا شریک کا خاصہ ہے جیسا کہ فرمایا: ﴿وَعِنْدَهٗ مَفَاتِحُ الْغَيْبِ لَا يَعْلَمُهَاۤ اِلَّا هُوَؕ﴾ (الانعام: 59) ’’اور اسی کے پاس غیب کی کنجیاں ہیں جنہیں اس کے سوا کوئی نہیں جانتا۔‘‘ اور فرمایا: ﴿اِنَّ اللّٰهَ عِنْدَهٗ عِلْمُ السَّاعَةِۚ وَيُنَزِّلُ الْغَيْثَۚ وَيَعْلَمُ مَا فِي الْاَرْحَامِؕ وَمَا تَدْرِيْ نَفْسٌ مَّا ذَا تَكْسِبُ غَدًاؕ وَمَا تَدْرِيْ نَفْسٌۢ بِاَيِّ اَرْضٍ تَمُوْتُؕ اِنَّ اللّٰهَ عَلِيْمٌ خَبِيْرٌࣖ۰۰۳۴﴾ (لقمٰن: 34) ’’یقیناً اللہ ہی کو قیامت کا علم ہے اور وہی مینہ برساتا ہے اور وہی رحموں کی چیزوں کو جانتا ہے اور کوئی شخص نہیں جانتا کہ وہ کل کیا کام کرے گا اور کوئی متنفس نہیں جانتا کہ کس سر زمین میں اسے موت آئے گی، بے شک اللہ ہی خوب جاننے والا، بڑا خبردار ہے۔‘‘ اس مضمون کی اور بھی بہت سی آیات ہیں۔\n﴿وَمَا يَشْعُرُوْنَ اَيَّانَ يُبْعَثُوْنَ۰۰۶۵﴾ ’’اور نہ یہ جانتے ہیں کہ کب (زندہ کرکے) اُٹھائے جائیں گے۔‘‘ یعنی آسمانوں اور زمین میں بسنے والی مخلوق میں سے کوئی بھی قیامت کے وقت کو نہیں جانتا جیسا کہ فرمایا: ﴿ثَقُلَتْ فِي السَّمٰوٰتِ وَالْاَرْضِؕ لَا تَاْتِيْكُمْ اِلَّا بَغْتَةًؕ﴾ (الاعراف: 187) ’’وہ آسمانوں اور زمین میں بہت بھاری ہے اور اچانک تم پر آ جائے گی۔‘‘ یعنی اس کا علم آسمان اور زمین والوں کے لیے بہت بھاری ہے، ﴿بَلِ ادّٰرَكَ عِلْمُهُمْ فِي الْاٰخِرَةِ١۫ࣞ بَلْ هُمْ فِيْ شَكٍّ مِّنْهَا١۫ٞ﴾ ’’بلکہ آخرت (کے بارے) میں ان کا علم منتہی ہو چکا ہے بلکہ وہ اس سے شک میں ہیں۔‘‘ یعنی ان کا علم ختم ہو گیا ہےا ور وہ اس کے وقت کے جاننے سے عاجز و قاصر ہیں۔ بعض نےا س کے یہ معنی بیان کیے ہیں کہ قیامت کے بارے میں ان کا علم ایک جیسا ہے۔ جیسا کہ صحیح مسلم کی روایت میں ہے کہ جب جبریل نے رسول اللہ صلی اللہ علیہ وسلم سے قیامت کے وقت کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: «مَا الْمَسْئُوْلُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ» ’’اس بارے میں مسئول کو سائل سے زیادہ علم نہیں ہے۔‘‘ (صحیح البخاری، حدیث: 50 و صحیح مسلم، حدیث: 9-8) یعنی اس کے بارے میں مسئول اور سائل کا علم ایک جیسا ہے کہ دونوں ہی اسے جاننے سے عاجز و قاصر ہیں۔\nاللہ تبارک و تعالیٰ آگاہ فرماتا ہے کہ صرف وہی ہے جو آسمانوں اور زمین کے غیب کا علم رکھتا ہے، جیسا کہ اللہ تعالیٰ نے فرمایا ہے : ﴿وَعِنْدَهٗ مَفَاتِحُ الْغَيْبِ لَا يَعْلَمُهَاۤ اِلَّا هُوَؕ وَيَعْلَمُ مَا فِي الْبَرِّ وَالْبَحْرِؕ وَمَا تَسْقُطُ مِنْ وَّرَقَةٍ اِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِيْ ظُلُمٰتِ الْاَرْضِ وَلَا رَطْبٍ وَّلَا يَابِسٍ اِلَّا فِيْ كِتٰبٍ مُّبِيْنٍ۰۰۵۹﴾ (الانعام:59) ”اور اسی کے پاس ہیں غیب کی کنجیاں، اس کے سوا انہیں کوئی نہیں جانتا، جو کچھ بر و بحر میں ہے وہ سب جانتا ہے، کوئی پتا نہیں جھڑتا مگر وہ اس کے علم میں ہوتاہے۔ کوئی تر اور کوئی سوکھی چیز نہیں مگر ایک واضح کتاب میں درج ہے۔ “ اور فرمایا:﴿اِنَّ اللّٰهَ عِنْدَهٗ عِلْمُ السَّاعَةِۚ وَيُنَزِّلُ الْغَيْثَۚ وَيَعْلَمُ مَا فِي الْاَرْحَامِؕ وَمَا تَدْرِيْ نَفْسٌ مَّاذَا تَكْسِبُ غَدًاؕ وَمَا تَدْرِيْ نَفْسٌۢ بِاَيِّ اَرْضٍ تَمُوْتُؕ اِنَّ اللّٰهَ عَلِيْمٌ خَبِيْرٌࣖ۰۰۳۴﴾ (لقمان:34) ”قیامت کی گھڑی کا اللہ ہی کو علم ہے، وہی بارش برساتا ہے وہی جانتا ہے کہ ماؤں کے رحموں میں کیا ہے، کوئی شخص یہ نہیں جانتا کہ وہ کل کیا کمائی کرنے والا ہے اور کوئی متنفس یہ نہیں جانتا کہ اسے کس سرزمین میں موت آئے گی بے شک اللہ ہی جاننےو الا اور خبر رکھنے والا ہے۔“\nاس قسم کے تمام غیوب کے علم کو اللہ تعالیٰ نے اپنے ساتھ مختص کیا ہے۔ پس کوئی مقرب فرشتہ یا نبی بھی ان کو نہیں جانتا اور چونکہ وہ اکیلا غیب کا علم رکھتا ہے، اس کا علم تمام بھیدوں، باطنی اور خفیہ اُمور کا احاطہ کیے ہوئے ہے اس لیے اس کے سوا کوئی ہستی عبادت کے لائق نہیں۔\nپھر اللہ تبارک و تعالیٰ نے آخرت کی تکذیب کرنے والوں کے ضعف علم کے بارے میں ایک کمتر چیز سے برتر چیز کی طرف منتقل کرتے ہوئے آگاہ کیا اورفرمایا:﴿وَمَا يَشْعُرُوْنَ﴾ یعنی وہ نہیں جانتے ﴿اَيَّانَ يُبْعَثُوْنَ۰۰۶۵﴾ ”وہ کب اُٹھائے جائیں گے ؟“ یعنی قبروں سے دوبارہ زندہ کرکے کب کھڑا کیاجائے گا۔ یعنی پس اسی لیے انہوں نے تیاری نہیں کی۔ ﴿بَلِ ادّٰرَكَ عِلْمُهُمْ فِي الْاٰخِرَةِ١۫﴾ ”بلکہ ان کا علم آخرت کے بارے میں ختم ہو گیا ہے۔“ یعنی بلکہ ان کا علم کمزور ہے، ان کا علم یقینی نہیں ہے اور وہ ایسا علم نہیں جو قلب کی گہرائیوں تک پہنچ سکے۔ یہ علم کا قلیل ترین اور ادنیٰ ترین درجہ ہے۔ بلکہ ان کے پاس کوئی قوی علم ہے نہ کمزور ﴿بَلْ هُمْ فِيْ شَكٍّ مِّنْهَا١۫ٞ﴾ ”بلکہ وہ اس سے شک میں ہیں۔“ یعنی آخرت کے بارے میں۔ شک علم کو زائل کر دیتا ہے کیونکہ علم اپنے تمام مراتب میں کبھی شک کے ساتھ یکجا نہیں ہوتا۔ ﴿بَلْ هُمْ مِّنْهَا﴾ ”بلکہ وہ اس سے“ یعنی آخرت کے بارے میں ﴿عَمُوْنَ﴾ ”اندھے ہیں۔“ ان کی بصیرتیں ختم ہو گئیں۔ ان کے دلوں میں آخرت کے وقوع کے بارے میں کوئی علم ہے نہ اس کا کوئی احتمال بلکہ وہ آخرت کا انکار کرتے ہیں اور اس کو بہت بعید سمجھتے ہیں۔"],[5192,"§غیب اور شہادت کے مختلف پہلو\nغیب سے مراد ایک تو ایسی چیزیں ہیں جو کسی خاص انسان کے علم یا مشاہدہ میں نہ آئی ہوں۔ پھر جب وہ اس کے علم میں آجائیں گی تو اس کے لیے غیب نہ رہیں گی۔ مثلاً سڑک پر ایک بس اور کار کا حادثہ ہوگیا جس میں چار آدمی مرگئے۔ پھر جب اسے اس کا علم ہوجائے گا یا وہ خود مشاہدہ کرلے گا تو یہ واقعہ اس کے لیے غیب نہ رہا۔ ایسی خبریں ماضی کی بھی ہوسکتی ہیں۔ حال کی بھی جو کسی کو معلوم ہوتی ہیں اور کسی کے لیے غیب کا درجہ رکھتی ہیں۔ البتہ مستقبل کی خبریں سب کے لیے غیب ہوتی ہیں۔ دوسری قسم یہ ہے کہ جتنے علوم انسان دریافت کرچکا ہے یا جس حد تک دریافت کرچکا ہے۔ وہ سب انسان کے لیے علم الشہادۃ ہیں اور جن علوم تک انسان کی رسائی ہو ہی نہیں ہوسکتی یا نہیں ہوسکی۔ وہ اس کے لیے علم غیب ہیں۔ تیسری قسم ان اشیاء کا علم ہے جن تک انسان کی رسائی نہ پہلے کبھی ہوئی اور نہ آئندہ کبھی ہوسکے گی اور کتاب و سنت کی تصریح کے مطابق یہ پانچ چیزیں ہیں۔ (1) کل کیا کچھ ہونے والا ہے اور فلاں شخص کل کیا کچھ کرے گا، (2) موت کب آئے اور کہاں آئے گی۔ (3) رحم مادر میں تغیرات کیونکر واقع ہوتے ہیں۔ (4) نفع رساں بارش کب ہوگی اور (5) قیامت کب آئے گی۔ (34:31) ان چیزوں کا علم صرف اللہ کو ہوتا ہے۔"],[5193,"§علم غیب صرف اللہ کو ہے\nان تصریحات سے معلوم ہوا کہ غیب کا علم صرف اللہ کو ہے۔ البتہ اس علم میں سے جتنا وہ انسانی ہدایت کے لیے ضروری سمجھتا ہے اس سے اپنے انبیاء علیہم السلام کو مطلع کردیتا ہے۔ جیسے قیامت، بعث بعد الموت، جنت و دوزخ اور روز قیامت کے احوال اور ایسے ہی ماضی کے حالات جیسے شرعی اصطلاح میں تذکیربایامِ اللہ کہتے ہیں۔ انبیاء و اقوام کے حالات اور بعض مستقبل کے متعلق پیشین گوئیاں اور بشارات۔ چنانچہ اللہ تعالیٰ نے انبیاء علیہم السلام کی زبان سے بار بار یہ اعلان کروایا کہ اللہ کے سوا کوئی غیب نہیں جانتا۔ ایک مقام پر فرمایا:”اے نبی کہہ دو کہ اگر میں غیب جانتا ہوتا تو میں بہت بھلائیاں اکٹھی کرلیتا اور مجھے کبھی کوئی تکلیف نہ پہنچتی“ (188:7) اور انبیاء علیہم السلام پر چونکہ بموجب تصریح احادیث صحیحہ ابتلا کا دور آتا ہے تو جس سے صاف معلوم ہوتا ہے کہ انبیاء علیہم السلام بھی اتنا ہی غیب کا علم جانتے ہیں۔ جتنا اللہ انھیں بتلا دیتا ہے۔"],[5194,"§علم غیب اور الوہیت کا باہمی تعلق\nعلم غیب کو اللہ تعالیٰ سے مخصوص رکھنا اسلام کا بنیادی عقیدہ ہے اور اس کی وجہ ہے کہ الوہیت اور علم غیب ماننے میں ایک گہرا تعلق ہے۔ قدیم زمانے سے لے کر آج تک انسان نے جس ہستی میں الوہیت کے کسی شائبہ کا گمان کیا ہے اس کے متعلق یہ ضرور خیال کیا ہے کہ اس پر سب کچھ روشن ہے اور کوئی چیز اس پر پوشیدہ نہیں رہتی۔ آپ نے اکثر اولیاء اللہ کے تذکروں میں پڑھا یا سنا ہوگا کہ پیر اپنے مریدوں کے حالات سے آگاہ ہوتا ہے۔ پھر ایسے بیشمار واقعات بھی ان تذکروں میں پائے جاتے ہیں۔ ایسے سب قصے اس لیے گھڑے جاتے ہیں کہ ان پیروں میں الوہیت کی صفات کو تسلیم کیا جائے اگرچہ زبان سے ان کا اقرار نہ کیا جائے۔ گویا کسی کے متعلق ایسا عقیدہ رکھنا ہی شرک کی سب سے بڑی بنیاد ہے۔ کوئی بزرگ یا پیر خواہ زندہ ہو یا فوت ہوچکا ہو کسی کی فریاد تو اسی صورت میں سن سکتا ہے اور اس کی حاجت روائی اور مشکل کشائی اسی صورت میں کرسکتا ہے کہ سب سے پہلے وہ اپنے مریدوں کے احوال سے آگاہ ہو پھر اس کے بعد امور کائنات میں کچھ تصرف بھی رکھتا ہو۔"],[5195,"§علمِ غیب ناقابل تقسیم صفت ہے\nپھر جس طرح اللہ تعالیٰ کی بعض دوسری صفات مثلاً خلاقیت اور رزاقیت ناقابل تقسیم و تجزیہ ہیں۔ اس طرح علم غیب بھی ناقابل تقسیم و تجزیہ ہے۔ یعنی یہ نہیں کہا جاسکتا کہ فلاں بزرگ اپنے تمام مریدوں کے حالات سے یا اپنے علاقہ یا شہر کے حالات سے پوری طرح باخبر ہے اور ان کے غیب کے حالات بھی جانتا ہے۔ یا فلاں ہستی اس علاقہ کی زمین کے مدفون خزانوں کو جانتی ہے، ایسی تمام باتیں شرک میں داخل ہیں۔\nیعنی ان کا علم آخرت کے وقوع کا وقت جاننےسے عاجز ہے۔ یا ان کا علم آخرت کے بارےمیں برابر ہے جیسے نبی صلی اللہ علیہ وسلم نے سیّدنا جبریل علیہ السلام کے استفسار پر فرمایا تھا کہ:”قیامت کے بارے میںمسئول عنہا (نبی اکرم صلی اللہ علیہ وسلم) بھی سائل (سیّدنا جبریل) سے زیادہ علم نہیں رکھتے“ یا یہ معنی ہیں کہ ان کا علم مکمل ہو گیا، اس لیے کہ انہوں نے قیامت کے بارےمیںکیے گئے وعدوںکو اپنیآنکھوںسے دیکھ لیا، گو یہ علم اب ان کے لیے نافع نہیں ہے، کیونکہ دنیامیںوہ اسے جھٹلاتے رہے تھے۔\nجیسے فرمایا: ﴿اَسْمِعْ بِهِمْ وَاَبْصِرْۙ يَوْمَ يَاْتُوْنَنَا لٰكِنِ الظّٰلِمُوْنَ الْيَوْمَ فِيْ ضَلٰلٍ مُّبِيْنٍ۰۰۳۸﴾ (مریم:38)”وہ جس دن ہمارے سامنے آئیں گے، کیسے سننے والے اور کیسے دیکھنے والے ہوں گے، مگر ظالمآج صریح گمراہی میںہیں۔“"],[5196,"§مشرکین کے سوال پر آیات کا نزول\nاللہ پاک کو ہی غیب کا علم ہے ہرگز کوئی فرشتہ یا انسان غیب کا علم نہیں جانتا ہے یہ آیت مشرکین کے ایک سوال پر نازل ہوئی جب انھوں نے نبی کریم صلی اللہ علیہ وسلم سے قیامت کے بارے میں سوال کیا کہ مخلوق میں سے ہرگز کسی کو قیامت کے وقوع پذیر ہونے کا علم نہیں ہے کہ اس کا وقوع کب ہوگا ؟ صرف اللہ ہی کی ذات کو اس کا علم ہے بلکہ آخرت کے وقوع کے بارے میں ان کا یہ علم تھا کہ وہ اس کے وقوع کے بارے میں شک وشبہ کا اظہار کرتے تھے بلکہ پوری کائنات انسانی کو ہرگز اس کے واقع ہونے کے بارے میں معلومات نہیں ہیں کہ کب اس کا وقوع ہوگا وہ تو آخرت کے بارے میں شک میں ہیں اس کی تصدیق نہیں کرتے ہیں اسی لیے اس کے مخالف ہیں بلکہ وہ تو قیامت کے وقوع کے بارے میں اندھے ہیں ان میں بصیرت نام کی کوئی چیز نہیں ہے۔ جس کے ساتھ وہ اس کے وقوع کے دلائل کا ادراک کرسکیں جب کہ وہ لذات نفسانیہ میں مشغول ہیں وہ توپیٹ اور شرمگاہ کی شہوت میں ڈوبے ہوئے ہیں اس لحاظ سے وہ چارپایوں کی طرح ہیں جس طرح چارپایوں میں تدبر موجود نہیں ہوتا ان میں بھی موجود نہیں۔\nعلامہ ابن کثیر رحمہ اللہ وضاحت فرماتے ہیں وہ تو اس کے وجود میں ہی شک اور تذبذب میں ہیں بلکہ انتہادرجہ کی جہالت میں مستغرق ہیں۔\n﴿وَقَالَ الَّذِيْنَ كَفَرُوْۤا ءَاِذَا كُنَّا تُرٰبًا وَّاٰبَآؤُنَاۤ اَىِٕنَّا لَمُخْرَجُوْنَ۰۰۶۷ لَقَدْ وُعِدْنَا هٰذَا نَحْنُ وَاٰبَآؤُنَا مِنْ قَبْلُۙ اِنْ هٰذَاۤ اِلَّاۤ اَسَاطِيْرُ الْاَوَّلِيْنَ۰۰۶۸ قُلْ سِيْرُوْا فِي الْاَرْضِ فَانْظُرُوْا كَيْفَ كَانَ عَاقِبَةُ الْمُجْرِمِيْنَ۰۰۶۹ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُنْ فِيْ ضَيْقٍ مِّمَّا يَمْكُرُوْنَ۰۰۷۰﴾\nاور کافروں نے کہا: کیا جب ہم اور ہمارے آبائو اجداد مٹی ہو جائیں گے تو کیا ہمیں (پھر قبروں سے) نکالا جائے گا؟⟦67⟧ بلاشبہ ہمیں اور اس سے پہلے ہمارے آبائو اجداد کو بھی یہ وعدے دیے جاتے رہے ہیں، لیکن یہ تو محض لوگوں کے افسانے ہیں⟦68⟧ کہہ دیجیے: تم زمین میں چلو پھرو، پھر دیکھو مجرموں کا انجام کیسا ہوا؟⟦69⟧ اور (اے نبی صلی اللہ علیہ وسلم!) آپ ان پر غم نہ کریں اور نہ ہی جو وہ مکر و فریب کر رہے ہیں (اس پر) تنگ دل ہوں⟦70⟧"],[5197,"§کفار کا بعث بعد الموت کو بعید سمجھنا اور اس کی تردید\nاللہ تعالیٰ نے بیان فرمایا ہے کہ مشرکین اور منکرین بعثت نے جسموں کے بوسیدہ ہڈیاں بلکہ مٹی ہو جانے کے بعد دوبارہ اُٹھائے جانے کو بہت بعید سمجھا ہے اور وہ کہا کرتے تھے: ﴿لَقَدْ وُعِدْنَا هٰذَا نَحْنُ وَاٰبَآؤُنَا مِنْ قَبْلُۙ﴾ ’’(کہاں کا اُٹھنا اور کیسی قیامت) یہ تو صرف پہلے لوگوں کی کہانیاں ہیں۔‘‘ یعنی یہ جسموں کے دوبارہ زندہ کیے جانے کا وعدہ صرف پہلے لوگوں کی کہانیاں ہیں، لوگوں نے اسے اپنے سے پہلے لوگوں کی کتابوں سے اخذ کیا ہے جبکہ ان کی کوئی حقیقت نہیں ہے۔ اللہ تعالیٰ نے ان کے کفر اور قیامت کے برپا نہ ہونے کے بارے میں ان کے گمان کا جواب دیتے ہوئے فرمایا: ﴿قُلْ﴾ ’’کہہ دیجیے!‘‘ ﴿سِيْرُوْا فِي الْاَرْضِ فَانْظُرُوْا كَيْفَ كَانَ عَاقِبَةُ الْمُجْرِمِيْنَ۰۰۶۹﴾ ’’زمین میں چلو پھرو، پھر دیکھو کہ مجرموں کا انجام کیسا ہوا!‘‘ یعنی جنہوں نے رسولوں کی اور قیامت کے بارے میں ان کے بیان کیے ہوئے ارشادات کی تکذیب کی، ان پر کس طرح اللہ تعالیٰ کا عذاب نازل ہوا اور ان کے درمیان میں سے اللہ تعالیٰ نے اپنے رسولوں اور ان پر ایمان لانے والوں کو کس طرح نجات عطا فرمائی؟ یہ چیز اس بات پر دلالت کرتی ہے کہ حضرات انبیائے کرام بھی سچے تھے اور انہوں نے جس پیغام کو پیش فرمایا وہ بھی سچا تھا، پھر اللہ تبارک و تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو تسلی دیتے ہوئے فرمایا: ﴿وَلَا تَحْزَنْ عَلَیْھِمْ﴾ ’’اور آپ اُن (کے حال) پر غم نہ کریں۔‘‘ جو آپ کے لائے ہوئے دین کی تکذیب کر رہے ہیں، ان پر غم کرنا اور نہ اس قدر افسوس کرنا کہ آپ کا دم ہی نکل جائے۔ ﴿وَلَا تَكُنْ فِيْ ضَيْقٍ مِّمَّا يَمْكُرُوْنَ۰۰۷۰﴾ ’’اور نہ ان چالوں سے جو یہ کر رہے ہیں تنگ دل ہونا۔‘‘ آپ کو نقصان پہنچانے اور آپ کے لائے ہوئے دین کی تردید کرنے میں جو یہ چالیں چل رہے ہیں، ان سے اپنے دل میں تنگی محسوس نہ کرنا کیونکہ اللہ تعالیٰ آپ کو اپنی تائید اور نصرت سے سرفراز فرمائے گا اور ان کی مخالفت اور دشمنی کے باوجود اللہ تعالیٰ آپ کے دین کو مشرق و مغرب میں سربلندی عطا فرمائے گا۔\nیعنی اے محمد صلی اللہ علیہ وسلم ! آپ ان جھٹلانے والوں اور ان کے عدم ایمان کی وجہ سے غمزدہ نہ ہوں۔ اگر آپ کو یہ معلوم ہوجائے کہ ان میں کتنی برائی ہے اور وہ بھلائی کی صلاحیت نہیں رکھتے تو آپ کبھی غمگین ہوں گے نہ آپ تنگدل ہوں گے اور نہ آپ کا دل ان کے مکر و فریب پر کوئی قلق محسوس کرے گا۔ ان کے مکر و فریب کا بُرا انجام آخر کار انہی کی طرف لوٹے گا۔ ﴿وَيَمْكُرُوْنَ وَيَمْكُرُ اللّٰهُؕ وَاللّٰهُ خَيْرُ الْمٰكِرِيْنَ۰۰۳۰﴾ (الانفال:30) ”وہ چال چلتےہیں، اللہ بھی ان کے مقابلے میں چال چلتا ہے، اور اللہ بہترین چال چلنے والا ہے۔“\nدل کے اندھے ہونے کی وجہ سے ہی مشرکین نے آخرت کا یکسر انکار کردیا اور کہا کہ کیا جب ہم اور ہمارے باپ دادے مرنے کے بعد گل سڑ کر مٹی ہوجائیں گے تو اپنی قبروں سے دوبارہ زندہ کر کے اٹھائے جائیں گے ؟ یہ انہونی بات ہے اور محمد صلی اللہ علیہ وسلم سے پہلے اسی طرح کے دوسرے لوگ بھی گزشتہ زمانوں میں پیدا ہوئے، اور لوگوں سے یہی بات کہی، لیکن اب تک تو ایسا ہوا نہیں اس بات کی کوئی حقیقت نہیں ہے اس قسم کے لوگ ہمیشہ جھوٹی باتیں لوگوں کو سناتے رہے ہیں۔ اللہ تعالیٰ نے ان کے اس کفر وعناد اور انکار آخرت کا جواب اپنے نبی کی زبانی یہ دیا کہ تم لوگ ذرا دنیا میں چل کر ان قوموں کا انجام دیکھ لو، جنہوں نے ہمارے انبیا کی اور آخرت کی تکذیب کی کہ ہم نے کس طرح انہیں ہلاک کردیا، اور اپنے انبیا اور ان پر ایمان لانے والوں کو بچا لیا۔ اگر وہ انبیا جھوٹے تھے تو پھر ان قوموں کو کیوں ہلاک کیا گیا، اور جس ذات برحق نے انہیں پہلے پیدا کیا تھا اور پھر انہیں ہلاک کردیا وہ یقیناً انہیں دوبارہ زندہ کرنے پر قادر ہے۔ نبی کریم صلی اللہ علیہ وسلم کو تسلی دی جارہی ہے کہ اگر مشرکین مکہ آپ کی تکذیب کرتے ہیں اور ایمان نہیں لاتے ہیں تو غم نہ کیجیے عنقریب اللہ تعالیٰ ایسے لوگوں کو ظاہر کرے گا جو آپ پر ایمان لائیں گے، اور کفار خس و خاشاک کی مانند مٹ جائیں گے، اور یہ کفار آپ کے خلاف جو سازشیں کرتے ہیں ان سے بھی آپ تنگ دل نہ ہوں، اللہ آپ کی حفاظت کرے گا۔"],[5198,"§سوال کیا ہم اٹھائے جائیں گے اور جواب مجرموں کا انجام دیکھ لو میں ربط\nان دو آیات میں کافروں کا قول یہ نقل کیا گیا ہے کہ مر کر مٹی ہوجانے کے بعد دوبارہ جی اٹھنے کا وعدہ تو ہمارے آباء و اجداد کو بھی دیا گیا تھا پہلے لوگ بھی ایسی باتیں کرتے رہے اور آج بھی ایسی ہی باتیں ہو رہی ہیں حالانکہ جو مرگیا ان میں کوئی شخص بھی آج تک زندہ ہو کر نہیں آیا۔ یہ تو بس ایک افسانوی سی بات ہے جس میں حقیقت کچھ نہیں۔ اور کافروں کے اس قول کا جواب یہ دیا جارہا ہے کہ زمین میں ذرا چل پھر کر تو دیکھو کہ مجرموں کا انجام کیا ہوا تھا ؟ بظاہر ایسا معلوم ہوتا ہے کہ کافروں کے اس قول اور اس کے جواب میں کوئی ربط نہیں۔ حالانکہ اس قول اور اس کے جواب میں گہرا ربط ہے اور ایک بہت بڑی حقیقت سے پردہ اٹھایا گیا ہے اور وہ یہ ہے کہ جو قومیں بھی اللہ کے عذاب سے تباہ ہوئیں سب کی سب قیامت اور بعث بعد الموت کی منکر تھیں۔ اور جو شخص یا جو قوم بھی آخرت کے دن اور اللہ کے حضور اپنے اعمال کی باز پرس کی منکر ہوتی ہے۔ اس کی زندگی کبھی راہ راست پر نہیں رہ سکتی۔ اور وہ دنیا میں شتر بےمہار کی طرح زندگی گزارتا ہے کہ جس کام میں اس نے اپنا فائدہ دیکھا اسی کو اپنا لیا۔ خواہ اس سے دوسروں کا کتنا ہی نقصان کیوں نہ ہو رہا ہو۔ ایسے ہی لوگ فساد فی الارض کے مرتکب ہو کر مجرمانہ زندگی بسر کرنے کے عادی ہوجاتے ہیں اور ایسے مجرموں کو تباہ کردینا ہی اللہ کی سنت جاریہ ہے تاکہ باقی لوگ ایسے لوگوں کے شر سے محفوظ رہ سکیں۔\nدوسرا سبق ان واقعات سے یہ ملتا ہے کہ تاریخ انسانی میں یہ کوئی ایک ہی واقعہ نہیں۔ بلکہ بے شمار تاریخی شواہد سے یہ بات پایہ ثبوت کو پہنچ جاتی ہے کہ رسولوں کا انکار اور آخرت کا انکار کرنے والے مجرموں کا انجام ان کی تباہی اور ہلاکت کی صورت میں ہوا۔ جس سے از خود ایک اور حقیقت سامنے آتی ہے جو یہ ہے کہ کوئی ایسی مقتدر ہستی موجود ہے جو مجرموں کو ایک مقررہ حد سے آگے نکلنے سے روک دیتی ہے اور انھیں تباہ کردیتی ہے۔ یہ دنیا کوئی اندھیر نگری نہیں کہ جس شخص کا جو جی چاہے کرتا پھرے اور اس پر گرفت کرنے والا کوئی نہ ہو۔ پھر جب یہ تجربہ حاصل ہوگیا کہ مجرمین کو ان کے کئے کی سزا مل کے رہتی ہے۔ تو اسی قانون مکافات کا تقاضا یہ ہے کہ جن مجرموں کو اس دنیا میں سزا نہیں ملی یا ان کے جرم سے بہت کم سزا ملی ہے ان سے باز پرس اور ان کی سزا کے لیے ایک دوسرا عالم قائم ہو۔ جس میں تمام مجرموں کو ان کے جرائم کی پوری پوری سزا دی جائے۔ مجرموں کو عذاب سے تباہ کردینا عدل سے سب تقاضے پورے نہیں کرتا۔ اس سے تو صرف یہ ہوتا ہے کہ مجرموں کو زائد جرائم کرنے سے روک دیا جاتا ہے۔ ان کے جرائم کی سزا کے لیے تو یہ دنیا کی زندگی بہت ناکافی ہے۔ اسی طرح جن مظلوموں نے ان مجرموں کے مظالم برداشت کئے تھے۔ ان کی ہلاکت سے ان کو کیا ملا؟ آخر ان لوگوں نے راہِ حق میں جو مظالم و مصائب برداشت کئے ہیں۔ اس کا اجر بھی تو انھیں ملنا چاہیے۔ ان باتوں پر غور کرنے سے واضح طور پر معلوم ہوجاتا ہے کہ عدل و انصاف کے تقاضے پورے کرنے کے لیے آخرت کا قیام انتہائی ضروری ہے۔"],[5199,"§مشرکین کے شبہات کا بیان\nوَ قَالَ الَّذِيْنَ كَفَرُوْۤا ءَاِذَا كُنَّا تُرٰبًا : اللہ کی وحدانیت پر دلائل ذکر کرنے کے بعد ان مشرکین کے کچھ شبہات کا ذکر ہورہا ہے جو آخرت میں اٹھائے جانے کے بارے میں تھے اور قیامت کے قائم ہونے سے پہلے جو خوفناک حوادثات ظہور پذیر ہوں گے چنانچہ مشرکین نے جو قیامت کے واقع ہونے کا انکار کرتے تھے اور انھوں نے کہا کیا جب ہم فوت ہوجائیں گے اور ہم بوسیدہ ہڈیاں اور ٹوٹ پھوٹ جائیں گے تو کیا ہمیں قبروں سے نکالا جائے گا، اور ہم دوبارہ زندہ ہوں گے اس کا وعدہ نہ صرف یہ کہ ہم سے کیا جارہا ہے بلکہ ہم سے پہلے ہمارے آباؤ اجداد سے بھی کیا گیا تھا اگر یہ بات درست ہوتی تو واقع ہوجاتی بس یہ باتیں تو خرافات اور پہلے لوگوں کی کہانیاں ہیں تعجب ہے کہ وہ اٹھائے جانے کا انکار کررہے ہیں جبکہ وہ اس حقیقت کو فراموش کرچکے ہیں کہ ایک ایسادور تھا کہ ان کا وجود نہ تھا پھرا نہیں پیدا کیا گیا اور یہ حقیقت ہے کہ جس ذات نے ان کو پہلے پیدا کیا ہے وہ ذات ان کو دوبارہ لوٹانے پر بھی قادر ہے آپ ان کفار کو آگاہ کریں کہ آپ روئے زمین کے کناروں کا گشت لگائیں اور نگاہ عبرت کے ساتھ ساتھ ملاحظہ کریں کہ پیغمبروں کو جھٹلانے والوں کا انجام کیسا ہوا، ؟ کیا اللہ تعالیٰ نے انھیں تباہ و برباد نہیں کردیا ؟ تو جس طرح زمانہ ماضی کے مجرموں کو تباہ و برباد کردیا، گیا اسی طرح ان کے بعد آنے والے مجرموں کو بھی ان کی بدکرداری کے باعث تباہ و برباد کردیا جائے گا۔\nوَ لَا تَحْزَنْ عَلَيْهِمْ وَ لَا تَكُنْ فِيْ ضَيْقٍ : اس آیت کریمہ میں رسول اللہ صلی اللہ علیہ وسلم کو مطمئن کرنا مقصود ہے کہ آپ غمزدہ نہ ہوں اور آپ ان کے مکروفریب سے غمگین نہ ہوں اگر وہ ایمان قبول نہیں کررہے ہیں اور ان کے مکروفریب سے آپ تنگ دل نہ ہوں اور یہ حقیقت ہے کہ اللہ تعالیٰ ان سے آپ کی حفاظت فرمائیں گے۔\n﴿وَيَقُوْلُوْنَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صٰدِقِيْنَ۰۰۷۱ قُلْ عَسٰۤى اَنْ يَّكُوْنَ رَدِفَ لَكُمْ بَعْضُ الَّذِيْ تَسْتَعْجِلُوْنَ۠۰۰۷۲ وَاِنَّ رَبَّكَ لَذُوْ فَضْلٍ عَلَى النَّاسِ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَشْكُرُوْنَ۰۰۷۳ وَاِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُوْرُهُمْ وَمَا يُعْلِنُوْنَ۰۰۷۴ وَمَا مِنْ غَآىِٕبَةٍ فِي السَّمَآءِ وَالْاَرْضِ اِلَّا فِيْ كِتٰبٍ مُّبِيْنٍ۰۰۷۵﴾\nاور وہ کہتے ہیں: اگر تم سچے ہو تو یہ (عذاب کا) وعدہ کب پورا ہو گا؟⟦71⟧ آپ کہہ دیجیے: جو عذاب تم جلدی طلب کرتے، ہو سکتا ہے (اس میں سے) کچھ تمھارے قریب آ لگا ہو⟦72⟧ اور بے شک آپ کا رب لوگوں پر بہت فضل (فرمانے) والا ہے، لیکن ان کے اکثر شکر نہیں کرتے⟦73⟧ اور بلاشبہ آپ کا رب (وہ باتیں) جانتا ہے جو ان کے سینے چھپاتے ہیں اور جو کچھ وہ ظاہر کرتے ہیں⟦74⟧ اور آسمان و زمین میں غائب کوئی چیز ایسی نہیں جو کھلی کتاب میں (لکھی ہوئی) نہ ہو⟦75⟧"],[5200,"§منکرینِ قیامت\nاللہ تعالیٰ نے بیان فرمایا ہے کہ مشرکین قیامت کے وقوع پذیر ہونے کو بعید سمجھتے ہوئے یہ سوال کیا کرتے تھے: ﴿وَيَقُوْلُوْنَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صٰدِقِيْنَ۰۰۷۱﴾ ’’اور وہ کہتے ہیں کہ اگر تم سچے ہو تو یہ وعدہ کب پورا ہوگا۔‘‘ اللہ تعالیٰ نے انہیں جواب دیتے ہوئے فرمایا: ﴿قُلْ﴾ ’’(اے محمد صلی اللہ علیہ وسلم! ان سے) کہہ دیجیے!‘‘ ﴿عَسٰۤى اَنْ يَّكُوْنَ رَدِفَ لَكُمْ بَعْضُ الَّذِيْ تَسْتَعْجِلُوْنَ۠۰۰۷۲﴾ ’’جس (عذاب کے لیے تم جلدی کر رہے ہو شاید اس میں سے کچھ تمہارے نزدیک آ پہنچا ہو۔‘‘\nسیّدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ اس کے معنی یہ ہیں کہ جس عذاب کے لیے تم جلدی کر رہے ہو شاید اس میں سے کچھ تمہارے نزدیک آ ہی گیا ہو یا وہ عنقریب تمہارے نزدیک آ ہی جائے گا۔ (تفسیر الطبری: 13/20 وتفسیر ابن ابی حاتم: 2917/9) مجاہد، ضحاک، عطاء خراسانی، قتادہ اور سدی رحمہم اللہ نے بھی اسی طرح کہا ہے۔ (وتفسیر ابن ابی حاتم: 2917/9 و تفسیر الطبری: 13/20) اور یہی مراد ہے اس ارشاد باری تعالیٰ سے: ﴿وَيَقُوْلُوْنَ مَتٰى هُوَؕ قُلْ عَسٰۤى اَنْ يَّكُوْنَ قَرِيْبًا۰۰۵۱﴾ (بنی اسرائیل: 51) ’’اور وہ پوچھیں گے کہ ایسا کب ہوگا۔ آپ کہہ دیں: شاید کہ وہ قریب ہی ہو۔‘‘ اور فرمایا: ﴿وَيَسْتَعْجِلُوْنَكَ بِالْعَذَابِؕ وَاِنَّ جَهَنَّمَ لَمُحِيْطَةٌۢ بِالْكٰفِرِيْنَۙ۰۰۵۴﴾ (العنکبوت: 54) ’’وہ آپ سے جلدی عذاب کا مطالبہ کرتے ہیں اور بلاشبہ دوزخ تو کافروں کو گھیر لینے والی ہے۔‘‘ ﴿رَدِفَ لَکُمْ﴾ پر لام اس لیے داخل کیا گیا ہے کہ یہ عَجَّلَ لَکُمْ کے معنی میں ہے جیسا کہ امام مجاہد رحمہ اللہ نے اس ﴿قُلْ عَسٰۤى اَنْ يَّكُوْنَ رَدِفَ لَكُمْ﴾ کے بارے میں یہی کہا ہے۔ (تفسیر الطبری: 13/20)\nپھر اللہ تعالیٰ نے بیان فرمایا ہے کہ وہ آسمانوں اور زمین کے غیب کو جاننے والا ہے اور یقیناً وہی غیب اور حاضر کو جاننے والا ہے جبکہ غیب وہ ہے جو بندوں سے پوشیدہ ہو اور ظاہر وہ ہے جس کا بندوں نے مشاہدہ کیا ہو۔ ابن عباس رضی اللہ عنہما ارشاد باری تعالیٰ: ﴿وَمَا مِنْ غَآىِٕبَةٍ فِي السَّمَآءِ وَالْاَرْضِ اِلَّا فِيْ كِتٰبٍ مُّبِيْنٍ۰۰۷۵﴾ کے بارے میں فرماتے ہیں کہ اس کے معنی ہیں کہ زمین و آسمان میں کوئی مخفی یا ظاہری شے نہیں ہے جسے وہ نہ جانتا ہو۔ (تفسیر الطبری: 15/20 وتفسیر ابن ابی حاتم: 2919/9) اور یہ آیت اللہ تعالیٰ کے اس فرمان: ﴿اَلَمْ تَعْلَمْ اَنَّ اللّٰهَ يَعْلَمُ مَا فِي السَّمَآءِ وَالْاَرْضِؕ اِنَّ ذٰلِكَ فِيْ كِتٰبٍؕ اِنَّ ذٰلِكَ عَلَى اللّٰهِ يَسِيْرٌ۰۰۷۰﴾ (الحج: 70) ’’کیا آپ نہیں جانتے کہ جو کچھ آسمان اور زمین میں ہے اللہ اسے جانتا ہے، یقیناً یہ (سب کچھ) کتاب میں (لکھا ہوا) ہے، بے شک یہ سب اللہ کے لیے بالکل آسان ہے۔‘‘ کی طرح ہے۔\nآخرت اور اس حق کو جھٹلانے والے جسے لے کر رسول مصطفیٰ صلی اللہ علیہ وسلم مبعوث ہوئے ہیں، عذاب کے لیے جلدی مچاتے ہوئے کہتے ہیں : ﴿مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صٰدِقِيْنَ۰۰۷۱﴾ ”اگر تم سچے ہو تو یہ وعدہ کب پور اہوگا ؟“ یہ ان کی جہالت اور حماقت پر مبنی رائے ہے کیونکہ اس وعدے کا وقوع اور اس کا وقت اللہ تعالیٰ نے اپنی تقدیر کے مطابق مقرر کر رکھا ہے۔ اس کا جلدی نہ آنا ان کے کسی مطلوب و مقصود پر دلالت نہیں کرتا۔ اس کے ساتھ ساتھ جس کے بارے میں وہ جلدی مچاتے ہیں اس کے بارے میں ڈراتے ہوئے اللہ تعالیٰ فرماتا ہے :﴿قُلْ عَسٰۤى اَنْ يَّكُوْنَ رَدِفَ لَكُمْ﴾ یعنی ہو سکتا ہے وہ وقت مقرر قریب آگیاہو اور ہو سکتا ہے وہ تم پر واقع ہونے کے قریب ہو۔ ﴿بَعْضُ الَّذِيْ تَسْتَعْجِلُوْنَ۠۰۰۷۲﴾ یعنی وہ عذاب جس کے لیے تم جلدی مچاتے ہو۔\nکافروں کا جلد عذاب لانے کا مطالبہ اس بنا پر نہیں تھا کہ فی الواقعہ یہ چاہتے تھے کہ ان پر عذاب نازل ہو۔ بلکہ اس سے ان کا مطلب یہ ہے کہ وہ آپ کے ان وعدوں کو جھوٹا سمجھتے ہیں۔ تو آپ انہیں کہہ دیجئے کہ یہ عین ممکن ہے کہ ایسے عذاب کا کچھ حصہ عنقریب تمہیں اپنی گرفت میں لے لے۔ عذاب کے اس کچھ حصے کا آغاز تو جنگ بدر سے ہی ہوگیا تھا۔ پھر آپ کی زندگی میں ہی اسے کچھ حصے کی کئی اقساط سے ان کافروں کو سابتہ پیش آتا رہا۔ اور اس عذاب کا زیادہ حصہ بلکہ اصل عذاب تو انہیں آخرت میں بھگتنا پڑے گا۔\nواضح رہے کہ اس آیت میںعسٰی کا لفظ ان معنوں میں نہیں کہ شاید تم پر عذاب آجائے نہ آئے بلکہ یہ شاہانہ انداز کلام ہے اور بڑے لوگ جب اس انداز سے خطاب کریں۔ تو وہ بات یقینی ہی سمجھی جاتی ہے اور اگر ایسا کلام اللہ تعالیٰ کی طرف سے ہو تو پھر اس میں شبہ کی کوئی گنجائش نہیں ہوتی۔ کیونکہ اللہ تعالیٰ کے ارادہ اور فعل میں کچھ فرق نہیں۔ ارادہ تو دُور کی بات ہے اللہ تعالیٰ تو جو کچھ چاہے وہ بھی ہو کے رہتا ہے۔\nوَ مَا مِنْ غَآىِٕبَةٍ فِي السَّمَآءِ وَ الْاَرْضِ اِلَّا فِيْ كِتٰبٍ مُّبِيْنٍ:اور یہ حقیقت ہےکہ کوئی بھی چیز خواہ لوگوںکی نظر سے کتنی ہی پوشیدہ کیوں نہ ہوآسمانوں میںہو یا زمین میں، اللہ کی ذات سے پوشیدہ نہیں ہے اللہ کی ذات کو اس کا علم ہے اور اللہ کے علم نےاس کا احاطہ کیا ہوا ہے اور اسے اپنے ہاں لوح محفوظ میں ثبت فرما دیا ہے اس لیے کہ اللہ کی ذات پاک پر ہرگز کوئی چیز پوشیدہ نہیں ہے۔\nذات کو اس کا علم ہے اس سے کوئی چیز ہرگز پوشیدہ نہیں ہے سورة الحج میںہے: ﴿اَلَمْ تَعْلَمْ اَنَّ اللّٰهَ يَعْلَمُ مَا فِي السَّمَآءِ وَالْاَرْضِؕ اِنَّ ذٰلِكَ فِيْ كِتٰبٍؕ اِنَّ ذٰلِكَ عَلَى اللّٰهِ يَسِيْرٌ۰۰۷۰﴾ (الحج:70) ”کیا آپ کو معلوم نہیں کہ بلاشبہ اللہ کی ذات کو اس چیز کا علم ہے جو آسمانوں اور زمین میںہے یقیناً ہر چیز لوح محفوظ میں درج ہے اور یہ حقیقت ہے کہ اللہ تعالیٰ کی ذات پر یہ آسان ہے۔“\n﴿اِنَّ هٰذَا الْقُرْاٰنَ يَقُصُّ عَلٰى بَنِيْۤ اِسْرَآءِيْلَ اَكْثَرَ الَّذِيْ هُمْ فِيْهِ يَخْتَلِفُوْنَ۰۰۷۶ وَاِنَّهٗ لَهُدًى وَّرَحْمَةٌ لِّلْمُؤْمِنِيْنَ۰۰۷۷ اِنَّ رَبَّكَ يَقْضِيْ بَيْنَهُمْ بِحُكْمِهٖۚ وَهُوَ الْعَزِيْزُ الْعَلِيْمُۚ۰۰۷۸ فَتَوَكَّلْ عَلَى اللّٰهِؕ اِنَّكَ عَلَى الْحَقِّ الْمُبِيْنِ۰۰۷۹ اِنَّكَ لَا تُسْمِعُ الْمَوْتٰى وَلَا تُسْمِعُ الصُّمَّ الدُّعَآءَ اِذَا وَلَّوْا مُدْبِرِيْنَ۰۰۸۰ وَمَاۤ اَنْتَ بِهٰدِي الْعُمْيِ عَنْ ضَلٰلَتِهِمْؕ اِنْ تُسْمِعُ اِلَّا مَنْ يُّؤْمِنُ بِاٰيٰتِنَا فَهُمْ مُّسْلِمُوْنَ۰۰۸۱ وَاِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ اَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ الْاَرْضِ تُكَلِّمُهُمْۙ اَنَّ النَّاسَ كَانُوْا بِاٰيٰتِنَا لَا يُوْقِنُوْنَࣖ۰۰۸۲﴾\nبے شک یہ قرآن بنی اسرائیل پر اکثر وہ باتیں بیان کرتا ہے جن میں وہ اختلاف کرتے ہیں⟦76⟧ اور بلاشبہ یہ (قرآن) مومنوں کے لیے ہدایت اور رحمت ہے⟦77⟧ بے شک آپ کا رب ان کے درمیان اپنے حکم سے فیصلہ کرے گا، اور وہ نہایت غالب ہے، بہت علم والا ہے⟦78⟧ لہٰذا (اے نبی صلی اللہ علیہ وسلم!) آپ اللہ پر توکل کریں، بلاشبہ آپ واضح حق پر ہیں⟦79⟧ آپ مُردوں کو نہیں سنا سکتے، اور نہ آپ بہروں کو (اپنی) پکار سنا سکتے ہیں، جبکہ وہ پیٹھ کے بل پھر جائیں ⟦80⟧ اور نہ آپ اندھوں کو ان کی گمراہی سے راہِ ہدایت پر لا سکتے ہیں، آپ تو بس انھیں ہی سنا سکتے ہیں جو ہماری آیات پر ایمان لاتے ہیں، تو وہی فرماں بردار ہیں⟦81⟧ اور جب ان پر (قربِ قیامت کے وعدے کی) بات پوری ہو جائے گی تو ہم ان کے لیے زمین سے ایک جانور نکالیں گے، وہ ان سے کلام کرے گا کہ بے شک یہ لوگ ہماری آیات پر یقین نہیں رکھتے تھے⟦82⟧"],[5201,"§قرآن بنی اسرائیل کے اختلاف کو بیان کرتا ہے\nاللہ تعالیٰ نے اپنی کتاب عزیز کے بارے میں بیان فرمایا ہے جو ہدایت، بیان اور فرقان پر مشتمل ہے کہ یہ حاملین تورات و انجیل بنی اسرائیل کے سامنے اکثر باتیں جن میں وہ اختلاف کرتے ہیں، بیان کر دیتی ہے جیسا کہ سیّدنا عیسیٰ علیہ السلام کے بارے میں ان میں اختلاف ہے کہ یہودیوں نے تو ان کے بارے میں شرم ناک افترا پردازی سے کام لیا جبکہ عیسائیوں نے ان کے بارے میں بے حد غلو کیا جبکہ قرآن مجید نے ان کے بارے میں ایک ایسے درمیانے موقف کو اختیار کیا ہے جو حق و عدل پر مبنی ہے کہ وہ اللہ کے بندے ہیں اور اس کے مرسلین و انبیائے کرام میں سے ایک پیغمبر صلی اللہ علیہ وسلم بھی جیسا کہ ارشاد باری تعالیٰ ہے: ﴿ذٰلِكَ عِيْسَى ابْنُ مَرْيَمَۚ قَوْلَ الْحَقِّ الَّذِيْ فِيْهِ يَمْتَرُوْنَ۰۰۳۴﴾ (مریم: 34) ’’یہ مریم کے بیٹے عیسیٰ ہیں (اور یہ) سچی بات ہے جس میں لوگ شک کرتے ہیں۔‘‘"],[5202,"§توکل کا حکم\nارشاد باری تعالیٰ ہے: ﴿فَتَوَكَّلْ عَلَى اللّٰهِؕ﴾ ’’پس آپ اللہ پر بھروسا کریں۔‘‘ اپنے تمام امور میں۔ اور اپنے رب کے پیغام کو پہنچا دیں، ﴿اِنَّكَ عَلَى الْحَقِّ الْمُبِيْنِ۰۰۷۹﴾ ’’بے شک آپ تو حق صریح پر ہیں۔‘‘ یعنی آپ حق صریح پر ہیں، خواہ وہ لوگ آپ کی مخالفت ہی کیوں نہ کریں جن پر بد بختی لکھ دی گئی ہے۔ اور جن کے بارے میں آپ کے رب کا حکم قرار دیا جا چکا ہے کہ وہ ایمان نہیں لائیں گے، خواہ ان کے پاس ہر طرح کی نشانی آ جائے، اسی لیے فرمایا: ﴿اِنَّكَ لَا تُسْمِعُ الْمَوْتٰى﴾ ’’کچھ شک نہیں کہ آپ مردوں کو (بات) نہیں سنا سکتے۔‘‘ یعنی انہیں کوئی بات نہیں سنا سکتے جو انہیں نفع دے سکے، اسی طرح ان لوگوں کے دلوں پر پردے ہیں اور ان کے کانوں میں کفر کا بوجھ ہے، اسی لیے فرمایا: ﴿وَلَا تُسْمِعُ الصُّمَّ الدُّعَآءَ اِذَا وَلَّوْا مُدْبِرِيْنَ۰۰۸۰ وَمَاۤ اَنْتَ بِهٰدِي الْعُمْيِ عَنْ ضَلٰلَتِهِمْؕ اِنْ تُسْمِعُ اِلَّا مَنْ يُّؤْمِنُ بِاٰيٰتِنَا فَهُمْ مُّسْلِمُوْنَ۰۰۸۱﴾ ’’اور نہ آپ بہروں کو جبکہ وہ پیٹھ پھیر کر پھر جائیں آواز سنا سکتے ہیں اور نہ اندھوں کو گمراہی سے (آپ) رستہ دکھا سکتے ہیں آپ تو انہی کو سنا سکتے ہیں جو ہماری آیتوں پر ایمان لاتے ہیں سو وہ فرمانبردار ہیں۔‘‘ آپ کی بات کو تو وہ سنے گا جو بڑا سمیع و بصیر ہو۔ اور نافع سمع و بصر وہ ہوتی ہے جو دل اور بصیرت میں ہو، اللہ کے آگے جھکنے والا ہو اور اللہ تعالیٰ نے اپنے رسولوں کی زبانی جو پیغام نازل فرمایا ہے اس کی اطاعت کرنے والا ہو۔"],[5203,"§زمین سے ایک جانور کا نکلنا\nآخر زمانے میں زمین سے یہ جانور اس وقت نکلے گا جب لوگ خراب ہو جائیں گے، اللہ تعالیٰ کے احکام کو بدل دیں گے اور دین حق میں تبدیلی کر دیں گے تو اس وقت اللہ تعالیٰ زمین سے ان کے لیے ایک جانور نکالے گا۔ ایک قول کے مطابق یہ جانور مکہ سے اور دوسرے قول کے مطابق کسی دوسری جگہ سے نکلے گا جیسا کہ اس کی تفصیل، ان شاء اللہ تعالیٰ، آگے آ رہی ہے، یہ جانور لوگوں سے کلام کرے گا، ابن عباس رضی اللہ عنہما، حسن اور قتادہ رحمہم اللہ کا قول ہے، نیز سیّدنا علی رضی اللہ عنہ سے بھی روایت ہے کہ یہ لوگوں سے مخاطب ہو کر کلام کرے گا۔ (تفسیر ابن ابی حاتم: 2926/9) اس جانور کے بارے میں بہت سی احادیث و آثار وارد ہیں جن میں سے چند حسب ذیل ہیں۔ وَاللہُ الْمُسْتَعَانُ!\n(1) امام احمد رحمہ اللہ نے حذیفہ بن اَسید غفاری رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہم پر ایک بالا خانے سے متوجہ ہوئے جبکہ ہم قیامت کے بارے میں گفتگو کر رہے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: ’’قیامت اس وقت تک قائم نہ ہو گی جب تک تم دس نشانیاں نہ دیکھ لو: (1) مغرب سے سورج کا طلوع ہونا (2) دھواں (3) زمین کا جانور (4) یاجوج ماجوج کا خروج (5)عیسیٰ ابن مریم علیہما السلام کا خروج (6) دجال اور زمین میں دھنسنے کے تین واقعات (7) مغرب میں زمین میں دھنسنے کا واقعہ (8) مشرق میں زمین میں دھنسنے کا واقعہ (9) جزیرۃ العرب میں زمین میں دھنسنے کا واقعہ اور (10) ایک آگ جو عدن کے زیریں علاقے سے نکلے گی اور لوگوں کو ہانک کر لے جائے گی۔ یا آپ صلی اللہ علیہ وسلم نے یہ فرمایا کہ وہ لوگوں کو جمع کرے گی اور انہی کے ساتھ رات گزارے گی جہاں وہ رات گزاریں گے اور انہی کے ساتھ دوپہر کرے گی جہاں وہ دوپہر کریں گے۔‘‘\n(مسند احمد، حدیث: 16144)\n(2) امام مسلم رحمہ اللہ نے عبداللہ بن عمرو رضی اللہ عنہما سے روایت کیا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سن کر ایک حدیث کو یاد رکھا ہے جسے ابھی تک نہیں بھولا اور وہ یہ کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ ارشاد فرماتے ہوئے سنا: «اِنَّ اَوَّلَ الْآيَاتِ خُرُوجًا، طُلوعُ الشَّمْسِ مِنْ مَّغْرِبِهَا، وَخُرُوجُ الدَّابَّةِ عَلَى النَّاسِ ضُحيً، وَّاَيُّهُمَا مَا كَانَتْ قَبْلَ صَاحِبَتِهَا فَالْاُخْرٰى عَلٰى اِثْرِهَا قَرِيْبٌ» ’’قیامت کی اولین نشانیاں یہ ہیں: سورج کا مغرب سے طلوع ہونا، چاشت کے وقت جانور کا لوگوں کے سامنے نکلنا، ان میں سے جو نشانی پہلے ظاہر ہوئی تو دوسری بھی اس کے فوراً بعد ظاہر ہو جائے گی۔‘‘ (صحیح مسلم، حدیث: 2941)\n(3) امام مسلم رحمہ اللہ نے اسے اپنی صحیح میں سیّدنا ابوہریرہ رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «بَادِرُوا بِالْاَعْمَالِ سِتًّا: طُلُوعَ الشَّمْسِ مِنْ مَّغْرِبِهَا، اَوِ الدُّخَانَ، اَوِ الدَّجَّالَ، اَوِ الدَّابَّةَ اَوْ خَاصَّةَ اَحَدِكُمْ، اَوْ اَمْرَ الْعَامَّةِ» ’’چھ باتوں کے ظاہر ہونے سے پہلے پہلے جلدی سے نیک اعمال کر لو! (اور وہ چھ باتیں یہ ہیں): (1) سورج کا مغرب سے طلوع ہونا اور (2) دھواں (3) دجال (4) جانور (5) موت (6) قیامت۔‘‘\n(صحیح مسلم، حدیث: 2947)\n(4) امام ابو داؤد طیالسی رحمہ اللہ نے سیّدنا ابوہریرہ رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «تَخْرُجُ دَابَّةُ الْاَرْضِ مَعَهَا عَصَا مُوسٰى وَخاَتَمُ سُلَيْمَانَ، تَخْطِمُ اَنْفَ الْكَافِرِ بِالْعَصَا، وَتُجْلِي وَجْهَ الْمُؤْمِنِ بِالْخَاتَمِ، حَتّٰى يَجْتَمِعَ النَّاسُ عَلَى الْخِوَانِ يُعْرَفُ الْمُؤْمِنُ مِنَ الْكَافِرِ» ’’زمین کا جانور نکلے گا تو اس کے پاس موسیٰ علیہ السلام کا عصا اور سلیمان علیہ السلام کی انگوٹھی ہو گی، وہ کافر کی ناک پر عصا مارے گا اور مومن کے چہرے کو انگوٹھی سے روشن کر دے گا حتیٰ کہ لوگ ایک دستر خوان پر جمع ہوں گے، مومن اور کافر پہچانے جائیں گے۔‘‘\n(مسند ابی داؤد الطیالسی: حدیث: 2687 ومسند احمد، حدیث: 10361)\nابن جریج رحمہ اللہ نے ابن زبیر رضی اللہ عنہما سے روایت کیا ہے کہ انہوں نے جانور کا حلیہ اس طرح بیان کیا کہ اس کا سر بیل کے سر جیسا، اس کی آنکھیں خنزیر کی آنکھوں جیسی، اس کے کان ہاتھی کے کانوں جیسے، اس کے سینگ بارہ سنگے کے سینگوں جیسے، اس کی گردن شتر مرغ کی گردن جیسی، اس کا سینہ شیر کے سینے جیسا، اس کا رنگ چیتے کے رنگ جیسا، اس کا پہلو بلے کے پہلو جیسا، اس کی دم مینڈھے کی دم جیسی اور اس کی ٹانگیں اونٹ کی ٹانگوں جیسی ہوں گی، اس کے ہر دو جوڑوں کے درمیان بارہ ہاتھ کا فاصلہ ہوگا، جب وہ جانور نکلے گا تو اس کے پاس موسیٰ علیہ السلام کا عصا اور سلیمان علیہ السلام کی انگوٹھی بھی ہو گی، وہ ہر مومن کے چہرے پر موسیٰ علیہ السلام کے عصا کے ساتھ سفید نکتہ لگا دے گا، یہ نکتہ پھیل جائے گا حتیٰ کہ اس کی وجہ سے مومن کا چہرہ چمک اُٹھے گا اور ہر کافر کے چہرے پر وہ سلیمان علیہ السلام کی انگوٹھی کے ساتھ سیاہ نکتہ لگا دے گا اور وہ نکتہ اس قدر پھیل جائے گا کہ اس سے کافر کا چہرہ کالا سیاہ ہو جائے گا حتیٰ کہ لوگ بازاروں میں خرید و فروخت کرتے ہوئے کہیں گے کہ اے مومن! یہ چیز کتنے کی ہے، اے کافر! اس چیز کی کتنی قیمت ہے؟ حتیٰ کہ گھر والے دستر خوان پر بیٹھیں گے تو وہ پہچانتے ہوں گے کہ ان کے گھر کا کون سا فرد مومن ہے اور کون سا فرد کافر ہے، پھر یہ جانور ان سے یہ بھی کہے گا کہ اے فلاں شخص! تجھے بشارت ہو کہ تو اہل جنت میں سے ہے اور اے فلاں! تو اہل دوزخ میں سے ہے، اسی جانور کی طرف اس ارشاد باری تعالیٰ میں اشارہ ہے: ﴿وَاِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ اَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ الْاَرْضِ تُكَلِّمُهُمْۙ اَنَّ النَّاسَ كَانُوْا بِاٰيٰتِنَا لَا يُوْقِنُوْنَࣖ۰۰۸۲﴾ ’’اور جب ان پر (عذاب کی) بات واقع ہو گی تو ہم ان کے لیے زمین میں سے ایک جانور نکالیں گے جو اُن سے کلام کرے گا کہ بے شک یہ لوگ ہماری آیات پر یقین نہیں رکھتے۔‘‘ (تفسیر القرطبی: 236/13 وتفسیر ابن ابی حاتم: 2924/9)\nیہ آیت کریمہ اس بارے میں خبر دیتی ہے کہ قرآن کتب سابقہ کی تصدیق وتوضیح اور ان کی تفصیل بیان کرتا ہے۔ چونکہ کتب سابقہ کے بارے میں بنی اسرائیل میں اشتباہ و اختلاف واقع ہوا ہے اس لیے قرآن کریم نے ایسی توضیحات بیان کی ہیں جن سے اشکال دور ہوجاتا ہے اور مختلف فیہ مسائل میںراہ صواب واضح ہوجاتی ہے اور جب اس میں جلالت و وضاحت، ہر اختلاف کا ازالہ اور ہر اشکال کی تفصیل جمع ہے تو یہ اللہ تعالیٰ کی طرف سے اپنے بندوں پرسب سے بڑی نعمت ہے، مگر سب بندے اللہ تعالیٰ کی اس نعمت کا شکر ادا نہیں کرتے۔ اس لیے واضح فرمادیا کہ قرآن کا فائدہ، اس کی روشنی اور راہنمائی صرف اہل ایمان کے لیے مختص ہے۔ پس فرمایا:﴿وَاِنَّهٗ لَهُدًى﴾ ”اور بے شک یہ ہدایت ہے۔“ یعنی ضلالت، شبہات اور گمراہی کے جھاڑ جھنکار کے درمیان راہ ہدایت ہے ﴿وَّ رَحْمَةٌ﴾ ”اور رحمت ہے۔“ اس سے ان کے سینے ٹھنڈے اور ان کے تمام دینی اور دنیاوی اُمور درست ہوتے ہیں ﴿ لِّلْمُؤْمِنِيْنَ﴾ یہ ان لوگوں کے لیے رحمت ہے جو اس پر ایمان رکھتے ہیں، اس کی تصدیق کرتے ہوئے اس کو قبول کرتے ہیں، اس میں تدبر اور اس کے معانی میں غور و فکر کرتے ہیں۔ پس انہی لوگوں کو صراط مستقیم کی طرف راہنمائی اور رحمت سے سرفراز کیاجائے گا جو سعادت اور فوز و فلاح کو متضمن ہے۔\nیعنی جلب منفعت، دفع ضرر، تبلیغ رسالت،اقامت دین اور دشمنان اسلام کے خلاف جہاد کرنے میں آپ اپنے رب پر بھروسہ کیجئے ! ﴿اِنَّكَ عَلَى الْحَقِّ الْمُبِيْنِ۰۰۷۹﴾ ”بے شک آپ واضح حق پر ہیں۔“ وہ شخص جو حق پر ہو، حق کی طرف دعوت دیتا ہو اور اس کی مدد کرتا ہو، اللہ تعالیٰ پر توکل کرنے میں کسی دوسرے کی نسبت زیادہ مستحق ہے۔کیونکہ وہ ایک ایسے معاملے کے لیے کوشاں ہے جس کی صداقت قطعی ہے اور جس میں کوئی شک و شبہ نہیں،نیز یہ انتہائی واضح طور پر حق ہے یہ کوئی چھپی ہوئی چیز ہے نہ اس میں کوئی اشتباہ ہے۔ جب آپ حق کی خاطر کھڑے ہوجاتے ہیں اور اس بارے میں اللہ تعالیٰ پر بھروسہ کرتے ہیںتو کسی کا گمراہ ہونا آپ کوکوئی نقصان نہیں دے سکتا اور ان کو ہدایت دینا آپ کی ذمہ داری نہیں ہے، اس لیے فرمایا:﴿اِنَّكَ لَا تُسْمِعُ الْمَوْتٰى وَلَا تُسْمِعُ الصُّمَّ الدُّعَآءَ﴾ ”کچھ شک نہیں کہ آپ مُردوں کو سنا سکتے ہیںنہ بہروں کو۔“ یعنی جب آپ ان کوپکارتے اور ندا دیتے ہیں اور خاص طور پر ﴿اِذَا وَلَّوْا مُدْبِرِيْنَ۰۰۸۰﴾ ”اس وقت جبکہ وہ منہ پھیر کر جا رہے ہوں“ تب یہ عدم سماع کی انتہا کو پہنچے ہوئے ہوتے ہیں۔ ﴿وَمَاۤ اَنْتَ بِهٰدِي الْعُمْيِ عَنْ ضَلٰلَتِهِمْؕ﴾ ”اور نہ آپ اندھوں کو گمراہی سے (نکال کر) راستہ دکھا سکتے ہیں۔“ جیسا کہ اللہ تعالیٰ نے فرمایا: ﴿اِنَّكَ لَا تَهْدِيْ مَنْ اَحْبَبْتَ وَلٰكِنَّ اللّٰهَ يَهْدِيْ مَنْ يَّشَآءُۚ﴾ (القصص:56) ”آپ جسے چاہیں اسے ہدایت نہیں دے سکتے بلکہ اللہ جسے چاہے ہدایت دیتا ہے۔“ ﴿اِنْ تُسْمِعُ اِلَّا مَنْ يُّؤْمِنُ بِاٰيٰتِنَا فَهُمْ مُّسْلِمُوْنَ۰۰۸۱﴾ ”آپ تو ان ہی کو سنا سکتے ہیں جو ہماری آیتوں پر ایمان لاتے ہیں اور وہ مطیع ہوجاتے ہیں۔“ یہی لوگ جو آپ کے سامنے سر اطاعت خم کرتے ہیں یہی لوگ ہیں جو اللہ تعالیٰ کی آیات پر ایمان رکھتے ہیں اپنے اعمال اور اپنی اطاعت کے ذریعے سے ان آیات کی اتباع کرتے ہیں، جیسا کہ اللہ تعالیٰ کا ارشاد ہے : ﴿اِنَّمَا يَسْتَجِيْبُ الَّذِيْنَ يَسْمَعُوْنَ وَالْمَوْتٰى يَبْعَثُهُمُ اللّٰهُ ثُمَّ اِلَيْهِ يُرْجَعُوْنَ࣡۰۰۳۶﴾ (الانعام:36) ”حق کو صرف وہی لوگ قبول کرتے ہیں جو سنتے ہیں اور مُردوں کو تو اللہ تعالیٰ قیامت کے روززندہ کرے گا پھر وہ اللہ تعالیٰ ہی کی طرف لوٹائے جائیں گے۔“\nابن جریر، ابن ابی حاتم، حاکم اور ابن مردویہ رحمہم اللہ وغیرہم نے اس آیت کی تفسیر میں ابن عمر رضی اللہ عنہما کا قول نقل کیا ہے کہ جب قیامت کا وقت قریب ہوگا اور زمین میں کوئی بھلائی کا حکم دینے والا اور برائی سے روکنے والا باقی نہیں رہے گا، تو اللہ تعالیٰ زمین سے ایک جانور نکالے گا جو لوگوں سے کہے گا کہ تم لوگ ان آیتوں پر ایمان نہیں لاتے تھے جن میں قیامت کی خبر دی گئی ہے تو میں قرب قیامت کی نشانی ہوں مجھے اس اللہ نے یہ قوت گویائی دی ہے جو قیامت لانے پر قادر ہے۔\nصحیح مسلم میں عبداللہ بن عمرو رضی اللہ عنہما سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا : قیامت کی ابتدائی نشانیوں میں سے یہ ہے کہ آفتاب مغرب سے طلوع ہوگا اور صبح کے وقت اچانک ایک جانور نکل کر لوگوں کے سامنے آجائے گا اور دونوں نشانیاں ایک دوسرے کے قریب ہوں گی۔ مفسرین لکھتے ہیں کہ یا تو وہ جانور صرف ایک ہوگا، جو لوگوں سے مذکور بالا بات کرے گا یا مقصود جانور کی ایک قسم ہے، جس کی ایک بڑی تعداد یک بیک زمین کے مختلف حصوں میں ظاہر ہوگی اور سبھی اللہ کے حکم سے وہی بات کریں گے جس کا اوپر ذکر آچکا ہے۔\nوہ جانور کیسا ہوگا کہاں ظاہر ہوگا اور اس سے متعلق دوسری بہت سی تفصیلات کا ذکر ایسے اخبار و آثار میں آیا ہے جو قابل اعتبار نہیں اور نہ ہی اصل موضوع کو سمجھنے کے لیے ان کی ضرورت ہے، اسی لیے ان کے ذکر کرنے سے گریز کرنا ہی بہتر ہے۔"],[5204,"§بنی اسرائیل کے باہمی اختلافات کے متعلق قرآن کی نشاندہی\nیہ اختلاف صرف عقائد میں ہی نہیں تھے بلکہ احکام قصص میں بھی تھے۔ عقائد کے اختلاف یہ تھے کہ مثلاً یہود ہی کا ایک فرقہ آخرت کا منکر بن گیا تھا۔ پھر ان میں کچھ فرقوں کا آخرت کے متعلق تصور ہی غلط تھا جس کا قرآن نے کئی مواقع پر ذکر فرمایا ہے۔ عیسائیوں میں عیسیٰ علیہ السلام کے بارے میں اختلاف تھے کچھ انہیں اللہ کا بیٹا قرار دیتے تھے کچھ انہیں اللہ ہی سمجھتے تھے۔ کچھ بیٹے کو باپ کی طرح قدیم سمجھتے تھے اور کچھ اسے مخلوق اور حاوث قرار دیتے تھے۔ کچھ یہ کہتے تھے کہ اللہ نے اپنے سارے اختیارات اپنے بیٹے کو سونپدیئے ہیں۔ کچھ کہتے ہیں کہ وہ تین میں کا تیسرا ہیں۔ اور احکام میں اختلاف ان کی تحریفات لفظی اور معنی کی بنا پر تھا۔ بہت سی آیتوں کو وہ چھپا جاتے تھے اور بہت سی آیات کی تحریف کرلیتے تھے اور ان کی ایسی حرکات بھی قرآن میں متعدد مقامات پر بالوضاحت مذکور ہیں۔ ان سب اختلافات کا نتیجہ یہ تھا کہ وہ بہتر فرقوں میں بٹ گئے تھے۔ قرآن نے آکر ان اختلافات کو بیان بھی کیا اور ان میں صحیح راہ بھی متعین فرما دی کہ فلاں مسئلہ میں اصل حقیقت یہ ہے اور فلاں میں حقیقت اتنی ہے۔ یہاں اس آیت کے ذکر کرنے سے مطلب یہ ہے اس وقت جو اختلافات کفار مکہ اور مسلمانوں کے درمیان ہیں ان میں بھی قرآن صحیح راستے کی نشان دہی کر رہا ہے۔"],[5205,"§ہدایت پانے کی چار ممکنہ صورتیں\nیعنی ان کافروں کے ہدایت پانے کی چار ہی صورتیں ممکن ہیں۔ جن میں سے دو سننے سے تعلق رکھتی ہیں اور دو دیکھنے سے۔ سننے کی پھر دو صورتیں ہیں۔ ایک یہ کہ صرف زندہ سن سکتا ہے۔ مردہ نہیں سن سکتا۔ اب چونکہ ان کے دل مرچکے ہیں۔ لہٰذا اس طریقہ سے ان کی ہدایت ناممکن ہے۔ دوسری صورت یہ ہے کہ سماعت رکھنے والا تو بات سن سکتا ہے۔ لیکن بہرا نہیں سن سکتا۔ یہ لوگ چونکہ دل کے بہرے ہیں۔ لہٰذا یہ صورت بھی ناممکن ہوئی۔ تیسری صورت یہ تھی کہ ہو تو بہرا مگر کم از کم وہ توبہ تو کرتا ہو۔ اور بات سننے کی کچھ خواہش تو رکھتا ہو۔ اس صورت میں بھی کچھ اشاروں اور انداز خطاب سے اس کے کچھ نہ کچھ پلے پڑ سکتا تھا۔ مگر یہ لوگ تو پیٹھ پھیرے بھاگے جارہے ہیں لہٰذا یہ تیسری صورت بھی ناممکن ہوئی۔ اور چوتھی صورت یہ ہے کہ ہدایت کا طالب اگر کچھ سن سکتا تو دیکھ کر بات سمجھ لیتا۔ اگر اسے کوئی اشارہ سے راہ بتلائے تو اس سیدھی راہ کی طرف آئے۔ یا کم از کم جو لوگ سیدھی راہ پر چل رہے ہیں انھیں دیکھ کر ہی ان کے پیچھے ہولے۔ اب یہ کفار چونکہ دلوں کے اندھے بھی ہیں۔ لہٰذا ان کے ہدایت پانے کی چوتھی صورت بھی ناممکن ہوگئی۔ لہٰذا ایسے مردہ دل، دل کے بہرے اور اندھے لوگوں سے ہدایت پانے اور اسلام لانے کی توقع رکھنا بےکار ہے۔\nاس آیت میں ﴿دَآبَّةً﴾ کا لفظ استعمال ہوا ہے۔ جس کا مادہ د ب ب ہے اور دبّ بمعنی عام رفتار (مشی) ہلکی یا سست رفتار سے چلنا ہے۔ اور دابہ ہر اس جاندار کو کہتے ہیں جو ہلکی چال چلتا ہو۔ خواہ وہ پیٹ کے بل چلے جیسے سانپ اور چھپکلی وغیرہ یا خواہ دو پاؤں پر چلے جیسے انسان اور بندروں کی بعض اقسام یا چار پاؤں پر چلے جیسے وحشی جانور اور چوپائے وغیرہ۔ نیز مذکر و مؤنث کے لیے اس کا یکساں استعمال ہوتا ہے۔ اور قرآن میں یہ لفظ دیمک کے لیے بھی آیا ہے۔ جس نے سیدنا سلیمان علیہ السلام کی وفات کے بعد ان کی لاٹھی کو چاٹ کھایا تھا اور وہ ٹوٹ گئی تھی۔ (14:38)\nاس آیت میں جس دابہّ کا ذکر ہے۔ معلوم تو یہی ہوتا ہے کہ وہ انسان کی شکل کا یا اس سے ملتا جلتا ہوگا۔ ﴿ٰتُکَلِّمُھُمْ﴾ کا لفظ اس قیاس کی تائید کرتا ہے۔ تاہم یہ ضروری بھی نہیں۔ جس طرح اس دابہّ کا خروج خرقِ عادت ہوگا اسی طرح اس کا لوگوں سے کلام کرنا بھی خرق عادت ہوسکتا ہے۔ بہرحال یہ یقینی بات ہے کہ اس کا خروج علامات قرب قیامت میں سے ایک علامت ہے جیسا کہ درج ذیل احادیث سے واضح ہے :"],[5206,"§دابة الارض کی حقیقت\nسیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ”تین باتیں جب ظاہر ہوجائیں تو اس وقت کسی کو ایمان لانے کا کچھ فائدہ نہ ہوگا۔ الا یہ کہ وہ پہلے ایمان لاچکا ہو اور نیک اعمال کرتا رہا ہو۔ ایک سورج کا مغرب سے طلوع ہونا، دوسرے دجال کا نکلنا اور تیسرے دابة الارض کا خروج۔“ (مسلم: حدیث: 158)\nسیدنا حذیفہ بن اسید غفاری رضی اللہ عنہ فرماتے ہیں کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم ہم پر برآمد ہوئے جبکہ ہم گفتگو میں مشغول تھے۔ آپ صلی اللہ علیہ وسلم نے پوچھا :”کیا باتیں کر رہے تھے ؟“ ہم نے عرض کیا : قیامت کا ذکر کرتے تھے : آپ صلی اللہ علیہ وسلم نے فرمایا : قیامت اس وقت تک قائم نہ ہوگی۔ جب تک تم اس سے پہلے دس نشانیاں نہ دیکھ لو۔ پھر آپ صلی اللہ علیہ وسلم نے یہ نشانیاں بتلائیں۔ دھواں، دجال، دابة الارض۔ سورج کا مغرب سے نکلنا، نزول عیسیٰ ابن مریم علیہما السلام، یاجوج ماجوج کا خروج۔ تین مقامات پر زمین کا خیف مشرق میں، مغرب میں، جزیرہ عرب میں اور ان نشانیوں کے بعد ایک آگ پیدا ہوگی جو لوگوں کو یمن سے نکال کر ہانکتی ہوئی ان کے محشر (سرزمین شام) کی طرف لے جائے گی۔“ (مسلم، حدیث: 2901)\nبعض دوسری روایات سے معلوم ہوتا ہے کہ قیامت سے پہلے صفا پہاڑی پھٹے گی اس میں سے ایک جانور نکلے گا جو لوگوں سے باتیں کرے گا کہ اب قیامت نزدیک ہے اور سچے ایمان والوں اور چھپے منکروں کو نشان دے کر جدا کردے گا۔ دابة الارض سے متعلق بہت سے رطب و یابس اقوال و روایات بعض تفاسیر میں درج ہیں۔ مگر معتبر روایات سے تقریباً اتنا ہی ثابت ہے جو اُوپر درج ہے۔"],[5207,"§انسان کو جس بات کی سمجھ نہ آئے انکار کر دیتا ہے\nاس آیت میں میدان محشر کا ایک منظر پیش کیا گیا ہے۔ مجرموں کی ان کے جرائم کے لحاظ سے الگ الگ جماعتیں بنادی جائیں گی۔ جیسے مثلاً مشرکوں کی الگ جماعت ہوگی۔ کافروں کی الگ، منافقوں کی الگ، اور بعض مفسرین نے اس سے یہ مراد لی ہے کہ مکذبین کو محشر کی طرف لے چلیں گے اور وہ اتنی کثرت سے ہوں گے کہ پیچھے چلنے والوں کو آگے بڑھنے سے روک دیا جائے گا۔ جیسا کہ انبوہ کثیر میں انتظام قائم رکھنے کے لیے کیا جاتا ہے۔ وزع کا بنیادی معنی صرف روک دینا یا روکے رکھنا ہے۔ لہٰذا اس کے معنی میں دونوں طرح مطالب کی گنجائش موجود ہے۔\nیعنی وہ حق سےمکمل طور پر گریزاں اور متنفر ہیںکیونکہ آدمی رودر رو بھی کوئی بات نہیں سن پاتا چہ جائیکہ اس وقت سن سکے جب وہ منہ موڑ لے اور پیٹھ پھیرےہوئے ہو۔ قرآن کریم کی اس آیت سے یہ بھی معلوم ہوا کہ سماع موتٰی کا عقیدہ قرآن کے خلاف ہے۔ مردے کسی کی بات نہیں سن سکتے۔ البتہ اس سے صرف دو صورتیں مستثنیٰ ہوں گی جہاں سماعت کی صراحت کسی نص سے ثابت ہو گی۔ جیسےحدیث میں آتاہے کہ مردے کو جب دفناکر واپس جاتے ہیں تو وہ ان کے جوتوں کی آہٹ سنتا ہے، (صحیح بخاری: 1273، مسلم:2201)یا جنگ بدر میں کفارمقتولین کو جو قلیب بدرمیں پھینک دیئے گئے تھے۔ نبی صلی اللہ علیہ وسلم نے خطاب فرمایا، جس پر صحابہ رضی اللہ عنہم نے کہا”آپ صلی اللہ علیہ وسلم بے روح جسموں سے گفتگو فرما رہے ہیں۔آپ نے فرمایا کہ یہ تم سے زیادہ میری بات سن رہے ہیں۔ یعنی معجزانہ طور پر اللہ تعالیٰ نے آپ کی بات مردہ کافروں کو سنوا دی۔\n(صحیح بخاری رقم3757)\nیہ ﴿دَآبَّةٍ﴾ وہی ہے جو قرب قیامت کی علامات میں سے ہے جیسا کہ حدیث میں ہے۔ نبی صلی اللہ علیہ وسلم نے فرمایا:”قیامت اس وقت تک نہیں ہوگی جب تک تم دس نشانیاں نہ دیکھ لو،انمیں ایک جانور کا نکلناہے۔ (صحیح مسلم، حدیث: 2901) نیز دیکھئے (کتاب السنن) دوسری روایت میںہے، ”سب سے پہلی نشانی جو ظاہر ہو گی، وہ ہے سورج کا مشرق کی بجائے،مغرب سےطلوع ہونا اور چاشت کےوقت جانورکانکلنا۔ ان دونوں میں سے جو پہلےظاہرہو گی، دوسری اس کے فوراً بعد ہی ظاہرہوجائےگی۔ (صحیح مسلم، حدیث: 2901)"],[5208,"§قرآن کے واقعات توراۃ و انجیل کے مطابق ہیں\nاس حقیقت سے انکارممکن نہیں کہ قرآن مجید جس کو خاتم الرسل محمد صلی اللہ علیہ وسلم پر عہد نبوت میں مختلف اوقات میں اتارا گیا اس کی حقانیت میں ہرگز شک وشبہ کی گنجائش نہیں، اس کتاب نے اہل کتاب کے درمیان اختلافات کا ذکر کیا ہے جوان میں دین اسلام کے بارے میں تھا، اس لحاظ سے وہ مختلف فرقوں میں تقسیم ہوگئے تھے یہاں تک کہ ایک فریق نے دوسرے فریق کو ملعون قرار دیا جبکہ انصاف کا تقاضا تو یہ تھا کہ وہ اسلام قبول کرتے اور قرآن پاک کے مطالعہ سے راہ حق پر گامزن رہتے کیا یہ حقیقت نہیں کہ قرآن میں ذکر ہونے والے واقعات ان واقعات کے بالکل مطابق ہیں جن کا توراۃ اور انجیل میں تذکرہ ہے جب کہ محمد صلی اللہ علیہ وسلم توامی انسان تھے مزیدبرآں آپ صلی اللہ علیہ وسلم نے یہودی علماء سے ہرگز استفسار نہیں کیا بلکہ آپ صلی اللہ علیہ وسلم کا ان کے ساتھ میل جول بھی ثابت نہیں ہے توپھرتسلیم کرنا پڑے گا کہ آپ صلی اللہ علیہ وسلم نے جو کچھ فرمایا ہے وہ اللہ پاک کی جانب سے وحی ہے مزید برآں قرآن پاک میں مسئلہ توحید قیامت کے دن اٹھائے جانے نبوت اور عادلانہ شرعی احکام جن کی انسانیت کو ضرورت تھی ان کو بیان کیا گیا ہے کسی دوسری کتاب میں اس کی مثال نہیں ملتی ہے، اس لیے تسلیم کرنا ہوگا کہ آپ صلی اللہ علیہ وسلم نے جو کچھ بیان کیا ہے وہ اللہ کی جانب سے ہے بلکہ قرآن مجید کا فصاحت و بلاغت میں اتنااونچا مقام ہے کسی بھی شخص نے اس کا مقابلہ کرنے کی جرأت نہیں کی اس لیے کہ اس قسم کا فصیح و بلیغ کلام پیش کرنا انسان کی قوت سے باہر ہے جبکہ قرآن پاک کا نزول خالق کائنات کی جانب سے ہے۔\nاس حقیقت سے انکار ممکن نہیں ہے کہ قرآن پاک جس کو رسول اللہ صلی اللہ علیہ وسلم پر اتارا گیا اس نے اہل کتاب کے دین اسلام کے بارے میں اختلافات کا ذکر کیا ہے کہ کسی نے مسیح علیہ السلام کو خدا کسی نے خدا کا بیٹا، کسی نے تثلیث کا نعرہ بلند کیا جب کہ قرآن پاک نے انھیں صرف اللہ کا پیغمبر قرار دیا تو اے محمد صلی اللہ علیہ وسلم آپ کا پروردگار ان میں اپنا فیصلہ فرمائیں گے اور اللہ کا فیصلہ غالب ہے اس کے حکم کو روکا نہیں جاسکتا اور اللہ تعالیٰ انسانوں کے افعال سے باخبر ہیں اللہ کی ذات سے کوئی بھی چیز پوشیدہ نہیں ہے آپ اللہ کی ذات پر بھروسہ کرتے ہوئے اپنے سبھی معاملات کو اس کے سپرد کریں اور آپ صلی اللہ علیہ وسلم کے تمام معاملات میں آپ کے مددگار ہیں اس لیے کہ اے محمد صلی اللہ علیہ وسلم آپ تو واضح صحیح راہ پر گامزن ہیں اس لیے انجام کار غلبہ آپ صلی اللہ علیہ وسلم کو حاصل ہوگا۔"],[5209,"§کفار مردوں کی مانند ہیں\nاِنَّكَ لَا تُسْمِعُ الْمَوْتٰى : آپ کفار کو اللہ کا پیغام نہیں سناسکیں گے جبکہ وہ غور و فکر نہیں کرتے ہیں اور عبرت حاصل نہیں کرتے ہیں تو وہ ان مردوں کی مانند ہیں جن میں نہ احساس ہوتا ہے اور نہ ان کی عقل انھیں کچھ فائدہ پہنچاسکتی ہے، اور نہ آپ بہرے لوگوں کو اپنی دعوت سناسکیں گے بالخصوص جب وہ آپ سے روگردانی کریں گے ان کی مثال بہرے لوگوں جیسی ہے جن کے کانوں میں بوجھ ہوتا ہے بالخصوس جب آپ سے روگردانی کریں مزیدبرآں بہرہ انسان جب روگردانی کرتا ہے تو اگر اس حالت میں آپ صلی اللہ علیہ وسلم اس کو آواز دیں گے تو اس وقت وہ بہت ہی کم سن پاتا ہے جبکہ اب پہلے سے زیادہ مسافت بھی حائل ہے البتہ اس عام حکم سے بعض صورتوں کو دلیل کے ساتھ مستثنیٰ قرار دیا جاسکتا ہے جیسا کہ صحیح مسلم میں ہے (کہ نبی صلی اللہ علیہ وسلم نے غزوہ بدر میں بدر کے کنویں میں کفار مقتولین کو آپ صلی اللہ علیہ وسلم نے مخاطب کیا اور دریافت کیا کہ کیا تم نے اس وعدہ کو درست پالیا ہے جو تمہارے پروردگار نے تم سے کیا تھا ؟ تو آپ صلی اللہ علیہ وسلم سے صحابہ کرام نے استفسار کیا آپ تو مردوں کو آواز دے رہے ہیں جن کے جسم تو ہیں ان میں روح نہیں ہے اس کے جواب میں نبی کریم صلی اللہ علیہ وسلم نے انھیں آگاہ کیا اس ذات کی قسم جس کے ہاتھ میں میری جان ہے جو کلمات میں نے کہے ہیں ان کو تم ان سے زیادہ نہیں سن رہے تھے) اس طرح یہ حقیقت مسلمہ ہے کہ مرنے والاشخص الوداع کرنے والوں کے جوتوں کی آواز سنتا ہے۔\nوَ مَاۤ اَنْتَ بِهٰدِي الْعُمْيِ عَنْ ضَلٰلَتِهِمْ: اے محمد صلی اللہ علیہ وسلم آپ میں ہرگز قوت نہیں کہ آپ دلوں کے اندھے لوگوں کو کفر سے دور کرسکیں آپ تو صرف ایمان والوں کو سناسکتے ہیں جنہوں نے خود کو اللہ کی ذات کے تابع کردیا ہے جب کہ یہ توبہرے اندھے ہیں فہم سے عاری ہیں جب وہ پشت پھیر کر روگردانی کرتے ہیں گویا کہ کفار مردوں اور اندھوں اور بہرے لوگوں کی مانند ہیں جو نہ سمجھتے ہیں نہ سن پاتے ہیں نہ دیکھتے ہیں اور نہ وہ دلائل کی جانب دھیان کرتے ہیں۔"],[5210,"§قیامت سے قبل کے واقعات کا بیان\nان واقعات کا ذکرہورہا ہے جو قیامت کے وقوع سے پہلے رونماہوں گے کہ جب قیامت وقوع پذیر ہوجائے گی اور کفار کو عذاب میں مبتلا کرنے کا وقت قریب آن پہنچے گا، توہم کفار کے لیے بہت بڑی علامت کو نمایاں کریں گے، دابۃ الارض، کا خروج ہوگا جو لوگوں کے ساتھ گفتگو کرے گا، وہ ان لوگوں پر لعنت بھیجے گا جو قیامت کا انکار کرتے ہیں اس کی گفتگو یہ ہوگی خبردار ظالموں پر اللہ کی لعنت ہے جو اللہ کی آیات کو تسلیم نہیں کرتے ہیں ذہن نشین کریں کتب حدیث میں قیامت کی علامات میں دابۃ الارض کے خروج کا بھی تذکرہ ہے جیسا کہ سورج کے مغرب کی جانب سے طلوع ہونے کا ذکر ہے اور ان میں جو علامت پہلے ظہور پذیر ہوگی تو دوسری اس کے بعد ہوگی۔\nاس کے ظہو رپذیر ہونے کا وقت آخری زمانہ ہے جب لوگوں میں فسادرونما ہوگا اور اللہ کے احکام پر عمل پیرا نہ ہوگا اور دین اسلام کے احکام کو تبدیل کیا جارہا ہوگا، تودابۃ الارض لوگوں سے گفتگو کرے گا ان سے مخاطب ہو کر یہ جملہ داہرئے گا کہ عام طور پر لوگ ان آیات کا انکار کرتے ہیں اس وقت کیفیت یہ ہوگی بھلائی کا وجود نہیں ہوگا امربالمعروف نہی عن المنکر پر عمل نہیں ہوگا، اللہ کی جانب جھکاؤ کرنے والے نہ ہوں گے مزید توبہ کرنے والے بھی نہ ہوں گے۔\n﴿وَيَوْمَ نَحْشُرُ مِنْ كُلِّ اُمَّةٍ فَوْجًا مِّمَّنْ يُّكَذِّبُ بِاٰيٰتِنَا فَهُمْ يُوْزَعُوْنَ۰۰۸۳ حَتّٰۤى اِذَا جَآءُوْ قَالَ اَكَذَّبْتُمْ بِاٰيٰتِيْ وَلَمْ تُحِيْطُوْا بِهَا عِلْمًا اَمَّا ذَا كُنْتُمْ تَعْمَلُوْنَ۰۰۸۴ وَوَقَعَ الْقَوْلُ عَلَيْهِمْ بِمَا ظَلَمُوْا فَهُمْ لَا يَنْطِقُوْنَ۰۰۸۵ اَلَمْ يَرَوْا اَنَّا جَعَلْنَا الَّيْلَ لِيَسْكُنُوْا فِيْهِ وَالنَّهَارَ مُبْصِرًاؕ اِنَّ فِيْ ذٰلِكَ لَاٰيٰتٍ لِّقَوْمٍ يُّؤْمِنُوْنَ۰۰۸۶﴾\nاور جس دن ہم ہر امت میں سے ایک گروہ اکٹھا کریں گے، جو ہماری آیات کو جھٹلاتے تھے، پھر ان کی درجہ بندی کی جائے گی⟦83⟧ حتیٰ کہ جب وہ سب (میدان محشر میں) آ پہنچیں گے تو اللہ فرمائے گا: کیا تم نے میری آیات کو جھٹلایا تھا، جبکہ تم نے علم سے ان کا احاطہ نہ کیا تھا، یا تم کیا کرتے رہے تھے؟⟦84⟧ اور ان کے ظلم کی وجہ سے ان پر (وعدۂ عذاب کی) بات پوری ہو جائے گی، تو وہ (کچھ بھی) نہیں بول سکیں گے⟦85⟧ کیا انھوں نے نہیں دیکھا کہ ہم نے رات بنائی، تاکہ وہ اس میں آرام و سکون کریں اور دن کو روشن (بنایا)۔ بلاشبہ اس میں ان لوگوں کے لیے نشانیاں ہیں جو ایمان لاتے ہیں⟦86⟧"],[5211,"§قیامت کے دن ظالموں کا جمع کیا جانا\nاللہ تعالیٰ نے بیان فرمایا ہے کہ قیامت کے دن ظالموں کو اور اللہ تعالیٰ کی آیات اور اس کے رسول کی تکذیب کرنے والوں کو اس کے سامنے جمع کیا جائے گا تاکہ وہ سرزنش، ڈانٹ ڈپٹ اور ذلیل و رسوا کرتے ہوئے ان سے یہ پوچھے کہ انہوں نے دنیا میں کیا اعمال کیے تھے۔ ارشاد باری تعالیٰ ہے: ﴿وَیَوْمَ نَحْشُرُ مِنْ کُلِّ اُمَّۃٍ فَوْجًا﴾ ’’اور جس روز ہم ہر امت میں سے ایک گروہ جمع کریں گے۔‘‘ یعنی ہر قوم اور ہر قرن میں سے ایک جماعت کو جمع کریں گے ﴿مِّمَّنْ یُّکَذِّبُ بِاٰیٰتِنَا﴾ ’’جو ہماری آیت کو جھٹلاتے تھے۔‘‘ جیسا کہ فرمایا: ﴿اُحْشُرُوا الَّذِيْنَ ظَلَمُوْا وَاَزْوَاجَهُمْ وَمَا كَانُوْا يَعْبُدُوْنَۙ۰۰۲۲﴾ (الصّٰٓفٰت: 22) ’’جو لوگ طلم کرتے تھے اُن کو اور ان کے جوڑوں کو اور جنہیں وہ پوجا کرتے تھے (سب کو) جمع کر لو۔‘‘ اور فرمایا: ﴿وَاِذَا النُّفُوْسُ زُوِّجَتْ۪ࣕۙ۰۰۷﴾ (التکویر: 7) ’’اور جب روحیں (بدنوں سے) ملا دی جائیں گی۔‘‘ اور فرمایا: ﴿فَهُمْ يُوْزَعُوْنَ۰۰۸۳﴾ ابن عباس رضی اللہ عنہما کہتے ہیں کہ اس کے معنی یہ ہیں کہ وہ روک دیے جائیں گے، (تفسیر الطبری: 21/20 وتفسیر ابن ابی حاتم : 2927/9) عبدالرحمٰن بن زید بن اسلم رحمہ اللہ کا قول ہے کہ اس کے معنی یہ ہیں کہ انہیں ہانکا جائے گا۔ (تفسیر ابن ابی حاتم: 2927/9) ﴿حَتّٰۤى اِذَا جَآءُوْ﴾ ’’یہاں تک کہ جب وہ (سب) آجائیں گے۔‘‘ اور انہیں سوال و جواب کے لیے اللہ تعالیٰ کے سامنے کھڑا کر دیا جائے گا۔ ﴿قَالَ اَكَذَّبْتُمْ بِاٰيٰتِيْ وَلَمْ تُحِيْطُوْا بِهَا عِلْمًا اَمَّا ذَا كُنْتُمْ تَعْمَلُوْنَ۰۰۸۴﴾ ’’تو (اللہ) فرمائے گا کہ کیا تم نے میری آیتوں کو جھٹلا دیا تھا، حالانکہ تم نے (اپنے) علم سے اُن پر احاطہ تو کیا ہی نہ تھا، بھلا تم کیا کرتے تھے؟‘‘ یعنی اللہ تعالیٰ ان سے ان کے اعتقاد اور اعمال کے بارے میں پوچھے گا لیکن وہ اہل سعادت میں سے نہیں ہوں گے بلکہ ایسے ہوں گے جیسا کہ اللہ تعالیٰ نے ان کے بارے میں فرمایا ہے: ﴿فَلَا صَدَّقَ وَلَا صَلّٰىۙ۰۰۳۱ وَلٰكِنْ كَذَّبَ وَتَوَلّٰىۙ۰۰۳۲﴾ (القیامۃ: 32,31) ’’تو اس (عاقبت نا اندیش) نے نہ تو (اللہ کے کلام کی) تصدیق کی، نہ نماز پڑھی بلکہ جھٹلایا اور منہ پھیر لیا۔‘‘\nمنکرین قیامت کے دعویٰ پر غور و فکر دی جارہی ہے کہ اللہ نے رات بنائی ہے جس میں لوگ سکون حاصل کرنے کے لیے نیند کی گود میں چلے جاتے ہیں، جو موت کی ہی قسم ہے اور دن کے وقت جاگ اٹھتے ہیں اور مصروف عمل ہوجاتے ہیں، یہ جاگنا موت کے بعد زندگی کی ایک قسم ہے، اور جب تک آدمی زندہ رہا ہے، نیند و بیداری اور موت و زندگی کا سلسلہ جاری رہتا ہے، اور یہ سب اللہ کی قدرت سے ہوتا ہے اگر ایک عقلمند آدمی اس میں غور کرے گا تو وہ یقیناً موت کے بعد دوسری زندگی پر ایمان لے آئے گا کیونکہ جو اللہ نیند اور بیداری پر قادر ہے، وہ یقیناً موت کے بعد دوبارہ زندہ کرنے پر قادر ہے۔\nآیت کے آخر میں کہا گیا ہے کہ اس عمل خواب و بیداری میں ایمان والوں کے لیے نشانیاں ہیں، کیونکہ انہی کے دل زندہ ہوتے ہیں اور وہی اس میں غور و فکر کے بعد بعث بعد الموت پر ایمان لے آتے ہیں، اور جن کے دل کفر کی وجہ سے مردہ ہیں، انہیں غور و فکر کی توفیق ہی نہیں ہوتی۔\nوَ يَوْمَ نَحْشُرُ مِنْ كُلِّ اُمَّةٍ فَوْجًا : قیامت کے دن کے بعض مشاہد کا تذکرہ ہورہا ہے کہ اس دن محاسبہ اور عذاب کے لیے ہر امت سے ایک گروہ کو لایا جائے گا، جو ہمارے پیغمبروں اور ہماری آیات کی تکذیب کرتے رہے انھیں اکٹھا کیا جائے گا بعدازاں انھیں ڈانٹ پلائی جائے گی یہاں تک کہ جب وہ محاسبہ کے میدان میں جمع ہوں گے بلکہ بعض کو ڈانٹ پلاتے ہوئے شریک کیا جائے گا تو اللہ انھیں ڈانٹ پلاتے ہوئے ان سے استفسار کریں گے تم دنیا میں کیا کام کرتے رہے کیا تم میری ان آیات کو جھٹلاتے رہے جن کو میرے پیغمبروں پر اتارا گیا تھا ؟ تم نے ان کے بارے میں غور و فکر سے کام نہ لیا، ان کے حقائق کی گہرائی سے واقفیت حاصل نہ کی تم نے ان کے جھٹلانے کے علاوہ اور کیا کام کیا تھا ؟ اس سوال پر وہ حیران ہوں گے کچھ بات نہ کرسکیں گے جب کہ ان کے پاس ہرگز کوئی عذر نہ ہوگا اور نہ کوئی دلیل ہوگی۔\nاَلَمْ يَرَوْا اَنَّا جَعَلْنَا الَّيْلَ لِيَسْكُنُوْا فِيْهِ : یہ لوگ اللہ کی قدرت پر غور کیوں نہیں کررہے ہیں کہ وہ عبرت حاصل کریں اس نے رات کو اندھیرے والی بنایا تاکہ لوگ نیند کرکے آرام حاصل کرسکیں اور تھکاوٹ دور کرسکیں جب کہ دن کو روشن بنایا تاکہ دن کے لمحات میں معیشت کے ذرائع اختیار کرتے ہوئے اپنی بنیادی ضرورتوں کو حاصل کر پائیں یقیناً رات دن کی تبدیلی اندھیرے سے روشنی کی جانب اور روشنی سے اندھیرے کی جانب تبدیلی میں اللہ کی قدرت پر ان لوگوں کے لیے مستحکم دلائل ہیں جو ان کی تصدیق کے ساتھ ساتھ عبرت حاصل کرتے ہیں۔\n﴿وَيَوْمَ يُنْفَخُ فِي الصُّوْرِ فَفَزِعَ مَنْ فِي السَّمٰوٰتِ وَمَنْ فِي الْاَرْضِ اِلَّا مَنْ شَآءَ اللّٰهُؕ وَكُلٌّ اَتَوْهُ دٰخِرِيْنَ۰۰۸۷ وَتَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً وَّهِيَ تَمُرُّ مَرَّ السَّحَابِؕ صُنْعَ اللّٰهِ الَّذِيْۤ اَتْقَنَ كُلَّ شَيْءٍؕ اِنَّهٗ خَبِيْرٌۢ بِمَا تَفْعَلُوْنَ۰۰۸۸ مَنْ جَآءَ بِالْحَسَنَةِ فَلَهٗ خَيْرٌ مِّنْهَاۚ وَهُمْ مِّنْ فَزَعٍ يَّوْمَىِٕذٍ اٰمِنُوْنَ۰۰۸۹ وَمَنْ جَآءَ بِالسَّيِّئَةِ فَكُبَّتْ وُجُوْهُهُمْ فِي النَّارِؕ هَلْ تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُوْنَ۰۰۹۰﴾\nاور جس دن صور میں پھونکا جائے گا تو جو کوئی آسمانوں میں ہے اور جو کوئی زمین میں ہے (سب) گھبرا جائیں گے، سوائے اس کے جسے اللہ چاہے، اور (یہ) سب عاجز ہو کر اللہ کے حضور جائیں گے⟦87⟧ اور آپ پہاڑوں کو دیکھیں گے تو ان کو جامد (اپنی جگہ جمے ہوئے) سمجھیں گے، جبکہ وہ بادلوں کے چلنے کی طرح چل رہے ہوں گے، یہ اللہ کی کاریگری ہے جس نے ہر چیز کو پختہ اور مضبوط بنایا، بے شک وہ با خبر ہے اس سے جو تم کرتے ہو⟦88⟧ جو شخص نیکی لائے گا، تو اس کے لیے اس سے زیادہ بہتر (بدلہ) ہو گا، اور وہ اس دن ہر گھبراہٹ سے بے خوف ہوں گے⟦89⟧ اور جو شخص برائی لائے گا تو ان کے منہ آگ میں اوندھے کر دیے جائیں گے (اور کہا جائے گا:) تم بس اسی کا بدلہ پائو گے جو تم عمل کرتے تھے⟦90⟧"],[5212,"§قیامت کے دن کی ہولناکیاں اور نیکی و برائی کا بدلہ\nاللہ تعالیٰ نے صور میں پھونکے جانے کے دن کی ہولناکیوں کو بیان فرمایا ہے اور جیسا کہ حدیث میں آیا ہے: «قَرْنٌ يُّنْفَخُ فِيهِ» ’’وہ ایک سینگ ہے جس میں پھونکا جائے گا۔‘‘ (جامع الترمذی، حدیث: 2430) اور حدیث صور میں ہے کہ اس میں سیّدنا اسرافیل علیہ السلام اللہ تعالیٰ کے حکم سے پھونکیں گے، پہلے اس میں ایسی پھونک ماری جائے گی جس سے گھبراہٹ طاری ہوجائے گی، بھوک بہت طویل ہو گی اور دنیا کی عمر کے آخری حصے میں ہوگی(المعجم الکبیر للطبرانی: حدیث: 9761 وکتاب العظمۃ: 851,820/3) جب بدترین لوگوں پر قیامت قائم ہوگی۔(صحیح البخاری، حدیث: 7067 وصحیح مسلم، الامارۃ، حدیث: 1924) اس بھوک کی آواز سے آسمانوں اور زمین کے سب لوگ گھبرا اٹھیں گے۔ ﴿اِلَّا مَنْ شَآءَ اللّٰہُط﴾ ’’سوائے اس کے کہ جسے اللہ چاہے۔‘‘ اور وہ شہداء ہوں گے، وہ اپنے رب کے پاس زندہ ہیں اور رزق دیے جاتے ہیں۔\nامام مسلم رحمہ اللہ نے عبد اللہ بن عمرو رضی اللہ عنہما سے روایت کیا ہے کہ ان کے پاس ایک شخص آیا اور اس نے کہا کہ یہ کیا حدیث ہے جو آپ بیان کرتے ہیں کہ قیامت فلاں وقت برپا ہوگی۔ انہوں نے جواب دیتے ہوئے کہا: سبحان اللہ یا یہ کہا: لا الٰہ الا اللہ یا اسی طرح کا کوئی اور کلمہ کہا، پھر کہا کہ میں نے ارادہ کیا ہے کہ آئندہ کسی سے کچھ بھی نہیں کہوں گا۔ میں نے تو یہ بیان کیا تھا کہ تم عنقریب تھوڑے عرصے بعد ایک عظیم کام دیکھو گے اور وہ یہ کہ بیت اللہ کو خراب کر دیا جائے گا اور یہ یہ واقعات رونما ہوں گے، پھر کہا کہ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا ہے: ’’میری امت میں دجال نکلے گا اور وہ چالیس تک رہے گا لیکن مجھے نہیں معلوم کہ آپ نے چالیس دن فرمایا یا چالیس مہینے یا چالیس سال۔ پس اللہ تعالیٰ عیسیٰ ابن مریم علیہ السلام کو بھیج دیں گے، ان کی شکل و صورت ایسی ہوگی گویا سیّدنا عروہ بن مسعود رضی اللہ عنہ ہوں، وہ دجال کو تلاش کر کے ہلاک کردیں گے، پھر لوگ سات سال اس طرح بسر کریں گے کہ کوئی دو آدمی ایسے نہیں ہوں گے جن میں عداوت ہو، پھر اللہ تعالی شام کی طرف سے ٹھنڈی ہوا بھیجے گا جس کی وجہ سے روئے زمین پر کوئی ایک شخص بھی ایسا باقی نہیں بچے گا جس کے دل میں ذرہ بھر خیر یا ایمان ہوں حتیٰ کہ اگر کوئی شخص پہاڑ کے اندر داخل ہوا تو وہ ہوا بھی پہاڑ کے اندر داخل ہو کر اس کی روح قبض کر لے گی، راوی نے کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ بھی بیان فرماتے ہوئے سنا کہ ایسے بدترین لوگ رہ جائیں گے، جو شرارتوں کی طرح پرندوں کی سی تیزی کے ساتھ چلیں گے اور ایک دوسرے سے دشمنی اور ظلم کرنے کے اعتبار سے درندوں کی طرح ہوں گے۔ جو نہ نیکی کو پہچانتے ہوں گے اور نہ برائی کو برا جانتے ہوں گے، شیطان ان کے پاس آئے گا اور کہے گا: کیا تم میری بات مانو گے؟\nوہ جواب دیں گے: کیا حکم ہے؟ تو شیطان انہیں بتوں کی پوجا کا حکم دے گا، اس حالت میں ان کے پاس رزق پہنچ رہا ہوگا اور ان کی معیشت اچھی ہوگی، پھر صور میں پھونکا جائے گا تو اسے جو بھی سنے گا وہ اپنی گردن کو ایک طرف جھکا دے گا اور اسے اوپر اٹھا دے گا۔ اور سب سے پہلے جو اس کی آواز سنے گا، وہ ایک ایسا شخص ہوگا جو اپنے اونٹ کے حوض کو درست کر رہا ہوگا، وہ آواز سن کر بے ہوش ہو جائے گا۔ دوسرے لوگ بھی بے ہوش ہو جائیں گے، پھر اللہ تعالیٰ بارش نازل فرمائے گا جو طل یا ظل کی طرح ہوگی۔ اس حدیث کی سند کے ایک راوی نعمان بن سالم کو شک ہے کہ آپ نے یہاں کیا لفظ ارشاد فرمایا تھا۔(المستدرک للحاکم، حدیث: 8772) اس سے لوگوں کے جسم اُگنے لگے گیں، پھر صور میں ایک بار اور پھونکا جائے گا اور لوگ کھڑے ہو کر دیکھنے لگیں گے، پھر کہا جائے گا: اے لوگو! اپنے رب کے پاس چلو: ’’اور ان کو ٹھہرائے رکھو کہ ان سے (کچھ) پوچھنا ہے۔‘‘ پھر کہا جائے گا کہ جہنم کا حصہ نکالو، پوچھا جائے گا: کتنا؟ تو جواب دیا جائے گا کہ ہر ہزار میں سے نو سو ننانوے، آپ صلی اللہ علیہ وسلم نے فرمایا: یہی وہ دن ہے: ’’جو بچوں کو بوڑھا کر دے گا۔‘‘ اور یہی وہ دن ہے: ’’جس دن پنڈلی سے (کپڑا) کھولا جائے گا۔‘‘(صحیح مسلم، حدیث: 2940)\nاس حدیث میں جو یہ الفاظ آئے ہیں: «ثُمَّ يُنْفَخُ فِي الصُّورِ فَلَا يَسْمَعُهُ أَحدٌ اِلَّا اَصْغٰى لِيتًا وَّرَفَعَ لِيتًا» ’’پھر صور میں پھونکا جائے گا تو اسے جو بھی سنے گا، وہ اپنی گردن کو ایک طرف جھکا دے گا اور اسے اوپر اٹھا دے گا۔‘‘ ان میں لفظ لیت کے معنی سطح گردن کے ہیں، یعنی وہ گردن کو جھکا دے گا تاکہ آسمان سے آنے والی اس آواز کو اچھی طرح سے سن لے، یہ نفخہ فزع ہوگا، پھر اس کے بعد نفخہ موت ہوگا، پھر اس کے بعد اللہ رب العالمین کے سامنے کھڑے ہونے کا نفخہ ہوگا، یعنی قبروں سے تمام مخلوق کے اُٹھنے کا نفخہ، اسی لیے فرمایا: ﴿وَكُلٌّ اَتَوْهُ دٰخِرِيْنَ۰۰۸۷﴾ ’’اور سب اس کے پاس عاجز ہو کر چلے آئیں گے۔‘‘ اسے فعل پر مد اور بغیر مد کے دونوں طرح پڑھا گیا ہے اور دونوں کے معنی ایک ہی ہیں۔ (تفسیر الطبری: 26/20) ﴿دٰخِرِيْنَ۰۰۸۷﴾ کے معنی عاجز اور مطیع کے ہیں، کوئی بھی اللہ تعالیٰ کے حکم کی نافرمانی نہ کر سکے گا جیسا کہ فرمایا: ﴿يَوْمَ يَدْعُوْكُمْ فَتَسْتَجِيْبُوْنَ بِحَمْدِهٖ﴾ (بنیٓ اسرائیل: 52) ’’جس دن وہ تمہیں پکارے گا تو تم اس کی تعریف کے ساتھ جواب دو گے۔‘‘ اور فرمایا: ﴿ثُمَّ اِذَا دَعَاكُمْ دَعْوَةًࣗۖ مِّنَ الْاَرْضِ اِذَاۤ اَنْتُمْ تَخْرُجُوْنَ۰۰۲۵﴾ (الروم: 25) ’’پھر جب وہ تمہیں زمین میں سے (نکلنے کے لیے) ایک ہی بار آواز دے گا تو تم جھٹ نکل آئو گے۔‘‘\nاور حدیث صور میں ہے کہ تیسرے نفخے کے وقت اللہ تعالیٰ حکم دے گا اور روحوں کو صور کے سوراخ میں رکھ دیا جائے گا، پھر اسرافیل اس میں پھونک ماریں گے جبکہ جسم اپنی قبروں اور اپنی جگہوں میں اُگ پڑیں گے، پھر جب صور میں پھونکا جائے گا تو روحیں اڑنے لگیں گی، مومنوں کی روحیں منور ہوں گی اور کافروں کی روحیں کالی سیاہ تو اس وقت اللہ عزوجل ارشاد فرمائے گا: مجھے اپنی عزت و جلال کی قسم! ہر روح اپنے جسم میں چلی جائے تو تمام روحیں اپنے اپنے جسموں میں چلی جائیں گی اور روحیں جسموں میں اس طرح سرایت کریں گی جس طرح ڈسے ہوئے کے جسم میں زہر سرایت کر جاتا ہے، پھر مٹی جھاڑتے ہوئے وہ اپنی قبروں سے اُٹھیں گے۔ (کتاب العظمۃ: 842,841/3) ارشاد باری تعالیٰ ہے: ﴿يَوْمَ يَخْرُجُوْنَ مِنَ الْاَجْدَاثِ سِرَاعًا كَاَنَّهُمْ اِلٰى نُصُبٍ يُّوْفِضُوْنَۙ۰۰۴۳﴾ (المعارج: 43) ’’اس دن وہ قبروں سے دوڑتے ہوئے نکلیں گے گویا کہ وہ کسی گاڑے ہوئے نشان کی طرف دوڑے جا رہے ہیں۔‘‘\nاور اس کا فرمان ہے: ﴿وَمَنْ جَآءَ بِالسَّيِّئَةِ فَكُبَّتْ وُجُوْهُهُمْ فِي النَّارِؕ﴾ ’’اور جو برائی لے کر آئے گا تو ایسے لوگ اوندھے منہ دوزخ میں ڈال دیے جائیں گے۔‘‘ یعنی جو شخص اللہ تعالیٰ کے پاس برائیوں کے ساتھ آئے اور اس کے پاس کوئی نیکی نہ ہو یا اس کی برائیاں اس کی نیکیوں سے زیادہ ہوں تو اسے اوندھے منہ دوزخ میں ڈال دیا جائے گا، اسی لیے فرمایا: ﴿هَلْ تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُوْنَ۰۰۹۰﴾ ’’تم کو تو انہی اعمال کا بدلہ ملے گا جو تم کرتے رہے ہو۔‘‘\nنبی کریم صلی اللہ علیہ وسلم کو مخاطب کر کے کہا جارہا ہے کہ نفخ صور کے بعد پہاڑ بظاہر اپنی جگہ پر جامد ہوں گے، لیکن وہ بادلوں کی سی تیزی کے ساتھ چل رہے ہوں گے، اکثر مفسرین نے اس آیت کی یہی تفسیر بیان کی ہے کہ ایسا قیامت کے دن اس وقت ہوگا جب اللہ تعالیٰ پوری کائنات کو ہلاک کردے گا۔ اللہ تعالیٰ نے سورة الطور آیت (10) میں فرمایا ہے :﴿وَّتَسِيْرُ الْجِبَالُ سَيْرًاؕ۰۰۱۰﴾ اور سورة الکہف آیت (47) میں فرمایا ہے :﴿وَيَوْمَ نُسَيِّرُ الْجِبَالَ﴾دونوں آیتوں سے ثابت ہوتا ہے کہ قیامت کے دن اللہ تعالیٰ پہاڑوں کو بہت تیزی کے ساتھ چلائے گا اور یہ سب کچھ اللہ تعالیٰ کی عظیم قدرت کی وجہ سے ہوگا جس نے ہر چیز کو ایک مخصوص حکمت کے مطابق پیدا کیا ہے، اور جو بندوں کے تمام اچھے اور برے اعمال سے باخبر ہے، اور قیامت کے دن انھیں ان کا بدلہ دے گا۔ اسی مفہوم کی مزید تاکید کے طور پر آیات (89،90) میں اللہ تعالیٰ نے فرمایا کہ دنیا میں جو ایمان و عمل کی زندگی گزارے گا اس دن اسے کوئی خوف و حراس لاحق نہیں ہوگا، اور اللہ تعالیٰ اسے جنت عطا کرے گا، اور جو لوگ شرک و معاصی کے مرتکب ہوں گے انھیں ان کے منہ کے بل جہنم میں دھکیل دیا جائے گا۔ پھر بندوں کو خطاب کر کے فرمایا کہ اس دن جو کچھ ہوگا تمہارے اعمال کا نتیجہ ہوگا، کسی پر ایک رائی کے دانے کے برابر بھی ظلم نہیں ہوگا۔"],[5213,"§دَخَرَکا لغوی مفہوم\nدَخَرَکے معنی میں عاجزی، ذلت اور حقارت تین باتیں پائی جاتی ہیں اور داخر بمعنی عقل و ہوش کی کم مائیگی کی بنا پر نکو بن کر ذلت کی اطاعت قبول کرلینے والا ہے۔ یعنی ساری کی ساری مخلوق عاجز اور حقیر بن کر اللہ کے حضور پیش ہوجائے گی۔ اپنے آپ کو قصور وار سمجھتے ہوئے یوں پیش ہوں گے۔ جیسے کوئی قصور وار غلام اپنے آقا کے سامنے پیش ہوتا ہے۔"],[5214,"§قیامت کو پہاڑوں کا انجام\nیعنی جب قیامت قائم ہوگی تو اس کا آغاز اس طرح ہوگا کہ نظام کائنات میں زبردست خلل واقع ہوجائے گا۔ زمین مسلسل ہچکولے کھانے لگے لگی۔ اور پہاڑوں جیسی ٹھوس، سخت اور جامد چیز اپنی جڑیں چھوڑ کر ریزہ ریزہ ہوجائے گی اور ان ریزوں کی دھول فضا میں اس طرح اُڑتی پھرے گی جیسے دھنکی ہوئی روئی (القارعہ:5) اور اس مقام پر یہ تشبیہ دی گئی ہے کہ جیسے بادل فضا میں اڑتے پھرتے ہیں ویسے ہی پہاڑ بھی اڑتے پھریں گے۔"],[5215,"§اَتْقَنَکا لغوی مفہوم\nحالانکہ اللہ تعالیٰ نے کائنات کی جس چیز کو بھی بنایا وہ اس کی کاریگری کا بےمثال نمونہ ہے اور اتقن الامر کے معنی کسی چیز کو فنی مہارت کے ساتھ مضبوط بنانا ہے۔ جو مدت بعد تک کام کرنے پر بھی خراب نہ ہوں۔ مثلاً یہ سورج، یہ چاند، یہ ستارے، یہ زمین اور یہ آسمان، یہ سب اللہ نے جس دن سے پیدا کی ہیں اور جس مقصد کے لیے پیدا کی ہیں۔ وہ مقصد نہایت عمدگی سے پورا کر رہی ہیں۔ کبھی نہ ان کی چال میں فرق آتا ہے۔ نہ لمحہ بھر کی تقدیم و تاخیر ہوتی ہے اور نہ وہ خراب ہوتی ہیں اور نہ اپنا کام چھوڑ دیتی ہیں۔ اور یہ چیزیں تاقیام قیامت اسی حال پر برقرار رہیں گی اور ان میں خلل یا بگاڑ صرف اس وقت پیدا ہوگا جب اللہ کو منظور ہوگا اور قیامت قائم ہوگی۔\nیعنی حقیقی اور بڑی گھبراہٹ سے وہ محفوظ ہوں گے۔﴿لَا يَحْزُنُهُمُ الْفَزَعُ الْاَكْبَرُ﴾ (الانبیاء:103)\nوَیَوْمَ یُنْفَخُ فِی الصُّوْرِ: اس دن کا تذکرہ کریں جس دن اسرافیل فرشتہ صور میں پھونکے گا جس کے باعث آسمان و زمین میں کوئی فرد باقی نہیں رہے گا، مگر وہ خوف زدہ ہو کر گھبرائے گا البتہ انبیاء علیہم السلام اور فرشتوں اور شہداء میں سے جن کو اللہ مستثنیٰ قرار دے گا وہ بےہوش نہ ہوں گے پھر موت کا نفخہ، ہوگا اس کے بعد قبروں سے اٹھائے جانے کے لیے نفخہ ہوگا، سبھی لوگ بارگاہ رب العالمین میں حاضر ہوں گے سبھی فوت شدہ لوگ جو اس نفخہ سے زندہ ہوں گے وہ اپنے پروردگار کی بارگاہ میں اطاعت گزار تواضع کے ساتھ حاضر ہوں گے کوئی ایک فرد بھی پیچھے نہ رہے گا۔\nوَ تَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً : اور تو پہلے نفخہ کے وقت پہاڑوں کو دیکھے گا کہ وہ اپنی جگہ میں ثابت ہیں ٹھہرے ہوئے ہیں لیکن نفخہ کے بعد وہ بادلوں کی طرح تیز تیز چلیں گے البتہ ان کے بارے میں خیال کہ وہ چل نہیں رہے ہیں اس کی حقیقت یہ ہے کہ جو اجسام بڑے بڑے ہوتے ہیں جب وہ بادلوں کی طرح تیز تیز چل رہے ہوتے ہیں جب کہ ان کی جانب دیکھنے والاشخص ان کے بارے میں یہ خیال رکھتا ہے کہ وہ ٹھہرے ہوئے ہیں حالانکہ وہ تیز تیز رواں دواں ہوتے ہیں یہ اللہ کی نہایت عمدہ کاریگری کا نشان ہے جس نے ہرچیز کی تخلیق کو محکم بنایا ہے اور اس میں حکمتیں اور مصلحتیں ودیعت کررکھی ہیں بلاشبہ اللہ جانتا ہے جو کچھ لوگ کررہے ہیں خواہ اچھا کام یابراکام کررہے ہیں تو اللہ انھیں پورا پورا بدلہ دیں گے۔\nمَنْ جَآءَ بِالْحَسَنَةِ فَلَهٗ خَيْرٌ مِّنْهَا: جو شخص قیامت کے دن اچھے کام کے ساتھ آئے گا اللہ تعالیٰ اس کے اعمال کا اجر و ثواب دوگناعطا کرے گا بلکہ ایک نیکی کا بدلہ دس گنا عطا کرے گا، اور تھوڑے سے عمل پر ایساثواب عطا کرے گاجوہمیشہ ہمیشہ کے لیے ہوگا، وہ سخت دن کے ڈر سے اطمینان کی حالت میں ہوں گے جیسا کہ ارشاد ربانی ہے:﴿لَا يَحْزُنُهُمُ الْفَزَعُ الْاَكْبَرُ﴾ ان کو بہت بڑی گھبراہٹ غمناک نہ کرے گی اور جو لوگ برائی کے مرتکب ہوئے انھیں دوزخ میں چہروں کے بل گرایا جائے گا، ابن عباس رضی اللہ عنہما نے سیئۃ کی تفسیر شرک سے کی ہے کہ جس نے اللہ کی ذات کے ساتھ اس کی عبادت اس کی اطاعت میں غیر اللہ کو شریک بنایا توا سے دوزخ میں چہرے کے بل گرایا جائے گا، اور دوزخ میں الٹالٹکایا جائے گا، انھیں ڈانٹ پلاتے ہوئے کہا جائے گا تمہیں تو بس تمہارے اعمال کا بدلہ دیاجارہا ہے جو تم دنیا میں عمل کرتے رہے۔\n﴿اِنَّمَاۤ اُمِرْتُ اَنْ اَعْبُدَ رَبَّ هٰذِهِ الْبَلْدَةِ الَّذِيْ حَرَّمَهَا وَلَهٗ كُلُّ شَيْءٍ١ٞؗ وَّاُمِرْتُ اَنْ اَكُوْنَ مِنَ الْمُسْلِمِيْنَۙ۰۰۹۱ وَاَنْ اَتْلُوَا الْقُرْاٰنَۚ فَمَنِ اهْتَدٰى فَاِنَّمَا يَهْتَدِيْ لِنَفْسِهٖۚ وَمَنْ ضَلَّ فَقُلْ اِنَّمَاۤ اَنَا مِنَ الْمُنْذِرِيْنَ۰۰۹۲ وَقُلِ الْحَمْدُ لِلّٰهِ سَيُرِيْكُمْ اٰيٰتِهٖ فَتَعْرِفُوْنَهَاؕ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُوْنَࣖ۰۰۹۳﴾\n(آپ کہہ دیجیے:) بس مجھے تو حکم ہوا ہے کہ میں اس شہر (مکہ) کے رب کی عبادت کروں جس نے اسے حرمت بخشی ہے، اور ہر شے اسی کے لیے ہے، اور مجھے حکم ہوا ہے کہ میں فرمانبرداروں میں سے ہو جائوں⟦91⟧ اور یہ کہ میں قرآن پڑھوں، پھر جس نے ہدایت پائی تو بس وہ اپنی ہی ذات کے لیے ہدایت پاتا ہے، اور جو گمراہ ہوا تو آپ کہہ دیجیے: میں تو صرف ڈرانے والوں میں سے ہوں⟦92⟧ اور کہہ دیجیے: تمام حمد اللہ ہی کے لیے ہے، وہ جلد ہی تمھیں اپنی نشانیاں دکھائے گا، پھر تم انھیں پہچان لو گے، اور جو کچھ تم عمل کرتے رہے ہو آپ کا رب اس سے غافل نہیں⟦93⟧"],[5216,"§اللہ تعالیٰ کی عبادت کا حکم\nاللہ تعالیٰ نے اپنے رسول کو حکم دیتے ہوئے فرمایا ہے کہ آپ صلی اللہ علیہ وسلم کہہ دیں: ﴿اِنَّمَاۤ اُمِرْتُ اَنْ اَعْبُدَ رَبَّ هٰذِهِ الْبَلْدَةِ الَّذِيْ حَرَّمَهَا وَلَهٗ كُلُّ شَيْءٍ١ٞ﴾ ’’مجھ کو یہی ارشاد ہوا ہے کہ میں اس شہر (مکہ) کے رب کی عبادت کروں جس نے اسے حرمت دی اور ہر چیز اسی کی ہے۔‘‘ جیسا کہ فرمایا: ﴿قُلْ يٰۤاَيُّهَا النَّاسُ اِنْ كُنْتُمْ فِيْ شَكٍّ مِّنْ دِيْنِيْ فَلَاۤ اَعْبُدُ الَّذِيْنَ تَعْبُدُوْنَ مِنْ دُوْنِ اللّٰهِ وَلٰكِنْ اَعْبُدُ اللّٰهَ الَّذِيْ يَتَوَفّٰىكُمْۚۖ﴾ (یونس: 104) ’’(اے پیغمبر صلی اللہ علیہ وسلم!) کہہ دیں کہ لوگو اگر تمہیں میرے دین میں (کسی طرح کا) شک ہو تو (یاد رکھو کہ) جن لوگوں کی تم اللہ کے سوا عبادت کرتے ہو میں ان کی عبادت نہیں کرتا بلکہ میں اس اللہ کی عبادت کرتا ہوں جو تمہیں فوت کرتا ہے۔‘‘ اس آیت کریمہ میں ربوبیت کی شہر مکہ کی طرف اضافت بر سبیل تشریف و اعتنا ہے جیسا کہ فرمایا: ﴿فَلْيَعْبُدُوْا رَبَّ هٰذَا الْبَيْتِۙ۰۰۳ الَّذِيْۤ اَطْعَمَهُمْ مِّنْ جُوْعٍ࣢ۙ وَّاٰمَنَهُمْ مِّنْ خَوْفٍࣖ۰۰۴﴾ (قریش: 4,3) ’’لوگوں کو) چاہیے کہ اس گھر کے رب کی عبادت کریں جس نے اُن کو بھوک میں کھانا کھلایا اور خوف سے امن بخشا۔‘‘\n﴿الَّذِیْ حَرَّمَھَا﴾ ’’جس نے اسے حرمت دی۔‘‘ یعنی جو اللہ تعالیٰ کے محترم قرار دینے کی وجہ سے شرعاً اور قدراً محترم بن گیا ہے جیسا کہ صحیح بخاری و مسلم میں سیّدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن فرمایا: ’’اس شہر کو اللہ تعالیٰ نے اسی دن سے محترم قرار دیا ہے جس دن اس نے آسمانوں اور زمین کو پیدا فرمایا تھا پس وہ اللہ تعالیٰ کے محترم قرار دینے کی وجہ سے قیامت کے دن تک محترم ہے، اس کے کانٹے کو نہ کاٹا جائے، اس کے شکار کو نہ بھگایا جائے اور نہ اس کے لقطے کو اٹھایا جائے۔ البتہ جو اس کے بارے میں اعلان کرنا چاہے (وہ اسے اٹھا سکتا ہے) اور نہ اس کی گھاس کو کاٹا جائے۔‘‘ (صحیح البخاری، حدیث: 3189 و صحیح مسلم، حدیث: 1353)\n﴿وَقُلِ الْحَمْدُ لِلّٰهِ سَيُرِيْكُمْ اٰيٰتِهٖ فَتَعْرِفُوْنَهَاؕ﴾ ’’آپ کہہ دیں کہ تمام تعریفیں اللہ کے لیے ہیں، وہ تمہیں عنقریب اپنی نشانیاں دکھائے گا تو تم انہیں پہچان لو گے۔‘‘ یعنی سب تعریف اس اللہ کے لیے ہے جو اس وقت تک کسی کو عذاب نہیں دیتا جب تک ا س پر حجت تمام نہ کر دے اور اسے ڈرا نہ دے، اسی لیے فرمایا: ﴿سَيُرِيْكُمْ اٰيٰتِهٖ فَتَعْرِفُوْنَهَاؕ﴾ ’’وہ تمہیں عنقریب اپنی نشانیاں دکھائے گا تو تم انہیں پہچان لو گے۔‘‘ جیسا کہ فرمایا: ﴿سَنُرِيْهِمْ اٰيٰتِنَا فِي الْاٰفَاقِ وَفِيْۤ اَنْفُسِهِمْ حَتّٰى يَتَبَيَّنَ لَهُمْ اَنَّهُ الْحَقُّؕ﴾ (حٰمٓ السجدۃ: 53) ’’ہم عنقریب انہیں اطراف (عالم) میں بھی اور خود ان کی ذات میں بھی اپنی نشانیاں دکھائیں گے یہاں تک کہ ان پر ظاہر ہو جائے گا کہ یقیناً وہ (قرآن) حق ہے۔‘‘\n﴿وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُوْنَࣖ۰۰۹۳﴾ ’’اور جو کام تم کرتے ہو آپ کا پروردگار ان سے ہرگز بے خبر نہیں۔‘‘ بلکہ وہ ہر چیز سے باخبر ہے۔ ذکر کیا گیا ہے کہ امام احمد رحمہ اللہ ان دو شعروں کو پڑھا کرتے تھے جو ان کے اپنے یا کسی دوسرے شاعر کے ہیں:\nاِذَا مَا خَلَوْتَ الدَّھْرَ یَوْمًا فَلَا تَقُلْ\nخَلَوْتُ وَلٰکِنْ قُلْ عَلَیَّ رَقِیب\n’’جب تم کبھی خلوت میں ہو تو یہ نہ کہو کہ میں خلوت میں ہوں بلکہ یہ کہو کہ مجھ پر ایک نگہبان بھی ہے۔‘‘\nوَلَا تَحْسَبَنَّ اللہَ یَغْفَلُ سَاعَۃً\nوَّلَا اَنَّ مَا یُخْفٰی عَلَیْہِ یَغِیب\n’’اللہ تعالیٰ کے بارے میں یہ گمان نہ کرو کہ وہ ایک لمحے کے لیے بھی غافل ہے، اللہ تعالیٰ سے جس چیز کو مخفی رکھا جائے وہ اس سے کبھی بھی چھپ نہیں سکتی۔‘‘\nاوپر کی آیتوں میں قیامت کی کچھ نشانیاں اور اس کی بعض ہولناکیاں بیان کر کے کفار قریش کو اس پر ایمان لانے کی دعوت دی گئی ہے۔ اور اب نبی کریم صلی اللہ علیہ وسلم سے کہا جارہا ہے کہ وہ ان کافروں کے سامنے اپنا عقیدہ و عمل بیان کردیں اور اپنا موقف واضح کردیں، چنانچہ آپ صلی اللہ علیہ وسلم نے قرآن کی زبان میں کافروں سے کہا کہ مجھے تو یہ حکم دیا گیا ہے کہ میں صرف شہر مکہ کے رب کی عبادت کروں، اس کا کسی کو شریک نہ بناؤں، وہ مکہ جسے اللہ نے حرم اور جائے امن بنادیا ہے، جہاں نہ کسی کو قتل کیا جاتا ہے نہ کسی پر ظلم ہوتا ہے، نہ اس کے جانوروں کا شکار کیا جاتا ہے اور نہ اس کے درخت کاٹے جاتے ہیں۔\nمفسرین لکھتے ہیں کہ شہر مکہ اور اس کے امن و سکون کو ذکر کرنے سے مقصود کفار قریش کو احساس دلانا ہے کہ ان نعمتوں کا تقاضا تو یہ تھا کہ جس اللہ نے تمہیں یہ نعمتیں دی ہیں ان کی بندگی میں کسی کو شریک نہ کرتے اور اس کے قرآن اور اس کے رسول پر ایمان لے آتے۔\nآپ صلی اللہ علیہ وسلم نے اپنی تقریر جاری رکھتے ہوئے فرمایا : وہی اللہ ہر چیز کا خالق ومالک ہے اور مجھے تو یہی حکم دیا گیا ہے کہ اپنی جبین نیاز صرف اسی کے سامنے خم کروں، اور مجھے یہ بھی حکم دیا گیا ہے کہ تمہیں قرآن پڑھ کر سناؤں اور اس پر ایمان لانے کی تمہیں دعوت دوں، کیونکہ دونوں جہاں کی سعادت کا راز اسی میں ہے۔ تو جو شخص میری دعوت توحید کو قبول کرے گا اور شرک سے تائب ہوجائے گا اس کا نفع اسے ہی پہنچے گا اور جو شخص گمراہ ہوجائے گا اس کا وبال اسی کے سر ہوگا۔ میرا کام تو صرف پیغام حق لوگوں تک پوری صراحت کے ساتھ پہنچا دینا ہے۔\nآیت (93) میں اللہ تعالیٰ نے آپ کو حکم دیا کہ آپ نعمت اسلام پر کفار قریش کے سامنے اپنے شکر کا اظہار کریں کہ ہم مسلمان تو اللہ کے تہہ دل سے شکر گزار ہیں کہ اس نے ہمیں اس عظیم نعمت سے نوازا ہے اور آپ ان سے یہ بھی کہہ دیجیے کہ مستقبل میں ہمارا رب تمہیں اپنی نشانیاں دکھائے گا۔ چنانچہ اللہ نے انھیں اپنی پہلی نشانی میدان بدر میں دکھائی اور دوسری فتح مکہ کے دن اور آخری نشانی موت کے وقت دکھائے گا جب فرشتے ان کے چہروں اور ان کی پیٹھوں پر ضربیں لگائیں گے اور کہیں گے کہ اب چکھو جہنم کا عذاب۔ آخر میں اللہ نے فرمایا کہ اے میرے نبی ! آپ کا رب لوگوں کے اعمال سے غافل نہیں ہے اور وہ ہر ایک کو اس کے عمل کا بدلہ ضرور دے گا۔ مفسرین لکھتے ہیں کہ اس میں اللہ کی جانب سے تمام بنی نوع انسان کے لیے بہت بڑی دھمکی ہے۔"],[5217,"§حرمِ مکہ کی وجہ سے قریش کو حاصل ہونے والے فوائد\nمکہ کے مالک ہونے کا اللہ تعالیٰ نے اس لیے ذکر فرمایا کہ اس سورہ کے نزول کے وقت تک دعوت اسلام کا مرکز تبلیغ صرف مکہ ہی تھا۔ اور اللہ تعالیٰ کی عبادت اور اطاعت اس لحاظ سے بھی تمہارے لیے ضروری ہے کہ جس نے اس شہر کو قابل احترام قرار دیا ہے۔ جس کے بے شمار فوائد اے قریش مکہ ! تم ہی اٹھا رہے ہو۔ ساری دنیا بالخصوص اس گھر کے متولی ہونے کے باعث تمہاری عزت اور تمہارا وقار قائم ہے اللہ کے اس عطا کردہ احترام ہی کی وجہ سے عرب کے ڈاکوؤں اور لٹیروں سے تمہاری جانیں اور تمہارے اموال محفوظ رہتے ہیں اور بالخصوص تمہارے تجارتی قافلوں کو کوئی لوٹنے کی جرأت نہیں کرتا۔ پھر جسے تم پروانہ راہداری عطا کردو۔ لوگ اس پر بھی ہاتھ نہیں ڈالتے۔ آخر عرب کے ڈاکوؤں اور لٹیروں کے دلوں میں تمہارا یہ احترام اور اس گھر کی عزت اور ہیبت کس نے ڈالی ہے ؟ یہ کوئی تمہارے معبودوں کا کارنامہ تو نہیں ہے۔ لہٰذا مجھے تو یہی حکم ہے کہ میں اسی پروردگار کی اطاعت کروں اور اس کا فرمانروا بن کر رہوں اور اللہ کا یہ پیغام تم لوگوں تک بھی پہنچا دوں۔\nاس سے مرادمکہ شہر ہےاس کا بطور خاص اس لیے ذکر کیا ہے کہ اسی میںخانہ کعبہ ہے اور رسول اللہ صلی اللہ علیہ وسلم کو بھی یہی سب سے زیادہ محبوب تھا۔ ”حرمت والا“ کا مطلب ہے اس میںخون ریزی کرنا، ظلم کرنا، شکار کرنا،درخت کاٹنا حتیٰ کہ کانٹا توڑنا بھی منع ہے۔ (بخاری، حدیث: 1349، مسلم، حدیث : 1353)\nدوسرے مقام پر فرمایا ﴿سَنُرِيْهِمْ اٰيٰتِنَا فِي الْاٰفَاقِ وَفِيْۤ اَنْفُسِهِمْ حَتّٰى يَتَبَيَّنَ لَهُمْ اَنَّهُ الْحَقُّؕ﴾ (حم:53)”ہم انہیں آفاق وانفس میں اپنی نشانیاں دکھلائیں گے تا کہ ان پر حق واضح ہوجائے۔“ اگر زندگی میں یہ نشانیاں دیکھ کر ایمان نہیں لاتے تو موت کے وقت تو ان نشانیوںکو دیکھ کر وہ ضرور پہچان لیتے ہیں۔ لیکن اس وقت کی معرفت کوئی فائدہ نہیں پہنچاتی، اس لیے کہ اس وقت کا ایمان مقبول نہیں۔\nآپ انھیں آگاہ کریں کہ مجھے تو بس اس بات کا حکم دیا گیا ہے کہ میں مکہ مکرمہ کے پروردگار کی عبادت کروں جس نے اپنی مخلوق پر حرام قرار دیا ہے کہ وہ اس میں کسی کا حرام خون گرائیں، یا اس میں کسی رہائش پذیر پر ظلم کریں اس لیے کہ یہ پہلا اللہ کا گھر ہے اس جملہ میں کفار کو تنبیہ کرنا مقصود ہے جنہوں نے مکہ مکرمہ کے پروردگار کی عبادت کو چھوڑ رکھا ہے اور اللہ کی عبادت کی بجائے بتوں کی عبادت کرتے ہیں جب کہ انھیں بیت اللہ کے پروردگار کی عبادت کرنی چاہیے تھی اس لیے کہ پیدا کرنے، ملک اور تصرف کے لحاظ سے اس کا کوئی شریک نہیں ہے اور میرے پروردگار نے مجھے حکم دیا ہے کہ میں خود کو اس کے لیے مطیع کروں میں مخلص موحدین سے شمار کیا جاؤں اور مجھے حکم دیا گیا ہے کہ میں قرآن پاک کی تلاوت رات دن کے اوقات میں کروں تاکہ قرآن میں جو خزانے پوشیدہ ہیں وہ مجھ پر منکشف ہوں چنانچہ ایک حدیث میں اس حقیقت کو نمایاں انداز میں ذکر کیا گیا ہے کہ نبی کریم صلی اللہ علیہ وسلم ایک رات نوافل کی ادائیگی میں رات بھر اس آیت کی تلاوت کرتے رہے﴿اِنْ تُعَذِّبْهُمْ فَاِنَّهُمْ عِبَادُكَۚ وَاِنْ تَغْفِرْ لَهُمْ فَاِنَّكَ اَنْتَ الْعَزِيْزُ الْحَكِيْمُ۰۰۱۱۸﴾ (المائدہ:118) ”اگر تو انھیں عذاب میں گرفتار کرے تو ہرگز تجھ پر کوئی اعتراض نہیں اس لیے کہ یہ سب تیرے بندے ہیں اور اگر تو انھیں معاف کردیتا ہے تو بلاشبہ تو اس وصف کے ساتھ موصوف ہے کہ تو گناہوں کو معاف کرنے والامہربان ہے۔“ پس جس شخص نے میری تابعداری کی اور میری ہدایت کے مطابق رواں داوں رہاتو وہ سیدھے راہ پر چل رہا ہے اور جو شخص صراط مستقیم سے منحرف ہوا تو آپ اسے آگاہ کریں کہ میں تو صرف ڈرانے والاہوں اور میں نے اپنی ذمہ داری کو پورا کردیا ہے اور تمہارے گمراہ ہونے کا مجھ پر کچھ وبال نہیں ہے میں نے تم تک ان چیزوں کو پہنچادیا ہے جن کے پہنچانے کی مجھ پر ذمہ داری تھی اور آپ کہیں سب تعریفیں اللہ کے لیے جس نے مجھ پر انعامات کا فیضان کیا جب کہ عظیم نعمت نبوت کا عطا کیا جانا ہے تو تمہارا پروردگار تمہیں اپنے عذاب کی آیات کی حقیقت سے واضح کرے گا، تو تم انھیں پہچان لوگے اور آپ کا پروردگار ان کے اعمال سے بے خبر نہیں ہے جنہیں وہ سرانجام دے رہے ہیں ان پر نازل ہونے والے عذاب کو موخر کررکھا ہے اس کے اترنے کا وقت مقرر ہے نہ اس وقت سے موخر ہوگا نہ اس سے پہلے آئے گا آپ ان کے جھٹلانے سے تنگ دل نہ ہوں بلاشبہ میں تجھے غلبہ دوں گا اور آپ کے دشمن کو ذلیل ورسوا کروں گا۔\nامام احمد رحمہ اللہ نے معدیکرب سے روایت کیا ہے کہ ہم عبداللہ بن مسعود رضی اللہ عنہ کی خدمت میں حاضر ہوئے اور عرض کی کہ آپ ہمیں تقریباً دو صد آیات پر مبنی ﴿طٰسٓمّٓ۰۰۱﴾ سنائیں، انہوں نے فرمایا: یہ مجھے یاد نہیں ہے، لہٰذا تم اس شخصیت کی طرف رجوع کرو جنہوں نے اسے رسول اللہ صلی اللہ علیہ وسلم سے سیکھ کر یاد کیا ہے، یعنی خباب بن اَرَت رضی اللہ عنہ سے اسے سنو، ہم خباب بن اَرَت رضی اللہ عنہ کی خدمت میں حاضر ہوئے تو انہوں نے ہمیں یہ سورۂ مبارکہ سنائی۔(مسند احمد)\nنام : آیت (25) میں مرد مومن شعیب کے پاس موسیٰ علیہ السلام کی آمد کا ذکر ان الفاظ میں آیا ہے ﴿فَلَمَّا جَآءَهٗ وَقَصَّ عَلَيْهِ الْقَصَصَۙ قَالَ لَا تَخَفْ١۫ٙࣞ نَجَوْتَ مِنَ الْقَوْمِ الظّٰلِمِيْنَ۰۰۲۵﴾ اسی آیت سے یہ نام ماخوذ ہے اور چونکہ دعوت الی اللہ کی تاریخ میں موسیٰ علیہ السلام، فرعون اور بنی اسرائیل کے قصوں کی بڑی اہمیت ہے اسی اہمیت کے پیشِ نظر اس سورت کا نام، القصص، رکھ دیا گیا یعنی وہ سورت جس میں بہت ہی اہم تاریخی اور دعوتی قصے وارد ہوئے ہیں۔"],[5218,"§زمانہ نزول\nابن مردویہ اور بیہقی رحمہ اللہ نے کتاب الدلائل میں ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ سورة القصص مکہ میں نازل ہوئی تھی طبرانی رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کی ہے کہ آیات(52،53)ان اصحاب نجاشی کے بارے میں نازل ہوئی تھیں جو معرکہ اُحد میں شریک ہوئے تھے انتہی۔ اسی طرح آیت (85) کے بارے میں آتا ہے کہ وہ مقام جحفہ میں سفر ہجرت میں نازل ہوئی تھی۔\nکفار مکہ کے ذہنوں میں نبی کریم صلی اللہ علیہ وسلم کی نبوت سے متعلق جو شبہات پیدا ہوئے تھے مختلف اسالیب میں قرآن کریم نے انہی کے ازالہ کی کوشش کی ہے اور انھیں باور کرانا چاہا کہ محمد اللہ کے نبی برحق ہیں اور دنیا ودین کی ہر بھلائی ان کی اتباع میں ہی مضمر ہے۔\n﴿طٰسٓمّٓ۰۰۱ تِلْكَ اٰيٰتُ الْكِتٰبِ الْمُبِيْنِ۰۰۲ نَتْلُوْا عَلَيْكَ مِنْ نَّبَاِ مُوْسٰى وَفِرْعَوْنَ بِالْحَقِّ لِقَوْمٍ يُّؤْمِنُوْنَ۰۰۳ اِنَّ فِرْعَوْنَ عَلَا فِي الْاَرْضِ وَجَعَلَ اَهْلَهَا شِيَعًا يَّسْتَضْعِفُ طَآىِٕفَةً مِّنْهُمْ يُذَبِّحُ اَبْنَآءَهُمْ وَيَسْتَحْيٖ نِسَآءَهُمْؕ اِنَّهٗ كَانَ مِنَ الْمُفْسِدِيْنَ۰۰۴ وَنُرِيْدُ اَنْ نَّمُنَّ عَلَى الَّذِيْنَ اسْتُضْعِفُوْا فِي الْاَرْضِ وَنَجْعَلَهُمْ اَىِٕمَّةً وَّنَجْعَلَهُمُ الْوٰرِثِيْنَۙ۰۰۵ وَنُمَكِّنَ لَهُمْ فِي الْاَرْضِ وَنُرِيَ فِرْعَوْنَ وَهَامٰنَ وَجُنُوْدَهُمَا مِنْهُمْ مَّا كَانُوْا يَحْذَرُوْنَ۰۰۶﴾\nاللہ کے نام سے (شروع) جو نہایت مہربان، بہت رحم کرنے والا ہے۔\nطٰسٓمّٓ⟦1⟧ یہ واضح کتاب کی آیات ہیں⟦2⟧ ہم آپ کو موسیٰ اور فرعون کا کچھ حال ٹھیک ٹھیک سناتے ہیں، ان لوگوں کے لیے جو ایمان لاتے ہیں⟦3⟧ بے شک فرعون نے زمین (مصر) میں سر کشی کی، اور اس نے اہل مصر کے کئی گروہ بنا دیے، ان میں سے ایک گروہ (بنی اسرئیل) کو اس نے ضعیف جان کر دبا رکھا تھا، وہ ان کے بیٹے ذبح کرتا اور ان کی بیٹیاں زندہ رکھتا، بلاشبہ وہ فسادیوں میں سے تھا⟦4⟧ اور ہم چاہتے تھے کہ ان لوگوں پر احسان کریں جنھیں زمین میں ضعیف جان (کر دبا) لیا گیا تھا، اور انھیں پیشوا بنائیں، اور انھیں (ملک مصر کے) وارث بنائیں⟦5⟧ اور (یہ کہ) ہم انھیں زمین (شام و فلسطین) میں اقتدار بخشیں، اور ہم فرعون اور ہامان اور ان دونوں کے لشکروں کو ان (کمزور لوگوں کے ہاتھوں) سے وہ چیز دکھائیں جس سے\nوہ ڈرتے تھے⟦6⟧"],[5219,"§سیّدنا موسیٰ علیہ السلام اور فرعون کے حالات\n﴿تِلْكَ اٰيٰتُ الْكِتٰبِ الْمُبِيْنِ۰۰۲﴾ ’’یہ کتاب روشن کی آیتیں ہیں۔‘‘ یعنی ایسی کتاب کی جو واضح روشن ہے، امور و معاملات کے حقائق اور علم ما کان وما یکون کو کھلم کھلا بیان کرنے والی ہے۔ اور اس کا فرمان ہے: ﴿نَتْلُوْا عَلَيْكَ مِنْ نَّبَاِ مُوْسٰى وَفِرْعَوْنَ بِالْحَقِّ﴾ ’’(اے محمد صلی اللہ علیہ وسلم!) ہم آپ پر موسیٰ اور فرعون کے صحیح صحیح حالات تلاوت کرتے ہیں۔‘‘ جیسا کہ فرمایا: ﴿نَحْنُ نَقُصُّ عَلَيْكَ اَحْسَنَ الْقَصَصِ﴾ (یوسف: 3) ’’(اے پیغمبر صلی اللہ علیہ وسلم!) ہم آپ سے ایک نہایت اچھا قصہ بیان کرتے ہیں۔‘‘ اور تمام واقعے کو اس طرح بیان کریں گے کہ گویا آپ صلی اللہ علیہ وسلم وہاں موجود تھے اور یہ واقعہ آپ صلی اللہ علیہ وسلم کا گویا چشم دید ہے، پھر فرمایا: ﴿اِنَّ فِرْعَوْنَ عَلَا فِي الْاَرْضِ﴾ ’’بے شک فرعون نے زمین میں سرکشی کی۔‘‘ یعنی اس نے تکبر، غرور اور سرکشی کو اختیار کر رکھا تھا۔ ﴿وَجَعَلَ اَهْلَهَا شِيَعًا﴾ ’’اور اس نے وہاں کے باشندوں کو گروہ گروہ بنا رکھا تھا۔‘‘ یعنی وہ لوگوں کو مختلف قسموں میں تقسیم کرکے ہر ایک قسم سے اپنی مرضی و مشیت کے مطابق کام لیتا تھا۔\nاور فرعون نے اس سے بچنے کے لیے یہ تدبیر اختیار کی کہ اس نے حکم دے دیا کہ بنی اسرائیل کے پیدا ہونے والے تمام لڑکوں کو قتل کر دیا جائے مگر تقدیر کے مقابلے میں کوئی تدبیر کام نہیں آتی اور جب اللہ تعالیٰ کا مقرر کیا ہوا وقت آ جاتا ہے تو تاخیر نہیں ہوتی اور ہر چیز کے وقت کے بارے میں لکھا ہوا ہے، اسی لیے فرمایا: ﴿وَنُرِيْدُ اَنْ نَّمُنَّ عَلَى الَّذِيْنَ اسْتُضْعِفُوْا فِي الْاَرْضِ وَنَجْعَلَهُمْ اَىِٕمَّةً وَّنَجْعَلَهُمُ الْوٰرِثِيْنَۙ۰۰۵ وَنُمَكِّنَ لَهُمْ فِي الْاَرْضِ وَنُرِيَ فِرْعَوْنَ وَهَامٰنَ وَجُنُوْدَهُمَا مِنْهُمْ مَّا كَانُوْا يَحْذَرُوْنَ۰۰۶﴾ ’’اور ہم چاہتے تھے کہ جو لوگ ملک میں کمزور کر دیے گئے ہیں ہم اُن پر احسان کریں اور انہیں ہم پیشوا بنائیں اور ہم انہیں (ملک کا) وارث بنا دیں اور انہیں زمین میں قدرت دیں اور فرعون اور ہامان اور ان دونوں کے لشکروں کو ہم وہ چیز دکھا دیں جس سے وہ ڈرتے تھے۔‘‘ اللہ تعالیٰ نے ان کے ساتھ اسی طرح کیا جیسا کہ فرمایا ہے: ﴿وَاَوْرَثْنَا الْقَوْمَ الَّذِيْنَ كَانُوْا يُسْتَضْعَفُوْنَ۠ مَشَارِقَ الْاَرْضِ وَمَغَارِبَهَا الَّتِيْ بٰرَكْنَا فِيْهَاؕ وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنٰى عَلٰى بَنِيْۤ اِسْرَآءِيْلَ࣢ۙ بِمَا صَبَرُوْاؕ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهٗ وَمَا كَانُوْا يَعْرِشُوْنَ۰۰۱۳۷﴾ (الاعراف: 137) ’’اور ہم نے ان لوگوں کو جو لوگ کمزور سمجھےجاتے تھے، اس زمین (شام) کے مشرق و مغرب کا جس میں ہم نے برکت دی تھی وارث بنا دیا اور بنی اسرائیل کے بارے میں ان کے صبر کی وجہ سے آپ کے پروردگار کا وعدہ نیک پورا ہوا اور فرعون اور قوم فرعون جو (محل) بناتے اور (انگور کے باغ) جو چھتریوں پر چڑھاتے تھے سب کو ہم نے تباہ کر دیا۔‘‘ اور فرمایا: ﴿كَذٰلِكَؕ وَاَوْرَثْنٰهَا بَنِيْۤ اِسْرَآءِيْلَؕ۰۰۵۹﴾ (الشعرآء: 59) ’’اسی طرح ہوا اور ہم نے ان (چیزوں) کا وارث بنی اسرائیل کو بنا دیا۔‘‘\nفرعون نے اپنی طاقت و قوت کے ساتھ موسیٰ علیہ السلام سے نجات پانے کا ارادہ کیا تھا مگر اُس عظیم بادشاہ کی قدرت کے مقابلے میں وہ اپنے ارادے میں کامیاب نہ ہو سکا جس کے قدری حکم کی مخالفت نہیں کی جا سکتی اور نہ کوئی اس پر غالب آ سکتا ہے بلکہ اسی کا حکم اور اس کی مقرر کردہ تقدیر غالب آ کر رہی کہ فرعون موسیٰ علیہ السلام ہی کے ہاتھوں سے ہلاک ہوا۔\nآخر کار اللہ کی رحمت جوش میں آئی اسے اپنے ان ناتواں بندوں پر رحم آیا جو اس کے خلیل ابراہیم کی نسل سے تھے انھیں فرعون کی غلامی سے آزاد کرکے ایمان جیسی عظیم ترین نعمت سے نوازنا چاہا اور فرعون اور اس کے لشکر کو ہلاک کرکے انھیں سرزمین مصر کا وارث وحاکم بنانا چاہا جیسا کہ اللہ تعالیٰ سورة الاعراف میں آیت 137میں فرمایا ﴿وَاَوْرَثْنَا الْقَوْمَ الَّذِيْنَ كَانُوْا يُسْتَضْعَفُوْنَ۠ مَشَارِقَ الْاَرْضِ وَمَغَارِبَهَا الَّتِيْ بٰرَكْنَا فِيْهَاؕ وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنٰى عَلٰى بَنِيْۤ اِسْرَآءِيْلَ࣢ۙ بِمَا صَبَرُوْاؕ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهٗ وَمَا كَانُوْا يَعْرِشُوْنَ۰۰۱۳۷﴾ ”ہم نے ان لوگوں کو جو بالکل کمزور شمار کیے جاتے تھے اس سرزمین کے مشرق ومغرب کا مالک بنادیاجس میں ہم نے برکت رکھی ہے اور آپ کے رب کا نیک وعدہ بنی اسرائیل کے حق میں ان کے صبر کی وجہ سے پورا ہو اور ہم نے فرعون اور اس کی قوم کے ساختہ پرداختہ کارخانوں کو اور جو کچھ وہ اونچی اونچی عمارتیں بنواتے تھے سب کو درہم برہم کردیا۔“ اللہ تعالیٰ نے فرعون، ہامان، اور ان دونوں کی فوجوں کو وہ کچھ دکھانا چاہا جس کے خوف سے وہ لوگ اسرائیلی بچوں کو قتل کروا رہے تھے یعنی انھیں اپنی ہلاکت و بربادی کا نظارہ اپنی آنکھوں سے کرنا تھا یہ سب کچھ کیسے ہوا آئندہ آیتوں میں اللہ نے اسے بیان فرمایا ہے۔"],[5220,"§قرآن میں اکثر مقامات پر قصص الانبیاء کے ضمن میں سیدنا موسیٰ علیہ السلام کا ذکر پہلے کیوں آیا ہے؟\nقرآن کریم میں اکثر مقامات پر سیدنا موسیٰ علیہ السلام اور فرعون کا ذکر بڑی تفصیل سے کیا گیا ہے اور انبیاء علیہم السلام کے ذکر میں سیدنا موسیٰ علیہ السلام کا ذکر پہلے کیا گیا ہے۔ اس کی وجوہ ہم پہلے لکھ چکے ہیں۔ مختصراً یہ کہ موسیٰ علیہ السلام کو رسول اللہ صلی اللہ علیہ وسلم سے زیادہ شدید حالات میں فریضۂ رسالت سرانجام دینے کا حکم ہوا تھا۔ مثلاً یہ کہ سیدنا موسیٰ علیہ السلام جس قوم بنی اسرائیل کے فرد تھے، فرعون نے انھیں اچھوتوں کی طرح کم تر درجہ کی مخلوق اور عملاً غلام بنا کر رکھا ہوا تھا۔ جبکہ آپ اپنی قوم قریش ہی کے ایک فرد تھے۔ پھر سیدنا موسیٰ علیہ السلام کو فرعون جیسے مغرور، متمرد اور سرکش، فوراً بھڑک اٹھنے والے فرمانروا کے ہاں دعوت رسالت کے لیے بھیجا گیا تھا جبکہ آپ کے مخاطبین اوّل آپ صلی اللہ علیہ وسلم کی اپنی ہی قوم کے افراد تھے۔ تیسرے یہ کہ سیدنا موسیٰ علیہ السلام کو یہ بھی حکم تھا کہ دعوت توحید کے ساتھ اپنی قوم بنی اسرائیل کی رہائی کا بھی مطالبہ کریں جبکہ رسول اللہ صلی اللہ علیہ وسلم کو ایسا کوئی حکم نہ تھا۔ چوتھے یہ کہ آپ فرعون کے اشتہاری مجرم تھے۔ اور اس قصہ کا انجام یہ ہوتا ہے کہ بالآخر اللہ تعالیٰ سیدنا موسیٰ علیہ السلام اور ان کے ساتھیوں کی مدد کرکے انھیں فرعونیوں سے نجات دلاتے ہیں اور فرعون اور آل فرعون کو دریا میں غرق کرکے ایسے ظالموں کا صفحہ ہستی سے نام و نشان تک مٹا دیتے ہیں۔ گویا اس قصہ میں آپ صلی اللہ علیہ وسلم کے لیے اور مسلمانوں کے لیے سبق یہ ہے کہ جب موسیٰ علیہ السلام نے ایسے شدید حالات اور اللہ پر بھروسہ رکھتے ہوئے سب مصائب برداشت کئے تو آپ کو بھی کرنا چاہئیں اور بشارت یہ ہے کہ اللہ تعالیٰ اس معرکہ حق و باطل میں بالآخر اپنے پیغمبر اور ایمان لانے والوں کو ہی کامیاب کرتا ہے اور ان کے دشمن تباہ ہوجاتے ہیں۔"],[5221,"§فرعون کا لقب اور زمانہ\nشاہانِ مصر کا لقب، جیسے قدیم زمانہ میں ترکوں کے بادشاہ خاقان، یمن کے بادشاہ تُبّع، حبشہ کے بادشاہ نجاشی، روم کے بادشاہ قیصر اور ایران کے بادشاہ کسریٰ کہلاتے تھے ایسے ہی مصر کے بادشاہ فرعون کہلاتے تھے۔ موسیٰ علیہ السلام کو دو فرعونوںیادو بادشاہوں سے سابقہ پڑا تھا۔ جس فرعون نے آپ کی پرورش کی تھی اس کا نام رعمسیس تھا اور نبوت ملنے کے بعد جس کے ہاں آپ کو بھیجا گیا تھا وہ رعمسیس کا بیٹا منفتاح تھا ۔ ان کا عہد حکومت تقریباً چودہ سو سال قبل مسیح ہے۔"],[5222,"§فرعون کی سیاسی پالیسی . . . . قِبطی اور سِبطی کون لوگ تھے؟\nاپنی حکومت کو مستحکم کرنے اور مستحکم بنائے رکھنے کے سلسلہ میں اس کی سیاسی پالیسی یہ تھی کہ اس نے اپنی رعایا میں طبقاتی تقسیم پیدا کردی تھی۔ ایک تو اس کی اپنی قوم یا مصر کے قدیم باشندے تھے جنہیں قبطی کہتے ہیں اور یہ معزز طبقہ تھا۔ سرکاری مناصب بھی انھیں ہی مل سکتے تھے اور حکمران قوم ہونے کے ناطے سے ان کے حقوق کی ضرورت سے بھی زیادہ نگہداشت کی جاتی تھی۔ دوسرے بنی اسرائیل تھے۔ جو سیدنا یوسف علیہ السلام کے زمانہ یعنی تقریباً چار سو سال سے یہاں آکر آباد ہوئے تھے۔ اس وقت وہ حکمران قوم کی حیثیت سے آئے تھے لیکن ایک صدی بعد ہی ان میں جب بےدینی اور اخلاقی انحطاط شروع ہوگیا اور فرقوں میں بٹ گئے۔ تو اللہ نے ان سے حکومت چھین لی اور مصری لوگ ان پر قابض ہوگئے۔ انھوں نے ان بنی اسرائیل سے انتقاماً اچھوتوں اور شودروں کا سا سلوک روا رکھا ہوا تھا۔ معاشرہ میں ان کی کچھ عزت نہ تھی۔ کوئی سرکاری عہدہ انھیں نہیں مل سکتا تھا۔ یہ لوگ عموماً حکمران قوم کے افراد کے غلام، ملازم اور ان کی عورتیں بھی ان کے گھروں کا کام کاج کرتی تھیں۔ اس طرح فرعون نے عملاً ان لوگوں کو اپنا غلام بنا کر رکھا ہوا تھا۔"],[5223,"§سِبطیوں کی نسل کشی کے لئے فرعون کا اقدام\nمصر کی قومیت پرستی کی تحریک تو مدتوں پہلے شروع ہوچکی تھی اور اسی کے نتیجہ میں بنی اسرائیل (یعنی قبطیوں) سے ایسا ناروا سلوک کیا جاتا تھا۔ تاہم فرعون رعمسیس نے اس کے لیے انتہائی قدم یہ اٹھایا کہ آئندہ سے بنی اسرائیل کی ہاں پیدا ہونے والے لڑکے کو قتل کردیا جائے اور لڑکیوں کو زندہ رہنے دیا جائے۔ لڑکیاں یا عورتیں تو از خود قبطیوں یا آل فرعون کے قبضہ میں آجائیں گی اور اس طرح کچھ مدت بعد بنی اسرائیل کی نسل ہی ختم ہو کر مصریوں میں مدغم ہوجائے گی۔ چنانچہ فرعون کے اس حکم کی تعمیل کے لیے جاسوس قسم کی عورتیں مقرر کی گئی تھیں۔ جو بنی اسرائیل کے ہاں نوزائیدہ بچوں کی رپورٹ حکومت کو پیش کیا کرتی تھیں۔ اور یہ محض احتیاطی تدبیر تھی ورنہ بنی اسرائیل کے لیے آرڈر یہی تھا کہ وہ نوزائیدہ لڑکے کی اطلاع حکومت کو فراہم کریں اور وہ اس بات پر مجبور بھی تھے۔"],[5224,"§فرعون کا خواب کہ ایک اسرائیلی اس کی حکومت کا خاتمہ کرے گا\nبعض تفاسیر میں منقول ہے کہ فرعون کو ایک پریشان کن خواب آیا تھا جس کی نجومیوں نے اسے تعبیر یہ بتلائی تھی کہ بنی اسرائیل میں ایک لڑکا پیدا ہونے والا ہے جس کے ہاتھوں فرعون اور اس کی حکومت تباہ ہوجائے گی اور فرعون نے اسی خطرہ کے سد باب کے لیے بنی اسرائیل کے لڑکوں کے قتل کا حکم دیا تھا۔ اس پہلو سے اگر غور کیا جائے تو فرعون کا یہ اقدام سراسر حماقت اور استبداد تھا۔ کیونکہ اگر نجومیوں کی یہ تعبیر درست تھی تو یہ کام ہو کے رہنا چاہیے تھا اور وہ ہو کے رہا۔ خواب یا اس کی تعبیر میں یہ اشارہ تک نہیں پایا جاتا کہ اگر فرعون اس خطرہ کا کوئی سدباب سوچ لے تو بچ سکے گا۔ اور اگر یہ تعبیر غلط تھی تو پھر ویسے ہی یہ ایک سفاکانہ حرکت تھی۔ بہرحال دونوں صورتوں میں اس کا یہ اقدام ظالمانہ اور وحشیانہ قسم کا تھا۔ اور جہاں اس واقعہ خواب یا اس کی تعبیر کا تعلق ہے، اس کی صحت اور عدم صحت کے متعلق اللہ ہی بہتر جانتا ہے۔ اور یہ صورت نہ بھی ہوتی تو قومیت پرستی کی بنیاد پر حالات ایسے پیدا ہوچکے تھے کہ فرعون نے بنی اسرائیل کو مکمل طور پر کچل دینے کے لیے یہی اقدام مناسب سمجھا۔\nاور ابن کثیر اس خواب اور اس کی تعبیر کے واقعہ کی صورتِ حال یہ بتلاتے ہیں کہ بنی اسرائیل آپس میں سیدنا ابراہیم خلیل اللہ علیہ السلام کی ایک پیشین گوئی کا تذکرہ کیا کرتے تھے کہ ایک اسرائیل نوجوان کے ہاتھوں سلطنتِ مصر کی تباہی مقدر ہوگی۔ رفتہ رفتہ یہ بات فرعون کے کانوں تک بھی پہنچ گئی۔ اس احمق نے قضا و قدر کی روک تھام کے لیے یہ سفاکانہ اسکیم جاری کی تھی۔"],[5225,"§مظلوم بنی اسرائیل پر اللہ کی نظرکرم\nفرعون تو اس مظلوم گروہ کا کلی طور پر استیصال کرنا چاہتا تھا۔ مگر اللہ کو کچھ اور ہی منظور تھا۔ اللہ یہ چاہتا تھا کہ ایسی سفاک اور ظالم قوم کا استیصال ہونا چاہیے۔ اور جن بےچاروں پر یہ ظلم و ستم ڈھائے جارہے ہیں۔ انہیں نہ صرف ان سے نجات دلائی جائے۔ بلکہ انہیں ان ظالموں کی جائیدادوں اور ملک کا وارث بھی بنادیا جائے۔ دین کی امامت بھی ان کے سپرد کی جائے اور دنیا کی سرداری کا تاج بھی ان کے سر پر رکھ دیا جائے۔ اور اللہ کی سنت جاریہ یہی ہے کہ وہ ظالموں اور متکبروں سے زمین کو خالی کرا کر ان کی جگہ ان مظلوموں کو آباد کرتا ہے۔ جن پر ظلم ڈھائے گئے تھے۔\nطٰسٓمّٓ، کا شمار حروف مقطعات سے ہوتا ہے ان سے قرآن کریم کا اعجاز مترشح ہوتا ہے کہ یہ ایسی کتاب ہے جو فصاحت و بلاغت کے لحاظ سے مقام اعجاز پر فائز ہے اور اس جانب اشارہ ہے کہ قرآن پاک حروف تہجی سے مرکب ہے۔\nتِلْكَ اٰيٰتُ الْكِتٰبِ الْمُبِيْنِ: یہ تو روشن واضح کتاب کی آیات ہیں جن میں اعجاز نمایاں ہے جو احکام شریعت کے لحاظ سے واضح ہے اے محمد صلی اللہ علیہ وسلم ہم آپ پر روح الامین جبرائیل کی وساطت سے موسیٰ علیہ السلام اور فرعون ملعون کے واقعات کو سچائی کے دامن کو تھامے ہوئے بیان کرتے ہیں جس میں ہرگز شک وشبہ کا کوئی شائبہ تک نہیں ہے ان لوگوں کے لیے جو قرآن پاک کو سچا باور کرتے ہیں اور اس سے فوائد حاصل کرتے ہیں، بعدازاں فرعون سرکش کا واقعہ بیان کرتے ہوئے وضاحت کی ہے کہ فرعون تو متکبر شخص تھا جو مصر کی سرزمین میں حدا عتدال سے گزرا اور سرکش تھا، اس نے وہاں کے باشندوں کو اپنی مختلف قسم کی خدمات کے لیے گروہوں میں تقسیم کردیا تھا ان میں سے ایک گروہ کو جو بنی اسرائیل کے لقب کے ساتھ متعارف تھے ان کو اس نے اپنے غلام بنا رکھا تھا، اور انھیں ذلیل سمجھتا تھا اور انھیں بدترین قسم کے عذاب میں مبتلا کررکھا تھا ان کے لڑکوں کو قتل کردیتا تھا اور لڑکیوں کو اپنی اور قبطیوں کی خدمت کے لیے زندہ رہنے دیتا تھا، ذہن نشین کریں کہ بنی اسرائیل کے لڑکوں کو قتل کرنے کا سبب یہ تھا کہ فرعون نے ایک رات خواب دیکھا کہ زبردست قسم کی آگ بیت المقدس کی جانب سے چل کر ملک مصر کی زمین میں پہنچی ہے تو اس نے قبطیوں کو جلاکرراکھ کردیا ہے جب کہ بنی اسرائیل محفوظ رہے تو فرعون نے نجومیوں اور کاہنوں سے اس خواب کی تاویل دریافت کی انھوں نے فرعون کی خواب کی تاویل پیش کرتے ہوئے کہا کہ ایک لڑکابنی اسرائیل میں تولد پذیر ہوگا اس کے سبب تیری بادشاہت کا خاتمہ ہوگا اور تو بھی اس میں ہلاک ہوجائے گا، تو اس نے حکم نافذ کیا کہ بنی اسرائیل کے جس گھر میں لڑکے کی پیدائش ہو تو اس لڑکے کو فوراً موت کے گھاٹ اتاردیا جائے اس مقام کی وضاحت ایک شاعر کے شعر سے ملاحظہ کریں :\nیوں قتل سے بچوں کے وہ بدنام نہ ہوتا\nافسوس کہ فرعون کو کالج کی نہ سوجھی\nاِنَّهٗ كَانَ مِنَ الْمُفْسِدِيْنَ: اس میں ہرگز شک وشبہ کی گنجائش نہیں کہ فرعون کا شمار زمین فساد انگیزی کرنے والوں سے ہوتا تھا بلکہ زبردست سرکش قسم کی شخصیت سے جاناپہچانا جاتا تھا یہی وجہ تھی کہ اس نے خود کو ربوبیت کے مقام پر استوار کیا اور بچوں کے قتل میں کوئی دقیقہ فروگذاشت نہ کیا اور انسانیت کی ذلت میں ہر قسم کے حربے کو استعمال کیا۔"],[5226,"§اللہ کی رحمت کا بیان\nوَ نُرِيْدُ اَنْ نَّمُنَّ عَلَى الَّذِيْنَ اسْتُضْعِفُوْا : اور ہم اپنے وصف رحمت کے باعث چاہتے تھے کہ بنی اسرائیل سے ان لوگوں پر احسان کریں جن کو بنی اسرائیل سے کمزور سمجھاجاتا تھا تو ہم انھیں فرعون اور اس کے ظلم وستم سے نجات عطا کریں اور ہم انھیں لیڈر بنائیں کہ اچھے کاموں میں ان کی پیروی کی جائے جبکہ قبل ازیں انھیں ذلیل سمجھاجاتا تھا اور ہم انھیں فرعون اور اس کی بادشاہت کا وارث بنائیں اور ان کے گھروں میں آباد ہوں جبکہ قبل ازیں قبطی لوگ مصر کے اونچے شہری تسلیم کیے جاتے تھے اور ہم انھیں مصر اور شام کی سرزمین کی بادشاہت سے شام کام کرنا چاہتے تھے کہ وہ وہاں نہایت آزادی کے ساتھ جس طرح چاہیں تصرف کرتے رہیں اور ہم سرکش فرعون، ہامان، اور قبطیوں کو ان بنی اسرائیلیوں سے جنہیں وہ کمزور باور کرتے تھے وہ کیفیت دکھائیں جس سے وہ خوف زدہ تھے کہ ان کی بادشاہت تاخت و تاراج ہوجائے گی اور وہ بنی اسرائیل کے ایک بچے کے ہاتھ سے موت کے گھاٹ اتار دیے جائیں گے۔\n﴿وَاَوْحَيْنَاۤ اِلٰۤى اُمِّ مُوْسٰۤى اَنْ اَرْضِعِيْهِۚ فَاِذَا خِفْتِ عَلَيْهِ فَاَلْقِيْهِ فِي الْيَمِّ وَلَا تَخَافِيْ وَلَا تَحْزَنِيْۚ اِنَّا رَآدُّوْهُ اِلَيْكِ وَجَاعِلُوْهُ مِنَ الْمُرْسَلِيْنَ۰۰۷ فَالْتَقَطَهٗۤ اٰلُ فِرْعَوْنَ لِيَكُوْنَ لَهُمْ عَدُوًّا وَّحَزَنًاؕ اِنَّ فِرْعَوْنَ وَهَامٰنَ وَجُنُوْدَهُمَا كَانُوْا خٰطِـِٕيْنَ۰۰۸ وَقَالَتِ امْرَاَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّيْ وَلَكَؕ لَا تَقْتُلُوْهُࣗۖ عَسٰۤى اَنْ يَّنْفَعَنَاۤ اَوْ نَتَّخِذَهٗ وَلَدًا وَّهُمْ لَا يَشْعُرُوْنَ۰۰۹﴾\nاور ہم نے موسیٰ کی ماں کو الہام کیا کہ تو اسے دودھ پلا، پھر جب تو اس کے بارے میں ڈرے تو اسے دریا میں ڈال دینا، اور نہ ڈرنا اور نہ غم کھانا، بے شک ہم اسے تیری طرف لوٹانے والے ہیں، اور اسے رسولوں میں سے بنانے والے ہیں⟦7⟧ چنانچہ فرعون کے گھر والوں نے اسے (دریا سے) اٹھا لیا، تاکہ وہ ان کے لیے دشمن اور باعث غم ہے، بلاشبہ فرعون اور ہامان اور ان دونوں کے لشکر خطا کار تھے⟦8⟧ اور فرعون کی بیوی نے کہا: (یہ تو) میرے لیے اور تیرے لیے آنکھوں کی ٹھنڈک ہے، اسے قتل نہ کرو، شاید یہ ہمیں نفع دے یا ہم اسے بیٹا بنا لیں، اور وہ (انجام سے) بے خبر تھے⟦9⟧"],[5227,"§سیّدنا موسیٰ علیہ السلام کی ماں کی طرف تدبیر کے بارے میں وحی\nمؤرخین نے ذکر کیا ہے کہ فرعون نے جب بہت کثیر تعداد میں بنی اسرائیل کے لڑکے قتل کرا دیے تو قبطیوں کو یہ خدشہ لاحق ہوا کہ اس طرح بنی اسرائیل تو ختم ہو جائیں گے اور ان کے بجائے محنت و مشقت کے سارے کام انہیں خود کرنا پڑیں گے، اس بات کا انہوں نے فرعون سے ذکر کرتے ہوئے کہا کہ اگر یہی صورت حال برقرار رہی کہ بوڑھے مر جائیں اور بچے قتل کر دیے جائیں تو ان کی عورتوں کے لیے تو ان اعمال شاقہ کو سر انجام دینا ممکن نہ ہوگا جو ان کے مرد کیا کرتے تھے تو یہ سارے کام ہمیں خود کرنا پڑیں گے، یہ بات سن کر فرعون نے حکم دے دیا کہ بنی اسرائیل کے لڑکے ایک سال قتل کر دیے جائیں اور ایک سال قتل نہ کیے جائیں، پس ہارون علیہ السلام کی ولادت اس سال ہوئی جس میں بچوں کو قتل نہیں کیا جاتا تھا اور موسیٰ علیہ السلام کی ولادت اس سال ہوئی جس میں بچوں کو قتل کیا جاتا تھا۔ فرعون نے اس کام کے لیے کچھ آدمی مقرر کر رکھے تھے اور دائیوں کی ڈیوٹی لگا رکھی تھی کہ وہ عورتوں کی نگرانی کریں اور جسے حاملہ دیکھیں اس کا نام لکھ لیں، ولادت کے وقت قبطی عورتیں بھی موجود ہوتی تھیں، بنی اسرائیل کی کوئی عورت اگر لڑکی کو جنم دیتی تو وہ چلی جاتیں اور اگر اس کے ہاں لڑکا پیدا ہوتا تو وہ اطلاع دے دیتیں، پھر جلاد ہاتھوں میں تیز چھریاں پکڑے ہوئے آ جاتے اور وہ بچے کو ذبح کر دیتے تھے، اللہ تعالیٰ ان کو ہر قسم کی بھلائی اور اچھائی سے دو ررکھے۔\nموسیٰ علیہ السلام کی والدہ کو جب حمل قرار پایا تو ان کے حمل کے آثار اس طرح نمایاں نہ تھے جس طرح دیگر حاملہ عورتوں کے آثار نمایاں ہوتے ہیں حتیٰ کہ ان کے حاملہ ہونے کے بارے میں دائیوں کو بھی علم نہ ہو سکا لیکن جب انہوں نے لڑکے کو جنم دیا تو انہیں بے حد تشویش اور شدید خوف لاحق ہوا جبکہ اس لڑکے سے انہیں بہت زیادہ محبت بھی تھی، موسیٰ علیہ السلام کو جو بھی دیکھتا وہ آپ سے شدید محبت کرنے لگتا اور آپ سے محبت کرنے والا طبعاً اور شرعاً بے پناہ سعادت مند تھا۔ ارشاد باری تعالیٰ ہے: ﴿وَاَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّيْ࣢ۚ﴾ (طٰہٰ: 39) ’’اور میں نے آپ پر اپنی طرف سے محبت ڈال دی۔‘‘"],[5228,"§سیّدنا موسیٰ علیہ السلام فرعون کے گھر میں\nموسیٰ کی والدہ کو جب شدید گھبراہٹ اور خوف لاحق ہوا تو ان کے دل میں اللہ تعالیٰ نے یہ بات ڈال دی جیسا کہ اسی نے ارشاد فرمایا ہے: ﴿وَاَوْحَيْنَاۤ اِلٰۤى اُمِّ مُوْسٰۤى اَنْ اَرْضِعِيْهِۚ فَاِذَا خِفْتِ عَلَيْهِ فَاَلْقِيْهِ فِي الْيَمِّ وَلَا تَخَافِيْ وَلَا تَحْزَنِيْۚ اِنَّا رَآدُّوْهُ اِلَيْكِ وَجَاعِلُوْهُ مِنَ الْمُرْسَلِيْنَ۰۰۷﴾ ’’اور ہم نے موسیٰ علیہ السلام کی ماں کی طرف وحی بھیجی کہ تو اس کو دودھ پلا جب تجھے اس کے بارے میں کچھ خوف پیدا ہو تو اسے دریا میں ڈال دینا اور نہ تو خوف کرنا اور نہ رنج کرنا، بلاشبہ ہم اس کو تیرے پاس لوٹانے والے ہیں اور (پھر) اسے رسولوں میں سے بنانے والے ہیں۔‘‘\nارشاد باری تعالیٰ ہے: ﴿وَقَالَتِ امْرَاَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّيْ وَلَكَؕ﴾ ’’اور فرعون کی بیوی نے کہا کہ (یہ) میری اور تمہاری (دونوں کی) آنکھ کی ٹھنڈک ہے۔‘‘ یعنی فرعون نے جب اسے دیکھا تو اس خوف کی وجہ سے اس کے قتل کا ارادہ کر لیا کہ کہیں یہ بنی اسرائیل کا بچہ نہ ہو تو فرعون کی بیوی آسیہ بنت مزاحم نے اس سے جھگڑنا اور بچے کا دفاع کرنا اور بچے کو پیار کرکے دکھانا شروع کر دیا، اس نے کہا: ﴿قُرَّتُ عَيْنٍ لِّيْ وَلَكَؕ﴾ ’’یہ میری اور تمہاری (دونوں کی) آنکھ کی ٹھنڈک ہے۔‘‘ فرعون نے کہا کہ یہ تمہاری آنکھوں کی ٹھنڈک ہوگا، میری آنکھوں کی ٹھنڈک ہرگز نہیں ہے اور امر واقع میں بھی ایسا ہی ہوا کہ آگے چل کر اس بچے کے سبب اللہ تعالیٰ نے فرعون کی بیوی کو تو ہدایت نصیب فرما دی جبکہ فرعون کو اس کے ہاتھ ہلاک کر دیا۔ ارشاد باری تعالیٰ ہے: ﴿عَسٰۤى اَنْ يَّنْفَعَنَاۤ﴾ ’’شاید کہ یہ ہمیں فائدہ پہنچائے۔‘‘ اور اسے اس سے واقعی فائدہ پہنچا کہ اللہ تعالیٰ نے اسے اس کے سبب دنیا میں ہدایت عطا فرما دی اور آخرت میں جنت میں بسا دیا، ﴿اَوْ نَتَّخِذَهٗ وَلَدًا﴾ ’’یا ہم اسے بیٹا بنا لیں۔‘‘ فرعون کی بیوی نے اسے متبنّیٰ بنانے کا ارادہ کیا کیونکہ اس کی اپنی کوئی اولاد نہ تھی، ﴿وَّهُمْ لَا يَشْعُرُوْنَ۰۰۹﴾ ’’اور وہ شعور نہیں رکھتے تھے۔‘‘ یعنی وہ نہیں جانتے تھے کہ انہوں نے جو اس بچے کو اٹھا لیا ہے تو اس میں اللہ تعالیٰ کی طرف سے کس قدر عظیم الشان حکمت بالغہ اور حجتِ قاطعہ ہے۔"],[5229,"§سیدنا موسیٰ علیہ السلام کی پیدائش اور آپ کی والدہ کو وحی کے ذریعہ ہدایات\nیہ وحی موسیٰ علیہ السلام کی پیدائش کے بعد ہوئی اور یہ وحی چار اُمور پر مشتمل تھی :\n(1) جب تک اس بچے کی سراغ رسانی نہیں ہوتی، اسے اپنے پاس ہی رکھو اور اسے دودھ پلاتی رہو۔ بعض مفسرین نے لکھا ہے کہ ام موسیٰ نے آپ کو تین ماہ تک چھپائے رکھا تھا۔\n(2) جب یہ راز فاش ہونے لگے اور تمہیں یہ خطرہ محسوس ہو کہ اب عمال حکومت اس بچے کو پکڑ کرلے جائیں گے۔ تو اس کو کسی تابوت یا ٹوکرے میں رکھ کر دریا کی موجوں کے سپرد کردینا۔\n(3) اور دریا میں ڈالتے وقت اس بات کا ہرگز اندیشہ نہ کرنا کہ یہ بچہ ضائع ہوجائے گا۔ بلکہ ہم بہت جلد یہ بچہ تیری ہی طرف لوٹا دیں گے۔ تو ہی اسے دودھ پلائے گی اور اس کی پرورش کرے گی۔ یہی وہ بچہ ہے جو بنی اسرائیل میں رسول بننے والا ہے۔"],[5230,"§سیدنا موسیٰ علیہ السلام فرعون کی بیوی کے پاس\nچنانچہ اُم موسیٰ علیہ السلام نے وحی کے مطابق اس بچہ کو کسی تابوت یا ٹوکرے میں رکھ کر دریائے نیل کی موجوں کے سپرد کردیا۔ یہ تابوت موجوں پر سفر کرتے کرتے جب اس مقام پر پہنچا جہاں فرعون کے محلات تھے تو فرعون کے اہل کاروں نے اسے دیکھ لیا اور اسے پکڑ کر فرعون اور اس کی بیوی کے سامنے پیش کردیا۔ یا ممکن ہے کہ فرعون اور اس کی بیوی سیر و تفریح کی غرض سے محل سے نکل کر دریا کے کنارے آئے ہوئے ہوں اور انھوں نے خود یہ تابوت دیکھ کر اسے نکال لانے کا حکم دیا ہو۔ چنانچہ فرعون اور اس کی بیوی اس بچہ کو اپنے ہاں لے آئے۔ جو ان کا دشمن اور ان کی تباہی کا باعث بننے والا تھا۔"],[5231,"§اپنی بیوی کی درخواست پر فرعون کا سیدنا موسیٰ علیہ السلام کو متبنّیٰ بنانا اور پرورش کرنا\nاب ظاہری قیاس سے تو یہی معلوم ہو رہا تھا کہ یہ بچہ کسی بنی اسرائیل کے فرد کا ہی ہوسکتا ہے جس نے بچہ کے قتل کے خطرہ کی وجہ سے اس کے قتل ہونے سے بہتر یہی سمجھا کہ اسے دریا کے سپرد کردیا جائے۔ اس لحاظ سے فرعون کو یہ بچہ فوراً مار ڈالنا چاہیے تھا۔ مگر بچے کی صورت ایسی پیاری اور پُرکشش تھی کہ فرعون کی بیوی آسیہ جس کے متعلق قرآن نے ایک دوسرے مقام پر تصریح کر دی ہے کہ وہ فرعون کے ایسے ظالمانہ کاموں سے سخت بیزار تھی، نے جب یہ بچہ دیکھا تو فوراً اس کا دل محبت سے بھر آیا۔ مفسرین کہتے ہیں کہ اس کی ایک وجہ یہ بھی تھی کہ اس کے ہاں اولاد نہ تھی۔ چنانچہ وہ فوراً کہنے لگی کہ یہ بچہ تو بہت پیارا ہے کہ جسے دیکھ کر ہی دل خوش ہوجاتا ہے اور ہماری آنکھوں کی ٹھنڈک ہے۔ لہٰذا ہم خود اس کی تربیت کریں گے۔ اسے قتل کرنا کسی طرح بھی مناسب نہیں۔ پھر یہ بچہ ہمارے لیے مفید بھی ہوسکتا ہے۔ جب اس کی پرورش کریں گے تو یہ ہمارا ہی بچہ ہے۔ اسے کیا خبر ہوسکتی ہے کہ اس کا بنی اسرائیل کے کسی فرد سے بھی کچھ تعلق ہے۔ اگر ہم اسے اپنا بیٹا بنالیں گے تو اس کی ساری اہلیتیں بنی اسرائیل کے بجائے ہمارے کام آسکتی ہیں۔ لہٰذا اسے متبنّیٰ بنا لینے میں ہمیں بہت سے فائدے حاصل ہوسکتے ہیں۔"],[5232,"§تدبیر کند بندہ تقدیر کند خندہ\nیعنی ان دونوں کو یہ معلوم نہ تھا کہ جو باتیں وہ کر رہے ہیں وہ خود نہیں کر رہے بلکہ مشیتِ الٰہی ان کے منہ سے یہ الفاظ نکلوا رہی ہے۔ یا انہیں کیا خبر تھی کہ جس بچہ کو مارنے کی خاطر انھوں نے ہزارہا بچے قتل کردیئے ہیں یا کر رہے ہیں وہ بچہ ان کے اپنے ہاتھ میں جسے یہ اپنا متبنّیٰ بنانے کے مشورے کر رہے ہیں یا یہ کہ جس بچہ پر اس وقت ان کا اتنا دل بھر آیا ہے۔ وہی ان کا دشمن بن جائے گا۔ اور اسی کے ہاتھوں ان کی اور ان کی حکومت کی تباہی واقع ہوگی۔\nوحی سے مراد یہاں دل میں بات ڈالنا ہے، وہ وحی نہیں ہے، جو انبیاء پر فرشتے کے ذریعے سےنازل کی جاتی تھی اور اگر فرشتے کے ذریعے سے بھی آئی ہو، تب بھی اس ایک وحی سے اُم موسیٰ کا نبی ہونا ثابت نہیں ہوتا، کیونکہ فرشتے بعض دفعہ عام انسانوں کےپاس بھی آجاتے ہیں۔ جیسے حدیث میں اقرع، ابرص اور اعمی کے پاس فرشتوں کا آنا ثابت ہے۔ اور سیّدہ مریم[ کے پاس بھی ﴿فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا۰۰۱۷﴾ (مریم:17) تو وہ فرشتہ اس (مریم) کے سامنے پورا انسان بن کر آیا، مریم[ کے نبی نہ ہونے پر سب کا اتفاق ہے۔ متفق علیہ (بخاری، رقم 3277)"],[5233,"§فرعون کا سیّدنا موسیٰ علیہ السلام کو بیٹا بناکر دوبارہ اس کی ماں کی جانب بھیجنے کا بیان\nوَ اَوْحَيْنَاۤ اِلٰۤى اُمِّ مُوْسٰۤى اَنْ اَرْضِعِيْهِ: ہم نے سیّدنا موسیٰ علیہ السلام کی والدہ کے دل میں الہام کیا کہ آپ اس کی رضاعت کے سلسلہ کو جاری رکھیں جب تک کہ اس عمل کو پوشیدہ رکھنا ممکن ہوتا کہ آپ کے اور اس کے دشمن اس کو کسی نقصان سے ہم کنار نہ کریں لیکن جب تجھے اس کے بارے میں فرعون کے جاسوسوں سے اندیشہ لاحق ہوجوبنی اسرائیل کے لڑکوں کو اس کے حکم کے باعث قتل کرنا چاہتے ہیں یا جس گھر میں بچے کی پیدائش ہوتی ہے اس گھر کے پڑوسیوں سے خطرہ لاحق ہو کہ جب وہ نومولود بچے کے رونے کی آواز سنیں گے توچغل خوری کرتے ہوئے اس سے آگاہ کردیں گے اس بنا پر موسیٰ علیہ السلام کی والدہ کو حکم دیا گیا کہ آپ بچے کو دریائے نیل کی لہروں کے سپرد کردیں اور یہ خوف لاحق نہ ہو کہ بچہ ہلاک ہوجائے گا اور بچے کی جدائی کے باعث غم نہ کرنا، چنانچہ سورة طہ کی تفسیر میں جس کیفیت کے ساتھ موسیٰ علیہ السلام کو دریائے نیل کی لہروں کے سپرد کیا اس کی تفصل کا ذکر ہوچکا ہے اس کے بعداللہ پاک نے ان کی والدہ کو صبردلاتے ہوئے آگاہ کیا کہ اسے صحیح سلامت آپ کی جانب پہنچادیا جائے گا آپ ہی اس کو دودھ پلائیں گی اور ہم اسے پیغمبری کے منصب پر فائز کریں گے اور بنی اسرائیل کو اس کے ذریعہ ظلم وستم سے نجات عطا کریں گے۔\nفصاحت و بلاغت کے لحاظ سے ایک ہی آیت میں دوامر کے صیغے اور دونہی کے اور دوخبریں اور دوبشارتیں موجود ہیں، ان ارضعیہ، فالقیہ، دونوں امر ہیں﴿وَلَا تَخَافِيْ وَلَا تَحْزَنِيْۚ﴾ دونوں نہیں کے صیغے ہیں ﴿اِنَّا رَآدُّوْهُ اِلَيْكِ وَجَاعِلُوْهُ مِنَ الْمُرْسَلِيْنَ۰۰﴾ اور دوخبریں اور دوبشارتیں ہیں۔\nفَالْتَقَطَهٗۤ اٰلُ فِرْعَوْنَ : چنانچہ اسی رات کی صبح کو جس رات کے لمحات میں صندوق کو دریائے نیل کی لہروں کے حوالے کیا تھا فرعون کے سپاہیوں نے اس کو اٹھایا اس بچے کے بارے میں فرعون کو مطلع کیا گیا تو اس نے اس کے ذبح کرنے کا ارادہ کیا اس خطرہ کے پیشِ نظر کہ کہیں یہ بچہ بنی اسرائیل کی نسل سے نہ ہو اور اس کے ہاتھوں سے ہماری ہلاکت و بربادی نہ ہوجائے لیکن فرعون کی بیوی نے اس کو ذبح ہونے سے تحفظ عطا کیا فرمایا فرعون کی بیوی کی امیدوں کے برعکس وہ ان کے لیے دشمنی اور غم و اندوہ کا سبب بنا۔\nاِنَّ فِرْعَوْنَ وَ هَامٰنَ وَ جُنُوْدَهُمَا كَانُوْا خٰطِـِٕيْنَ: یہ حقیقت ہے کہ فرعون ہامان، اور ان کے لشکری لوگ سب خطاکار ثابت ہوئے انھوں نے انجام کے بارے میں غور و فکر نہ کیا یہی وجہ ہے کہ انھوں نے اپنے اقتدار کو تحفظ عطا کرنے کے لیے تو ہزاروں بچوں کو موت کے گھاٹ اتاردیا لیکن جس شخص کے باعث ان کے اقتدار کا سورج غروب ہواوہ بچہ فرعون کے شاہی گھر میں پرورش پاتارہا جب وہ جوان ہوا تو اس نے ان کے ساتھ وہی انداز اختیار کیا جس سے وہ خوف زدہ تھے۔\nوَ قَالَتِ امْرَاَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّيْ وَ لَكَ: جب نومولود بچہ فرعون کے گھر میں پہنچا تو فرعون کی بیوی نے اس کے دفاع میں غیر معمولی پارٹ ادا کیا اس نے کھلے الفاظ میں انھیں اس حقیقت سے ہم کنار کیا کہ یہ بچہ تو نہ صرف یہ کہ میری آنکھوں کی ٹھنڈک ثابت ہوگا بلکہ تمہاری آنکھوں کی بھی ٹھنڈک ثابت ہوگا اور اس کو دیکھ کر دلوں میں خوشی کی لہردوڑ جائے گی چنانچہ بیوی کے مطالبہ پر فرعون نے بچہ اس کے سپرد کردیابالخصوص اس وجہ سے کہ وہ اولاد نرینہ سے محروم تھی جب کہ انھیں مستقبل کے بارے میں کچھ علم نہ تھا اس کا علم تو اس ذات کو تھا جو پوشیدہ معاملات سے آگاہ ہے بلکہ مستقبل کے سبھی امور کا اس کو علم ہے۔\n﴿وَاَصْبَحَ فُؤَادُ اُمِّ مُوْسٰى فٰرِغًاؕ اِنْ كَادَتْ لَتُبْدِيْ بِهٖ لَوْ لَاۤ اَنْ رَّبَطْنَا عَلٰى قَلْبِهَا لِتَكُوْنَ مِنَ الْمُؤْمِنِيْنَ۰۰۱۰ وَقَالَتْ لِاُخْتِهٖ قُصِّيْهِ١ٞؗ فَبَصُرَتْ بِهٖ عَنْ جُنُبٍ وَّهُمْ لَا يَشْعُرُوْنَۙ۰۰۱۱ وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِنْ قَبْلُ فَقَالَتْ هَلْ اَدُلُّكُمْ عَلٰۤى اَهْلِ بَيْتٍ يَّكْفُلُوْنَهٗ لَكُمْ وَهُمْ لَهٗ نٰصِحُوْنَ۰۰۱۲ فَرَدَدْنٰهُ اِلٰۤى اُمِّهٖ كَيْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ اَنَّ وَعْدَ اللّٰهِ حَقٌّ وَّلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُوْنَࣖ۰۰۱۳﴾\nاور موسیٰ کی ماں کا دل (صبر و قرار سے) خالی ہو گیا، بے شک قریب تھا کہ وہ اسے ظاہر کر دیتی، اگر ہم نے اس کا دل مضبوط نہ کر دیا ہوتا، تاکہ وہ (ہمارے وعدے پر) یقین کرنے والوں میں سے ہو⟦10⟧ اور موسیٰ کی ماں نے اس کی بہن سے کہا: تو اس کے پیچھے پیچھے جا، پھر وہ (گئی تو) اسے دور سے دیکھتی رہی، جبکہ وہ (فرعونی) بے خبر تھے⟦11⟧ اور ہم نے موسیٰ پر دائیوں (کے دودھ) کو پہلے ہی سے حرام کر دیا تھا، پھر موسیٰ کی بہن نے کہا: کیا میں تمھیں ایک گھر والوں کا بتائوں جو تمھارے لیے اس کی پرورش کریں اور وہ اس کے خیر خواہ بھی ہوں؟⟦12⟧ چنانچہ ہم نے اسے اس کی ماں کے پاس لوٹا دیا، تاکہ اس کی آنکھیں ٹھنڈی ہوں اور وہ غم نہ کھائے اور تاکہ وہ جان لے کہ بے شک اللہ کا وعدہ سچا ہے اور لیکن اکثر لوگ نہیں جانتے⟦13⟧"],[5234,"§سیّدنا موسیٰ علیہ السلام کی ماں کا شدید غم اور بچے کی واپسی\nاللہ تعالیٰ نے موسیٰ علیہ السلام کی والدہ کے بارے میں بیان فرمایا ہے کہ جب ان کا بچہ دریا میں چلا گیا تو ان کا دل بے قرار ہو گیا۔ ﴿فٰرِغًا١ؕ ﴾ کے معنی یہ ہیں کہ دل موسیٰ علیہ السلام کے سوا دنیا کی ہر چیز سے خالی ہو گیا، یہ قول ابن عباس رضی اللہ عنہما، مجاہد، عکرمہ، سعید بن جبیر، ابو عبیدہ، ضحاک، حسن بصری، قتادہ اور دیگر ائمہ تفسیر رحمہم اللہ کا ہے۔ (تفسیر الطبری: 45,44/20 وتفسیر ابن ابی حاتم: 2946/9) ﴿اِنْ كَادَتْ لَتُبْدِيْ بِهٖ﴾ ’’قریب تھا کہ وہ اس (بات) کو ظاہر کر دیتیں۔‘‘ یعنی اگر اللہ تعالیٰ انہیں صبر و قرار عطا نہ فرماتا تو قریب تھا کہ وہ شدید غم و حزن اور افسوس کے باعث اسی بات کو ظاہر کر دیتیں کہ ان کا بیٹا دریا میں بہہ گیا ہے اور وہ ساری صورت حال بیان کر دیتیں۔ ﴿لَوْ لَاۤ اَنْ رَّبَطْنَا عَلٰى قَلْبِهَا لِتَكُوْنَ مِنَ الْمُؤْمِنِيْنَ۰۰۱۰ وَقَالَتْ لِاُخْتِهٖ قُصِّيْهِ١ٞ﴾ ’’اگر یہ بات نہ ہوتی کہ ہم ان کے دل مضبوط کر دیتے (تو وہ بیان کر دیتیں) تاکہ وہ یقین کرنے والوں میں سے ہو اور اس نے اس کی بہن سے کہا کہ اس کے پیچھے پیچھے جا۔‘‘ موسیٰ کی ماں نے اپنی بیٹی کو حکم دیا جو بڑی عمر کی تھی اور اس قابل تھی کہ جو اس سے کہا جائے اسے یاد رکھے، بہر حال اس سے کہا: ﴿قُصِّيْهِ﴾ ’’اس کے پیچھے پیچھے جا۔‘‘ اس کے حالات سے باخبر رہنا اور شہر کے مختلف علاقوں میں اس کے بارے میں پھیلنے والی خبروں کو معلوم کرنا، پس وہ اس مقصد کی خاطر گھر سے باہر نکل آئی، ﴿فَبَصُرَتْ بِهٖ عَنْ جُنُبٍ﴾ ’’تو وہ اسے دور سے دیکھتی رہی۔‘‘\nسیّدنا ابن عباس رضی اللہ عنہما فرماتے ہیں کہ وہ ایک طرف سے دیکھتی رہی۔ (تفسیر ابن ابی حاتم: 2948/9 وتفسیر الطبری: 49/20) مجاہد رحمہ اللہ فرماتے ہیں کہ اس کے معنی یہ ہیں کہ وہ دور سے دیکھتی رہی۔ (تفسیر الطبری: 48/20 وتفسیر ابن ابی حاتم: 2948/9) اور قتادہ رحمہ اللہ کہتے ہیں کہ وہ تجاہلِ عارفہ سے اس کی طرف دیکھتی رہی۔ (تفسیر ابن ابی حاتم: 2949/9 وتفسیر الطبری: 49/20)\nسیّدنا موسیٰ علیہ السلام جب فرعون کے محل میں پہنچ گئے، فرعون کی بیوی نے (موسیٰ علیہ السلام سے) محبت کی اور فرعون سے جان بخشی کروا لی تو محل میں موجود دودھ پلانے والی تمام عورتوں کو بلایا گیا مگر موسیٰ علیہ السلام نے کسی کا دودھ نہ پیا اور سب کا دودھ پینے سے انکار کر دیا تو وہ بازار میں چلے گئے تاکہ کسی ایسی عورت کو تلاش کر لیں جس کا یہ بچہ دودھ پی لے، موسیٰ علیہ السلام کی بہن نے جب لوگوں کے ہاتھوں میں اس بچے کو دیکھا تو اسے پہچان لیا، البتہ اس بات کا اظہار نہ کیا اور نہ وہ لوگ خود ہی سمجھ سکے کہ یہ لڑکی اس لڑکے کی بہن ہے۔\nارشاد باری تعالیٰ ہے: ﴿وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِنْ قَبْلُ﴾ ’’اور ہم نے پہلے ہی سے اس پر دائیوں (کے دودھ) کو حرام کر دیا تھا۔‘‘ اس سے مراد حرمتِ قدری ہے اور یہ اس لیے تھا کہ اللہ تعالیٰ کے ہاں آپ کو عزت و کرامت حاصل تھی اور اس میں دوسری حکمت یہ تھی کہ اللہ تعالیٰ نہیں چاہتا تھا کہ آپ اپنی ماں کے سوا کسی اور عورت کا دودھ پئیں کیونکہ اللہ تعالیٰ اس بات کو آپ کی ماں کے پاس آپ کی واپسی کا سبب بنانا چاہتا تھا تاکہ آپ کی ماں ہی آپ کو دودھ پلائے اور اللہ تعالیٰ آپ کی ماں کے ہر قسم کے خوف کو دور کرکے انہیں امن و چین بھی عطا فرمانا چاہتا تھا۔ بہر حال موسیٰ علیہ السلام کی بہن نے جب یہ دیکھا کہ یہ لوگ اس بارے میں حیران و پریشان ہیں کہ بچہ کس عورت کا دودھ پیے گا، ﴿فَقَالَتْ هَلْ اَدُلُّكُمْ عَلٰۤى اَهْلِ بَيْتٍ يَّكْفُلُوْنَهٗ لَكُمْ وَهُمْ لَهٗ نٰصِحُوْنَ۰۰۱۲﴾ ’’تو اس (موسیٰ علیہ السلام کی بہن) نے کہا: کیا میں تمہیں ایسے گھر والے بتائوں جو تمہارے لیے اس (بچے) کو پالیں اور وہ اس کے خیر خواہ ہوں۔‘‘\nسیّدنا ابن عباس رضی اللہ عنہما فرماتے ہیں کہ جب اس نے یہ بات کہی تو انہوں نے لڑکی کو پکڑ لیا اور اس کے بارے میں شک میں پڑ گئے اور کہنے لگے کہ تجھے کیسے معلوم ہوا کہ وہ اس کے بارے میں خیر خواہی و شفقت سے کام لیں گے۔ اس نے جواب دیا کہ اس لیے کہ وہ بادشاہ کی خوشی اور منفعت کے خواہش مند ہیں، یہ جواب سن کر انہوں نے لڑکی کو چھوڑ دیا۔\n(تفسیر الطبری: 51,50/20)\nبہر حال اس جواب سے وہ ان کی گرفت اور ایذا سے بچ گئی اور یہ لوگ اس کے ساتھ اس کے گھر کی طرف چل دیے اور جب اس کی ماں کے پاس پہنچے تو ماں نے بچے کے منہ میں اپنا پستان داخل کیا تو بچے نے اسے قبول کر لیا، اس سے ان سب لوگوں کو بے حد خوشی ہوئی، ان میں سے ایک شخص نے جا کر فرعون کی بیوی کو یہ خوش خبری سنا دی تو فرعون کی بیوی نے موسیٰ علیہ السلام کی ماں کی طرف پیغام بھیج کر انہیں اپنے پاس بلایا، ان سے حسن سلوک کا معاملہ کیا اور بہت سا مال بھی دے دیا جبکہ اسے علم نہ تھا کہ یہی خاتون اس بچے کی حقیقی ماں ہیں، انہوں نے حسن سلوک کا یہ معاملہ اس لیے کیا تھا کہ بچے نے ان کے دودھ کو پینا قبول کر لیا تھا، آسیہ نے ان سے کہا کہ تم ہمارے پاس ہی قیام کرو اور بچے کو دودھ پلائو مگر انہوں نےا نکار کر دیا اور کہا کہ میرا شوہر بھی ہے اور دوسرے بچے بھی، لہٰذا میرے لیے آپ کے ہاں قیام کرنا ممکن نہیں ہے، البتہ اگر آپ پسند کریں تو میں اپنے گھر میں بچے کو دودھ پلاتی رہوں گی، فرعون کی بیوی نے اس بات سے اتفاق کر لیا اور اس نے تحفہ، تحائف، لباس اور احسان جزیل کا سلسلہ شروع کر دیا، موسیٰ علیہ السلام کی والدہ اپنے بچے کو لے کر خوشی خوشی واپس آئیں، اللہ تعالیٰ نے ان کے خوف کو امن میں بدل دیا تھا اور عزت و جاہ اور بے پناہ مال جو عطا فرمایا وہ اس پر مستزاد تھا۔ اس غم اور خوشی کا وقفہ بہت قلیل، یعنی صرف ایک دن اور رات کے بقدر تھا۔ وَاللہُ اَعْلَمُ\nپس پاک ہے وہ ذات جس کے ہاتھ میں سارا نظام ہے، وہ جو چاہتا ہے ہو جاتا ہے اور جو نہیں چاہتا وہ نہیں ہوتا۔ جو اس سے ڈر جائے وہ اس کے ہر غم و فکر کو دور کرکے تنگی کے بعد اسے کشادگی عطا فرما دیتا ہے، اسی لیے اس نے فرمایا: ﴿فَرَدَدْنٰهُ اِلٰۤى اُمِّهٖ كَيْ تَقَرَّ عَيْنُهَا﴾ ’’تو ہم نے (اس طریق سے) ان کو ان کی ماں کے پاس لوٹا دیا تاکہ ان کی آنکھ ٹھنڈی ہو۔‘‘ یعنی موسیٰ علیہ السلام کے ساتھ، ﴿وَلَا تَحْزَنَ﴾ ’’اور وہ غم نہ کھائیں۔‘‘ موسیٰ علیہ السلام کی وجہ سے۔ ﴿وَلِتَعْلَمَ اَنَّ وَعْدَ اللّٰهِ حَقٌّ﴾ ’’اور تاکہ وہ جان لیں کہ یقیناً اللہ کا وعدہ سچا ہے۔‘‘ جو اس نے موسیٰ علیہ السلام کے بارے میں فرمایا تھا کہ وہ انہیں واپس پہنچا دے گا اور بعد میں رسول بھی بنا دے گا۔ جب موسیٰ علیہ السلام کی تربیت میں طبعاً اور شرعاً کوئی دقیقہ فروگذاشت نہ کیا۔ ﴿وَّلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُوْنَࣖ۰۰۱۳﴾ ’’اور لیکن ان کے اکثر نہیں جانتے۔‘‘ کہ اللہ تعالیٰ کے افعال میں کیا حکمتیں اور دنیا و آخرت میں ان کے انجام کتنے اچھے ہیں، بسا اوقات ایک کام ناپسندیدہ معلوم ہوتا ہے لیکن اس کا انجام بہت ہی بہتر اور قابلِ ستائش ہوتا ہے جیسا کہ فرمایا: ﴿وَعَسٰۤى اَنْ تَكْرَهُوْا شَيْـًٔا وَّهُوَ خَيْرٌ لَّكُمْۚ وَعَسٰۤى اَنْ تُحِبُّوْا شَيْـًٔا وَّهُوَ شَرٌّ لَّكُمْؕ﴾ (البقرۃ: 216) ’’اور عجب نہیں کہ تم ایک چیز کو ناپسند کرو اور وہ تمہارے حق میں بھلی ہو اور عجب نہیں کہ تم ایک چیز کو پسند کرو اور وہ تمہارے لیے بری ہو۔‘‘ اور فرمایا: ﴿فَعَسٰۤى اَنْ تَكْرَهُوْا شَيْـًٔا وَّيَجْعَلَ اللّٰهُ فِيْهِ خَيْرًا كَثِيْرًا۰۰۱۹﴾ (النسآء: 19) ’’سو عجب نہیں کہ تم کسی چیز کو ناپسند کرو اور اللہ اس میں بہت سی بھلائیاں (پیدا) کر دے۔‘‘\nسیّدنا موسیٰ علیہ السلام کو دودھ پلانے کے لیے فرعون کی بیوی آسیہ نے دایہ کو بلوا بھیجا لیکن انھوں نے اس کا دودھ نہیں پیا تو کسی اور دایہ کو بلوایا اس کا دودھ بھی پینے سے انکار کردیا اسی طرح بہت سی دائیاں کو بلوایا گیا لیکن بچے نے کسی کا بھی دودھ پینے سے انکار کردیا، اور اللہ نے فرعون وآسیہ اور محل کے دیگر رہنے والوں کے دلوں میں ان کی ایسی شدید محبت ڈالدی کہ سبھی پریشان ہوگئے اور بات شدہ شدہ محل سے باہر نکل گئی ان کی بہن تو تمام حالات کا خاموشی سے جائزہ لے رہی تھی اس نے ہمت کی اور آگے بڑھ کر محل والوں سے کہا کہ مجھے ایک دایہ کا پتا ہے شاید بچہ اس کا دودھ پینے پر آمادہ ہوجائے اور وہ لوگ اتنے اچھے ہیں کہ بچے کی اچھی نگہداشت کریں گے محل والوں نے فورا اس دایہ کو بلایا جو موسیٰ علیہ السلام کی ماں تھیں، بچہ نے ان کے گود میں جاتے ہی لپک کر ان کا دودھ پینا شروع کردیا اور اس طرح اللہ نے انھیں دریائے نیل سے نکال کر فرعون کے ذریعہ ان کی ماں کے پاس پہنچا دیا جہاں وہ ان کی محبت کے زیر سایہ پرورش پانے لگے اور ان کی آنکھوں کو ٹھنڈک پہنچانے لگے اور اللہ نے ام موسیٰ سے جو وعدہ کیا تھا وہ پورا پورا ہوگیا اور لوگوں کو اس کی کانوں کان خبر بھی نہیں ہوئی۔"],[5235,"§سیّدہ ام موسیٰ کی بے قراری\nاُم موسیٰ نے وحی کے مطابق سیدنا موسیٰ علیہ السلام کو دریا کی موجوں کے سپرد کر تو دیا مگر بعد میں سخت بےتاب ہوگئیں۔ ماں کی مامتا چین نہ لینے دیتی تھی۔ کئی بار دل میں خیال آیا تو لوگوں سے کہہ دیں کہ میں نے بچہ دریا میں ڈال دیا ہے۔ کوئی مجھ پر مہربانی کرے اور اسے وہاں سے نکال کر مجھے واپس لادے۔ اس صورت میں کئی طرح کے خطرات نظر آرہے تھے۔ پھر وحی میں یہ وعدہ بھی کیا گیا تھا۔ کہ عنقریب وہ بچہ تمہاری طرف لوٹا دیا جائے گا۔ اس خیال سے پھر دل کو کسی قدر قرار آجاتا تھا۔ یہ اللہ ہی کی مہربانی تھی کہ اس نے ام موسیٰ کے دل کو قرار بخش دیا اور یہ راز فاش نہ ہوا۔ جبکہ اسے اب یہ یقین ہوگیا کہ بس چند دن تک میرا بچہ مجھے واپس مل جانے والا ہے۔ اگرچہ اس کی کوئی صورت اس کے ذہن میں نہیں آرہی تھی۔"],[5236,"§سیدنا موسیٰ علیہ السلام کے دوسرے بہن بھائی اور بہن کا حالات کی خبر رکھنا\nاُم موسیٰ کے تین بچے تھے۔ سب سے بڑی لڑکی تھی۔ اس کے بعد ہارون علیہ السلام پیدا ہوئے پھر ان کے ایک سال بعد موسیٰ علیہ السلام کی پیدائش ہوئی۔ سیدنا ہارون علیہ السلام کی پیدائش تک بنی اسرائیل کے بچوں کے قتل کا حکم نافذ نہیں ہوا تھا۔ لہٰذا وہ بھی زندہ تھے اور بہن تو ان سے آٹھ دس سال بڑی تھی۔ جب ام ّموسیٰ سیدنا موسیٰ علیہ السلام کو دریا برد کرچکی اور دل بےقرار ہونے لگا تو ایک احتیاطی تدبیر اس کے ذہن میں آئی کہ شاید اس تدبیر کا کسی وقت فائدہ پہنچ جائے۔ اس نے موسیٰ علیہ السلام کی بہن سے کہا کہ اس دریا کے کنارے کنارے چلی جاؤ۔ اور بچہ کو دیکھتی رہو کہ کہاں جاتا ہے۔ لیکن یہ احتیاط ملحوظ رکھنا کہ اس طریقہ سے چھپتی چھپاتی جانا کہ کسی کو یہ گمان نہ ہوسکے کہ یہ لڑکی اس ٹوکرے کی نگہداشت کر رہی ہے۔ اور اس کی ٹوہ میں لگی ہوئی ہے۔\nاس کا دوسرا مطلب یہ بھی ہوسکتا ہے کہ جب آل فرعون نے یہ تابوت دریا سے نکالا اور اس سے بچہ برآمد ہوا تو اس واقعہ کی خبر سارے شہر میں آناً فاناً پھیل گئی۔ اس وقت اُم موسیٰ نے سیدنا موسیٰ کی بہن سے کہا کہ جاؤ اور اس بچہ کا پتہ لگاؤ اور علیحدہ رہ کر دیکھنا کہ کیا ماجرا ہوتا ہے۔ لڑکی ہوشیار تھی وہ اس مقام پر پہنچ گئی جہاں بچہ کے گرد بھیڑ لگی تھی کہ وہاں وہ ایک طرف کھڑے ہو کر اور بےتعلق سی بن کر دُور سے دیکھتی رہی اور لوگوں کی باتیں سنتی رہی مگر کسی کو یہ معلوم نہ ہوسکا کہ یہ لڑکی اس بچہ کی بہن ہے۔"],[5237,"§سیدنا موسیٰ علیہ السلام کے لیے اَنا تلاش\nجب فرعون اور اس کی بیوی نے یہ طے کرلیا کہ وہ خود اس بچہ کی پرورش کریں گے۔ تو اس کے لیے دودھ پلانے والی انا کی تلاش ہونے لگی۔ مگر جو بھی انا یا دایہ لائی جاتی۔ سیدنا موسیٰ علیہ السلام کو اس کا دودھ پینے کی کچھ رغبت نہ ہوتی۔"],[5238,"§بہن کی انا کے لیے نشاندہی\nیہ بھی دراصل مشیتِ الٰہی کا ایک کرشمہ تھا کہ کئی دنوں سے بھوکا بچہ کسی بھی دایہ کا دودھ پینے سے انکار کردیتا تھا۔ فرعون کے گھر والوں کو سخت تشویش لاحق ہوئی کہ اس کی تربیت کا معاملہ ایک بڑا مسئلہ بن گیا تھا۔ وہ لوگ اس تلاش و تجسّس میں تھے کہ موسیٰ علیہ السلام کی بہن نے مشورہ کے طور پر ان سے کہا کہ میں تم کو ایک گھرانے کا پتا بتلائے دیتی ہوں۔ مجھے اُمید ہے کہ وہ اس بچہ کو پال دیں گے۔ شریف گھرانہ ہے۔ غور و فکر سے اس بچے کی تربیت بھی کریں گے۔ چنانچہ لڑکی کے مشورہ کے مطابق ام موسیٰ کو طلب کیا گیا جونہی ام موسیٰ نے بچہ اپنی چھاتی سے لگایا تو بچہ نے دودھ پینا شروع کردیا۔ اس طرح آل فرعون کی ایک بہت بڑی پریشانی دُور ہوگئی۔"],[5239,"§سیدنا موسیٰ علیہ السلام کی اپنی ماں کے پاس واپسی\nاُم موسیٰ کو وہاں محل میں رہ کر بچہ کی پرورش کے لیے کہا گیا تو اس نے یہ عذر پیش کردیا کہ گھر کی دیکھ بھال بھی اس کے ذمہ ہے۔ لہٰذا یہ یہاں رہ کر یہ خدمت سرانجام نہیں دے سکتی۔ البتہ یہ کرسکتی ہوں کہ اس بچے کو اپنے ہمراہ لے جاؤں اور اس کی پرورش کروں۔ چنانچہ آل فرعون نے ام موسیٰ کا یہ عذر قبول کرلیا وہ بچہ کو اپنے گھر لے آئی۔ اس طرح سیدنا موسیٰ علیہ السلام صرف آغوش مادری میں ہی نہ پہنچے بلکہ اپنے گھر میں ہی واپس آگئے۔ اس طرح اللہ تعالیٰ نے سیّدہ ام موسیٰ سے جو وعدہ کیا تھا۔ وہ بھی پورا ہوا اور شاہی خزانہ سے جو ماں کو معاوضہ ملتا رہا وہ اللہ تعالیٰ کا زائد انعام تھا۔"],[5240,"§آپ کی ذات پر دیندارانہ ماحول کا اثر\nیعنی اللہ کے کئے ہوئے وعدے بہرحال پورے ہو کے رہتے ہیں۔ خواہ ان کے امکانات بالکل معدوم نظر آرہے ہوں۔ یا یہ کہ اگر لوگ یہ بات نہیں جانتے کہ ظاہری اسباب کے علاوہ کچھ باطنی اسباب بھی ہوتے ہیں جو مکمل طور پر اللہ تعالیٰ کے قبضہ قدرت میں ہوتے ہیں اور اکثر لوگ یہ نہیں جان سکتے کہ اللہ تعالیٰ کے وعدے کون کون راستے اور کون کون سے مراحل طے کرتے ہوئے پورے ہوتے ہیں۔\nجب سیّدنا موسیٰ علیہ السلام نے اپنی والدہ کا دودھ پی لیا، تو فرعون نے والدہ موسیٰ سے محل میںرہنے کی استدعاء کی تا کہ بچے کی صحیح پرورش اورنگہداشت ہو سکے۔ لیکن انہوں نے کہا کہ میں اپنے خاوند اور بچوں کو چھوڑ کر یہاں نہیںرہ سکتی۔ بالآخر یہ طے پایا کہ بچے کو وہ اپنے ساتھ ہی اپنے گھر لے جائیں اور وہیں اس کی پرورش کریںاور اس کی اجرت انہیں شاہی خزانے سے دی جائے گی، سبحان اللہ! اللہ کی قدرت کےکیا کہنے،دودھ اپنے بچےکو پلائیں اور تنخواہ فرعون سےوصول کریں، رہا موسیٰ علیہ السلام کو واپس لوٹانے کا وعدہ کس احسن طریقے سے پورا فرمایا۔ ﴿فَسُبْحٰنَ الَّذِيْ بِيَدِهٖ مَلَكُوْتُ كُلِّ شَيْءٍ﴾ایک مرسل روایت میںہے۔”اس کا ریگر کی مثال، جو اپنی بنائی ہوئی چیز میں ثواب اور خیر کی نیت بھی رکھتاہے، موسیٰ علیہ السلام کی ماں کی طرح ہے جو اپنے ہی بچے کو دودھ پلاتی ہے اور اس کی اجرت بھی وصول کرتی ہے۔“(مراسیل ابی دائود)\nیعنی بہت سے کام ایسے ہوتےہیں کہ ان کے انجام کی حقیقت سےاکثر لوگ بے علم ہوتے ہیں لیکن اللہ کو اس کے حسن انجام کا علم ہوتاہے۔اسی لیے اللہ نے فرمایا:”ہو سکتا ہے جس چیز کو تم برا سمجھو، اس میں تمہارے لیے خیرہواور جس چیز کو تم پسندکرو، اس میں تمہارے لیے شر کاپہلو ہو۔“(البقرة:216)دوسرے مقام پر فرمایا”ہو سکتا ہے تم کسی چیزکو برا سمجھو، اور اللہ اس میں تمہارے لیےخیر کثیر پیدا فرما دے۔“ (النساء:19)اس لیے انسان کی بہتری اسی میں ہے کہ وہ اپنی پسند و نا پسند سے قطع نظر ہرمعاملےمیںاللہ اور اس کے رسول کے احکام کی پابندی کرے کہ اسی میںاس کے لیے خیراور حسن انجام ہے۔\nوَ اَصْبَحَ فُؤَادُ اُمِّ مُوْسٰى فٰرِغًا: جب موسیٰ علیہ السلام کی والدہ کو معلوم ہوا کہ اس کا بچہ توفرعون کے ہاتھ میں پہنچ گیا ہے توغم و اندوہ کے باعث اس کی عقل جواب دے گئی اور اس کے دل پر بار بار یہ خدشہ نمودار ہوتا تھا کہ اب تو بچے کے بچاؤ کی کوئی صورت نظر نہیں آرہی ہے اگر موسیٰ علیہ السلام کی والدہ کے دل کو ہم مضبوط نہ کرتے تو اس نے اس راز کو فاش کردینا تھا کہ یہ تو اس کا بیٹا ہے اور شدت غم کے باعث اس کی زبان پر یہ جملہ بلااختیار آجاتا، ہائے میرے بچے ہم نے اس کی والدہ کو یقین دلاتے ہوئے آگاہ کیا کہ ایک نہ ایک دن ہم اس لڑکے کو تیرے پاس لوٹائیں گے اور اسے منصب رسالت کے اعزاز سے ہم کنار کریں گے۔\nوَ قَالَتْ لِاُخْتِهٖ قُصِّيْهِ١ٞ فَبَصُرَتْ بِهٖ عَنْ جُنُبٍ : موسیٰ کی والدہ نے موسیٰ کی بڑی ہمشیرہ کو ایک اہم ذمہ داری سونپ کر اسے حکم دیا کہ آپ ان باتوں کو محفوظ رکھیں جو اس کے بارے میں کہی جارہی ہیں اور اس نومولود بھائی کے پیچھے پیچھے رہیں اور اس کے بارے میں اطلاع دیں چنانچہ لڑکی اس کو دور سے دیکھتی رہی ان کی نظر سے خود کو تحفظ عطا کررکھا تھا انھیں اس کے بارے میں علم نہ تھا کہ وہ اپنے بھائی کے تعاقب میں پیچھے پیچھے جارہی ہے تاکہ بھائی کے بارے میں معلومات حاصل ہوں دور سے اپنے بھائی کو دیکھ رہی تھی جبکہ فرعون کے مقرر کردہ سپاہیوں کو اس کے بارے میں معلوم نہ تھا، کہ وہ پیچھے پیچھے حالات کا جائزہ لے رہی ہے اور یہ بھی معلوم نہ تھا کہ یہ لڑکی اس بچے کی بہن ہے اب ان اسباب کو بیان کرنا مقصود ہے کہ کس طرح نومولود موسیٰ علیہ السلام کو اس کی حقیقی والدہ کی جانب لوٹایا گیا۔\nوَ حَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِنْ قَبْلُ فَقَالَتْ هَلْ اَدُلُّكُمْ : ہم نے شروع سے ہی موسیٰ علیہ السلام پر دودھ پلانے والیوں کو حرام قرار دیا تھا تو اس دوران موسیٰ علیہ السلام کی بہن نے جب اپنے حقیقی بھائی کے دودھ پلانے کے سلسلہ میں اس قدر زبردست اہتمام کا ملاحظہ کیا تو اس نے کہا کیا تم چاہتے ہو کہ میں تمہیں ایسے گھرانے کے بارے میں آگاہ کروں جو اس بچے کی کفالت بہترین انتظامات کے ساتھ کر پائیں گے اور اس کی خدمت کرنے میں ہرگز کوتاہی نہیں کریں گے۔\nفَرَدَدْنٰهُ اِلٰۤى اُمِّهٖ كَيْ تَقَرَّ عَيْنُهَا : چنانچہ ہم نے موسیٰ علیہ السلام کو اس کی والدہ کی جانب لوٹادیا جب کہ قبل ازیں آل فرعون نے اس کو دریا کی لہروں سے اٹھایا تھا کہ اس کی والدہ کی آنکھ کو ٹھنڈک نصیب ہو جب وہ اسے دیکھے گی اور جدائی کا غم دور ہوجائے گا اس طرح یہ حقیقت اس کی آنکھوں کے سامنے نکھر کر آجائے گی کہ اللہ تعالیٰ نے جو وعدہ اس سے کیا تھا وہ سچا وعدہ تھا اب ہم اس کو آپ کی جانب لوٹا رہے ہیں اور اس کو منصب رسالت پر متمکن کرنے والے ہیں چنانچہ والدہ نے اس کی تربیت مناسب انداز سے کی کوئی دقیقہ فروگذاشت نہ کیا اخلاق فاضلہ کا ہر طرح خیال رکھا اور اسے معلوم ہوگیا کہ اسے مستقبل میں مقام رسالت پر متمکن کیا جائے گا جب کہ اکثر لوگ اللہ کے فیصلوں سے آگاہی نہیں رکھتے ہیں جیسا کہ موسیٰ علیہ السلام کا یہ واقعہ کہ اسے دریائے نیل کی لہروں کے سپرد کیا گیا بعدازاں اسے ان کی والدہ کی جانب اعزاز و اکرام کے ساتھ لوٹایا گیا بعدازاں اسے نہ صرف دنیوی وجاہت کا اعزاز عطا ہوا بلکہ اُخروی وجاہت سے بھی شاد کام کیا گیا۔\n﴿وَلَمَّا بَلَغَ اَشُدَّهٗ وَاسْتَوٰۤى اٰتَيْنٰهُ حُكْمًا وَّعِلْمًاؕ وَكَذٰلِكَ نَجْزِي الْمُحْسِنِيْنَ۰۰۱۴ وَدَخَلَ الْمَدِيْنَةَ عَلٰى حِيْنِ غَفْلَةٍ مِّنْ اَهْلِهَا فَوَجَدَ فِيْهَا رَجُلَيْنِ يَقْتَتِلٰنِ١ٞؗ هٰذَا مِنْ شِيْعَتِهٖ وَهٰذَا مِنْ عَدُوِّهٖۚ فَاسْتَغَاثَهُ الَّذِيْ مِنْ شِيْعَتِهٖ عَلَى الَّذِيْ مِنْ عَدُوِّهٖۙ فَوَكَزَهٗ مُوْسٰى فَقَضٰى عَلَيْهِ١ٞؗ قَالَ هٰذَا مِنْ عَمَلِ الشَّيْطٰنِؕ اِنَّهٗ عَدُوٌّ مُّضِلٌّ مُّبِيْنٌ۰۰۱۵ قَالَ رَبِّ اِنِّيْ ظَلَمْتُ نَفْسِيْ فَاغْفِرْ لِيْ فَغَفَرَ لَهٗؕ اِنَّهٗ هُوَ الْغَفُوْرُ الرَّحِيْمُ۰۰۱۶ قَالَ رَبِّ بِمَاۤ اَنْعَمْتَ عَلَيَّ فَلَنْ اَكُوْنَ ظَهِيْرًا لِّلْمُجْرِمِيْنَ۰۰۱۷﴾\nاور جب وہ (موسیٰ) اپنی جوانی کو پہنچا اور (عقل و شعور میں کامل اور) پورا طاقتور ہو گیا تو ہم نے اسے قوت فیصلہ اور علم دیا، اور ہم نیکی کرنے والوں کو اسی طرح جزا دیتے ہیں⟦14⟧ اور وہ شہر میں ایسے وقت داخل ہوا جبکہ اہل شہر غفلت میں تھے، پھر اس نے شہر میں دو آدمیوں کو باہم لڑتے پایا، یہ (ایک تو) اس کے اپنے گروہ میں سے تھا اور یہ (دوسرا) اس کے دشمنوں میں سے تھا، پھر جو اس کے اپنے گروہ میں سے تھا اس نے موسیٰ سے اس شخص کے خلاف مدد مانگی جو اس کے دشمنوں میں سے تھا، چنانچہ موسیٰ نے اسے گھونسا مارا تو اس کا کام تمام کر دیا (پھر) کہا: یہ (قتل) شیطان کے عمل سے ہے، بلاشبہ وہ گمراہ کرنے والا کھلم کھلا دشمن ہے⟦15⟧ موسیٰ نے کہا:اے میرے رب! بے شک میں نے اپنی جان پر ظلم کیا ہے، لہٰذا تو میری مغفرت فرما، چنانچہ اللہ نے اسے بخش دیا، بلاشبہ وہ بہت بخشنے والا، نہایت رحم کرنے والا ہے⟦16⟧ موسیٰ نے کہا: اے میرے رب! چونکہ تو نے مجھ پر انعام کیا ہے، لہٰذا میں مجرموں کا مدد گار ہر گز نہیں بنوں گا⟦17⟧"]])